INSERT INTO embeddings_queue VALUES(132,'2025-08-26 14:03:20',0,'persistent://default/default/cee23c0b-1653-41fb-ab9b-099a592a4170','STORMSChecklist.txt_126',X'','FLOAT32','{"type": "txt", "source": "STORMSChecklist.txt", "chroma:document": "STORMSChecklist:   is_a: NamedEntity   description: A checklist of items that should be reported in a microbiome study. Try and provide a value for ALL items. If an item is not reported, say NOT REPORTED.   attributes:     abstract_structured_or_unstructured:       description: Abstract should include information on background, methods, results, and conclusions in structured or unstructured format.       range: string     abstract_study_design:       description: Study design in abstract.       range: string     abstract_sequencing_methods:       description: Strategy used for metagenomic classification.       range: string     abstract_specimens:       description: Body site(s) studied.       range: string       multivalued: true     introduction_background_and_rationale:       description: Underlying background, scientific evidence, or theory driving the current hypothesis as well as the study objectives.       range: string     introduction_hypotheses:       description: Pre-specified hypothesis. If the study is exploratory, state any pre-specified study objectives.       range: string     methods_study_design:       description: Study design.       range: string     methods_participants:       description: Population of interest, and the method by which participants are sampled from that population.       range: string     methods_geographic_location:       description: Geographic region(s) where participants were sampled from.       range: string       multivalued: true     methods_relevant_dates:       description: Start and end dates for recruitment, follow-up, and data collection.       range: string     methods_eligibility_criteria:       description: Criteria for inclusion and exclusion of recruited participants.       range: string       multivalued: true     methods_antibiotics_usage:       description: What is known about antibiotics usage before or during sample collection.       range: string       multivalued: true     methods_analytic_sample_size:       description: How the final analytic sample size was calculated, including the number of cases and controls if relevant, and reasons for dropout at each stage of the study.       range: string     methods_longitudinal_studies:       description: For longitudinal studies, how many follow-ups were conducted, sample size at follow-up by group or condition, and any loss to follow-up.       range: string       multivalued: true     methods_matching:       description: For matched studies, matching criteria.       range: string       multivalued: true     methods_ethics:       description: Name of the institutional review board that approved the study and protocols, protocol number and date of approval, and procedures for obtaining informed consent from participants.       range: string       multivalued: true     methods_laboratory_methods:       description: Laboratory/center where laboratory work was done.       range: string     methods_specimen_collection:       description: Body site(s) sampled from and how specimens were collected.       range: string       multivalued: true     methods_shipping:       description: How samples were stored and shipped to the laboratory.       range: string     methods_storage:       description: How the laboratory stored samples, including time between collection and storage and any preservation buffers or refrigeration used.       range: string     methods_dna_extraction:       description: DNA extraction method, including kit and version if relevant.       range: string     methods_human_dna_sequence_depletion_or_microbial_dna_enrichment:       description: Whether human DNA sequence depletion or enrichment of microbial or viral DNA was performed.       range: boolean     methods_primer_selection:       description: Primer selection and DNA amplification methods as well as variable region sequenced (if applicable).       range: string       multivalued: true     methods_positive_controls:       description: Any positive controls (mock communities) if used.       range: string       multivalued: true     methods_negative_controls:       description: Any negative controls if used.       range: string       multivalued: true     methods_contaminant_mitigation_and_identification:       description: Any laboratory or computational methods used to control for or identify microbiome contamination from the environment, reagents, or laboratory.       range: string       multivalued: true     methods_replication:       description: Any biological or technical replicates included in the sequencing, including which steps were replicated between them.       range: string       multivalued: true     methods_sequencing_strategy:       description: Major divisions of strategy, such as shotgun or amplicon sequencing.       range: string       multivalued: true     methods_sequencing_methods:       description: Whether experimental quantification was used (QMP/cell count based, spike-in based) or whether relative abundance methods were applied.       range: boolean     methods_batch_effects:       description: Any blocking or randomization used in study design to avoid confounding of batches with exposures or outcomes. Includes any likely sources of batch effects, if known.       range: string       multivalued: true     methods_metatranscriptomics:       description: Whether any mRNA enrichment was performed and whether/how retrotranscription was performed prior to sequencing. Includes size range of isolated transcripts. Also, whether the sequencing library was stranded or not. Includes details on sequencing methods and platforms.       range: boolean     methods_metaproteomics:       description: Which protease was used for digestion. Includes details on proteomic methods and platforms (e.g. LC-MS/MS, instrument type, column type, mass range, resolution, scan speed, maximum injection time, isolation window, normalised collision energy, and resolution).       range: string     methods_metabolomics:       description: The analytic method used (such as nuclear magnetic resonance spectroscopy or mass spectrometry). For mass spectrometry, includes which fractions were obtained (polar and/or non polar) and how these were analyzed. Includes also details on metabolomics methods and platforms (e.g. derivatization, instrument type, injection type, column type and instrument settings).       range: string     results_descriptive_data:       description: Characteristics of study participants (e.g. dietary, demographic, clinical, social) and information on exposures and potential confounders.       range: string       multivalued: true     results_microbiome_data:       description: Descriptive findings for microbiome analyses with all applicable outcomes and covariates.       range: string       multivalued: true     results_taxonomy:       description: Taxonomy using standardized taxon classifications that are sufficient to uniquely identify taxa.       range: string     results_differential_abundance:       description: Results of differential abundance analysis by the variable of interest and (if applicable) by time, clearly indicating the direction of change and total number of taxa tested.       range: string       multivalued: true     results_other_data_types:       description: Other data analyzed--e.g. metabolic function, functional potential, MAG assembly, and RNAseq.       range: string       multivalued: true     results_other_statistical_analysis:       description: Any statistical data analysis not covered above.       range: string     discussion_key_results:       description: Key results with reference to study objectives.       range: string       multivalued: true     discussion_interpretation:       description: A cautious overall interpretation of results considering objectives, limitations, multiplicity of analyses, results from similar studies, and other relevant evidence.       range: string     discussion_limitations:       description: Limitations of the study, taking into account sources of potential bias or imprecision.       range: string       multivalued: true     discussion_bias:       description: Any potential for bias to influence study findings.       range: string     discussion_generalizability:       description: The generalizability (external validity) of the study results.       range: string     discussion_ongoing_future_work:       description: Potential future research or ongoing research based on the study''s findings.       range: string     other_information_funding:       description: The source of funding and the role of the funders for the present study and, if applicable, for the original study on which the present article is based.       range: string     other_information_acknowledgements:       description: Acknowledgements of those who contributed to the research but did not meet criteria for authorship.       range: string     other_information_conflicts_of_interest:       description: A conflicts of interest statement.       range: string     other_information_supplements:       description: Where supplements may be accessed and what materials they contain.       range: string     other_information_supplementary_data:       description: Supplementary data files of results with all taxa and all outcome variables analyzed. Includes the taxonomic level of all taxa.       range: string"}');
