INSERT INTO embeddings_queue VALUES(138,'2025-08-26 14:03:20',0,'persistent://default/default/cee23c0b-1653-41fb-ab9b-099a592a4170','TableCell.txt_132',X'','FLOAT32','{"type": "txt", "source": "TableCell.txt", "chroma:document": "TableCell:   is_a: NamedEntity   description: >-     An individual cell in the table, containing a numerical value and optional qualifiers.   attributes:     row_index:       description: Numeric index of this row (starting from 0 or 1).       range: integer     column_index:       description: Numeric index of this column (starting from 0 or 1).       range: integer     value:       description: Numeric value in this cell.       range: float     unit:       description: Optional unit.       range: string       annotations:         prompt.examples: mg, kg, mL     note:       description: Optional note or comment about this particular cell.       range: string"}');
