INSERT INTO embeddings_queue VALUES(349,'2025-08-26 14:06:32',0,'persistent://default/default/8efdc35c-b2fa-49c8-9bef-a6656316682f','MetricOrIndicatorToDisease.txt_63',X'','FLOAT32','{"type": "txt", "source": "MetricOrIndicatorToDisease.txt", "chroma:document": "  MetricOrIndicatorToDiseaseRelationship:     is_a: Triple     description: >-       A triple where the subject is a MetricOrIndicator and where the object is       a Disease. A triple where the subject is an experimental metric, the       object is a disease or condition, and the predicate describes the       relationship between the metric and the disease, usually USED_TO_MODEL.     slot_usage:       subject:         range: MetricOrIndicator       object:         range: Disease       predicate:         range: MetricOrIndicatorToDiseasePredicate       subject_qualifier:         description: >-           An optional qualifier or modifier for the experimental metric.           This may include the method of measurement or the specific assay used.       object_qualifier:         description: >-           An optional qualifier or modifier for the disease or condition.           This may include the stage or subtype of the disease.       direct_or_indirect:         description: >-           Whether the relationship between the metric and the disease is direct           or indirect. UNKNOWN if this is not specified in the text           or is unclear.         range: string       association:         description: >-           The type of any observed association between the value of the metric           and the disease. May be \"positive\", \"negative\", \"inconclusive\", or           UNKNOWN if this is not specified in the text or is unclear.         range: string      MetricOrIndicatorToDiseasePredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the MetricOrIndicatorToDisease relationships.      MetricOrIndicator:     is_a: NamedEntity     description: >-       The name of an experimental metric, sign, symptom, or outcome used to       measure the effects of treatments on symptoms or diagnostics, or of the       progression of Alzheimer''s disease and related dementias. In experimental       animal models these are analogues of cognitive impairment or indicators of       disease progression modeling those observed in humans.     id_prefixes:       - MAXO       - MONDO       - MP       - NBO       - NCIT       - MESH       - HP     annotations:       annotators: >-         sqlite:obo:maxo, sqlite:obo:mondo, sqlite:obo:mp, sqlite:obo:nbo,         sqlite:obo:ncit, sqlite:obo:hp, sqlite:obo:mesh, bioportal:SNOMEDCT       prompt.examples: Amyloid beta (A\u03b2) levels, Morris water maze test, tau phosphorylation, neurofibrillary tangles, and cognitive decline.      Disease:     is_a: NamedEntity     description: >-       The name of a disease or condition.     id_prefixes:       - MONDO     annotations:       annotators: sqlite:obo:mondo       prompt.examples: Alzheimer''s disease, Parkinson''s disease, Huntington''s disease "}');
INSERT INTO embeddings_queue VALUES(350,'2025-08-26 14:06:32',0,'persistent://default/default/8efdc35c-b2fa-49c8-9bef-a6656316682f','MetricOrIndicatorToTaxon.txt_64',X'','FLOAT32','{"type": "txt", "source": "MetricOrIndicatorToTaxon.txt", "chroma:document": "  MetricOrIndicatorToTaxonRelationship:     is_a: Triple     description: >-       A triple where the subject is a MetricOrIndicator and where the object is       a Taxon. A triple where the subject is an experimental metric, the object       is an taxon, metric, and the predicate describes the relationship between       the metric and the taxon, usually MEASURED_IN.     slot_usage:       subject:         range: MetricOrIndicator       object:         range: Taxon       predicate:         range: MetricOrIndicatorToTaxonPredicate       subject_qualifier:         description: >-           An optional qualifier or modifier for the experimental metric.           This may include the method of measurement or the specific assay used.       object_qualifier:         description: >-           An optional qualifier or modifier for the taxon.           This may include a strain or genetic background of the model organism.       direct_or_indirect:         description: >-           Whether the relationship between the metric and the taxon is direct           or indirect. UNKNOWN if this is not specified in the text           or is unclear.         range: string      MetricOrIndicatorToTaxonPredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the MetricOrIndicatorToTaxon relationships.      MetricOrIndicator:     is_a: NamedEntity     description: >-       The name of an experimental metric, sign, symptom, or outcome used to       measure the effects of treatments on symptoms or diagnostics, or of the       progression of Alzheimer''s disease and related dementias. In experimental       animal models these are analogues of cognitive impairment or indicators of       disease progression modeling those observed in humans.     id_prefixes:       - MAXO       - MONDO       - MP       - NBO       - NCIT       - MESH       - HP     annotations:       annotators: >-         sqlite:obo:maxo, sqlite:obo:mondo, sqlite:obo:mp, sqlite:obo:nbo,         sqlite:obo:ncit, sqlite:obo:hp, sqlite:obo:mesh, bioportal:SNOMEDCT       prompt.examples: Amyloid beta (A\u03b2) levels, Morris water maze test, tau phosphorylation, neurofibrillary tangles, and cognitive decline.      Taxon:     is_a: NamedEntity     description: >-       The taxonomic group or species of a model organism.     id_prefixes:       - NCBITAXON     annotations:       annotators: sqlite:obo:ncbitaxon       prompt.examples:  human, mouse, rat, Rhesus macaque, canine, marmoset, fruit fly, C. elegans, S. cerevisiae "}');
