INSERT INTO embeddings_queue VALUES(380,'2025-08-26 14:06:32',0,'persistent://default/default/8efdc35c-b2fa-49c8-9bef-a6656316682f','ProteinHasAnnotationGOTerm.txt_94',X'','FLOAT32','{"type": "txt", "source": "ProteinHasAnnotationGOTerm.txt", "chroma:document": "  ProteinHasAnnotationGOTermRelationship:     is_a: Triple     description: >-       A triple where the subject is a protein and the object is a GO term.     slot_usage:       subject:         range: Protein       object:         range: GOTerm       predicate:         range: ProteinHasAnnotationGOTermPredicate       subject_qualifier:         description: >-           An optional qualifier or modifier for the protein.         range: string       object_qualifier:         description: >-           An optional qualifier or modifier for the GO term.         range: string     annotations:       prompt.examples: >-         RPS7B has annotation structural constituent of ribosome;         granzyme M has annotation endopeptidase activity;         Mknk1 has annotation nucleoplasm    ProteinHasAnnotationGOTermPredicate:     is_a: RelationshipType     slot_usage:       label:         description: The predicate for the ProteinHasAnnotationGOTerm relationships.       id:         pattern: ''has annotation''    Protein:     is_a: NamedEntity     description: >-       Technically gene or protein. Can also be UniProt accession, etc     id_prefixes:       - PR     annotations:       annotators: bioportal:hgnc-nr, sqlite:obo:pr       prompt.examples: >-         Klp61F, GATA binding protein 3, S-formylglutathione, ydrolase, RPS7B,         granzyme M, Mknk1    GOTerm:     is_a: NamedEntity     description: The Gene Ontology term     id_prefixes:       - GO     annotations:       annotators: sqlite:obo:go       prompt.examples: >-         nuclear axial expansion, intracellular transport,         medial surface of mandible, ribosomal subunit export from nucleus,         pole cell development, tubulin complex, proteasome complex, cytoplasm,         keratohyalin granule, catalytic activity, amine binding,         peptide receptor activity, oxygen carrier activity,         structural constituent of cytoskeleton, cytosol,         plasma cell differentiation, small-subunit processome,         structural constituent of ribosome, endopeptidase activity,         nucleoplasm "}');
