INSERT INTO embeddings_queue VALUES(406,'2025-08-26 14:06:32',0,'persistent://default/default/8efdc35c-b2fa-49c8-9bef-a6656316682f','UnitMeasuresUnit.txt_120',X'','FLOAT32','{"type": "txt", "source": "UnitMeasuresUnit.txt", "chroma:document": "  UnitMeasuresUnitRelationship:     is_a: Triple     slot_usage:       subject:         range: Unit       object:         range: Unit       predicate:         range: UnitMeasuresUnitPredicate       value:         description: the value of the measurement         range: float      UnitMeasuresUnitPredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the UnitMeasuresUnit relationships.       id:         pattern: ''measures''    Unit:     is_a: NamedEntity     id_prefixes:       - UO       - NCIT     annotations:       annotators: sqlite:obo:uo, sqlite:obo:ncit "}');
INSERT INTO embeddings_queue VALUES(407,'2025-08-26 14:06:32',0,'persistent://default/default/8efdc35c-b2fa-49c8-9bef-a6656316682f','UnitQuantity.txt_121',X'','FLOAT32','{"type": "txt", "source": "UnitQuantity.txt", "chroma:document": "  UnitQuantityRelationship:     is_a: Triple     slot_usage:       subject:         range: Unit       object:         range: Quantity       predicate:         range: UnitQuantityPredicate      UnitQuantityPredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the UnitQuantity relationships.    Unit:     is_a: NamedEntity     id_prefixes:       - UO       - NCIT       - dbpediaont     annotations:       annotators: sqlite:obo:uo, sqlite:obo:ncit, sqlite:obo:dbpediaont       prompt.examples: grams, cups    Quantity:     is_a: NamedEntity     description: the quantity of the ingredient     attributes:       value:         description: the value of the quantity         range: float         annotations:           prompt.examples: 2 lbs "}');
INSERT INTO embeddings_queue VALUES(408,'2025-08-26 14:06:32',0,'persistent://default/default/8efdc35c-b2fa-49c8-9bef-a6656316682f','VariableCausesVariable.txt_122',X'','FLOAT32','{"type": "txt", "source": "VariableCausesVariable.txt", "chroma:document": "  VariableCausesVariableRelationship:     is_a: Triple     slot_usage:       subject:         range: Variable       object:         range: Variable       predicate:         range: VariableCausesVariablePredicate       study:         range: Study    VariableCausesVariablePredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the VariableCausesVariable relationships.       id:         pattern: ''causes''    Variable:     is_a: NamedEntity     id_prefixes:       - ENVO       - PATO     annotations:       annotators: sqlite:obo:envo, bioportal:bero, bioportal:envthes, sqlite:obo:pato "}');
INSERT INTO embeddings_queue VALUES(424,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','all_disease_grounding.txt_0',X'','FLOAT32','{"type": "txt", "source": "all_disease_grounding.txt", "content": "id: http://w3id.org/ontogpt/all_disease_grounding\ndefault_range: string\nname: all_disease_grounding\ntitle: Template for grounding disease names\ndescription: Template for grounding disease names\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ontogpt: http://w3id.org/ontogpt/\n  MONDO: http://purl.obolibrary.org/obo/mondo.owl\n  OMIM: http://purl.bioontology.org/ontology/OMIM/\nimports:\n  - ontogpt:core\n  - linkml:types\nclasses:\n  Disease:\n    is_a: NamedEntity\n    description: The name of a disease, with specific subtype if provided.\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo, bioportal:OMIM\n      prompt.examples: neurothekoma, retinal vasculitis,\n        chicken monocytic leukemia, neoplasm of spinal cord,\n        moyamoya disease 3, noninsulin-dependent diabetes mellitus\n        with deafness, Teebi hypertelorism syndrome 1,\n        multiple pterygium syndrome escobar variant,\n        Otopalatodigital syndrome type II,\n        Alzheimer disease type 3\n"}');
INSERT INTO embeddings_queue VALUES(425,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','alzrd.txt_1',X'','FLOAT32','{"type": "txt", "source": "alzrd.txt", "content": "id: http://w3id.org/ontogpt/alzrd\ndefault_range: string\nname: alzrd\ntitle: Template for extracting Alzheimer''s Disease Phenotypes\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  Template for extracting phenotypes of Alzheimer''s disease and related\n  dementias along with experimental metrics and model organisms.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ontogpt: http://w3id.org/ontogpt/\n  MONDO: http://purl.obolibrary.org/obo/mondo.owl\n  MAXO: http://purl.obolibrary.org/obo/maxo.owl\n  MP: http://purl.obolibrary.org/obo/mp/mp-international.owl\n  NBO: http://purl.obolibrary.org/obo/nbo.owl\n  NCIT: http://purl.obolibrary.org/obo/ncit.owl\n  HP: http://purl.obolibrary.org/obo/hp/hp-international.owl\n  NCBITAXON: http://purl.obolibrary.org/obo/ncbitaxon.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n  ENVO: http://purl.obolibrary.org/obo/envo.owl\n  MESH: http://identifiers.org/mesh/\nimports:\n  - ontogpt:core\n  - linkml:types\nclasses:\n  MetricOrIndicatorToTaxonRelationship:\n    is_a: Triple\n    description: >-\n      A triple where the subject is a MetricOrIndicator and where the object is\n      a Taxon. A triple where the subject is an experimental metric, the object\n      is an taxon, metric, and the predicate describes the relationship between\n      the metric and the taxon, usually MEASURED_IN.\n    slot_usage:\n      subject:\n        range: MetricOrIndicator\n      object:\n        range: Taxon\n      predicate:\n        range: MetricOrIndicatorToTaxonPredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the experimental metric.\n          This may include the method of measurement or the specific assay used.\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the taxon.\n          This may include a strain or genetic background of the model organism.\n      direct_or_indirect:\n        description: >-\n          Whether the relationship between the metric and the taxon is direct\n          or indirect. UNKNOWN if this is not specified in the text\n          or is unclear.\n        range: string\n  MetricOrIndicatorToTaxonPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetricOrIndicatorToTaxon relationships.\n  MetricOrIndicatorToDiseaseRelationship:\n    is_a: Triple\n    description: >-\n      A triple where the subject is a MetricOrIndicator and where the object is\n      a Disease. A triple where the subject is an experimental metric, the\n      object is a disease or condition, and the predicate describes the\n      relationship between the metric and the disease, usually USED_TO_MODEL.\n    slot_usage:\n      subject:\n        range: MetricOrIndicator\n      object:\n        range: Disease\n      predicate:\n        range: MetricOrIndicatorToDiseasePredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the experimental metric.\n          This may include the method of measurement or the specific assay used.\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the disease or condition.\n          This may include the stage or subtype of the disease.\n      direct_or_indirect:\n        description: >-\n          Whether the relationship between the metric and the disease is direct\n          or indirect. UNKNOWN if this is not specified in the text\n          or is unclear.\n        range: string\n      association:\n        description: >-\n          The type of any observed association between the value of the metric\n          and the disease. May be \"positive\", \"negative\", \"inconclusive\", or\n          UNKNOWN if this is not specified in the text or is unclear.\n        range: string\n  MetricOrIndicatorToDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetricOrIndicatorToDisease relationships.\n  Disease:\n    is_a: NamedEntity\n    description: >-\n      The name of a disease or condition.\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n      prompt.examples: Alzheimer''s disease, Parkinson''s disease, Huntington''s disease\n  MetricOrIndicator:\n    is_a: NamedEntity\n    description: >-\n      The name of an experimental metric, sign, symptom, or outcome used to\n      measure the effects of treatments on symptoms or diagnostics, or of the\n      progression of Alzheimer''s disease and related dementias. In experimental\n      animal models these are analogues of cognitive impairment or indicators of\n      disease progression modeling those observed in humans.\n    id_prefixes:\n      - MAXO\n      - MONDO\n      - MP\n      - NBO\n      - NCIT\n      - MESH\n      - HP\n    annotations:\n      annotators: >-\n        sqlite:obo:maxo, sqlite:obo:mondo, sqlite:obo:mp, sqlite:obo:nbo,\n        sqlite:obo:ncit, sqlite:obo:hp, sqlite:obo:mesh, bioportal:SNOMEDCT\n      prompt.examples: Amyloid beta (A\u03b2) levels, Morris water maze test, tau phosphorylation, neurofibrillary tangles, and cognitive decline.\n  Diagnostic:\n    is_a: NamedEntity\n    description: >-\n      The name of a diagnostic procedure or test.\n    id_prefixes:\n      - MAXO\n      - NCIT\n      - MESH\n    annotations:\n      annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh\n      prompt.examples: MRI, PET scan, lumbar puncture, blood test, biopsy.\n  Taxon:\n    is_a: NamedEntity\n    description: >-\n      The taxonomic group or species of a model organism.\n    id_prefixes:\n      - NCBITAXON\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n      prompt.examples:  human, mouse, rat, Rhesus macaque, canine, marmoset, fruit fly, C. elegans, S. cerevisiae\n  Chemical:\n    is_a: NamedEntity\n    description: >-\n      The name of a chemical, drug, or other substance.\n    id_prefixes:\n      - CHEBI\n      - MESH\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:mesh\n      prompt.examples: donepezil, A\u03b242, A\u03b240, tau, insulin, caffeine, nicotine, alcohol\n  EnvironmentalExposure:\n    is_a: NamedEntity\n    description: >-\n      The name of an environmental exposure or condition.\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo\n      prompt.examples: pesticides, chronic stress, air pollution, heavy metals, radiation, heat stress"}');
INSERT INTO embeddings_queue VALUES(426,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','biological_process.txt_2',X'','FLOAT32','{"type": "txt", "source": "biological_process.txt", "content": "id: https://w3id.org/ontogpt/biological_process\ndefault_range: string\nname: biological-process-template\ntitle: Biological Process Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO-CAMs\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  CL: http://purl.obolibrary.org/obo/CL_\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  bp: http://w3id.org/ontogpt/biological-process-template\n  linkml: https://w3id.org/linkml/\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  GeneMolecularActivityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: MolecularActivity\n      predicate:\n        range: GeneMolecularActivityPredicate\n      biological_process:\n        range: BiologicalProcess\n\n  GeneMolecularActivityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneMolecularActivity relationships.\n  \n  BiologicalProcessSubclassOfBiologicalProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: BiologicalProcessSubclassOfBiologicalProcessPredicate\n\n  BiologicalProcessSubclassOfBiologicalProcessPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessSubclassOfBiologicalProcess relationships.\n      id:\n        pattern: ''subclass of''\n\n  BiologicalProcessInputsChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: BiologicalProcessInputsChemicalEntityPredicate\n\n  BiologicalProcessInputsChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessInputsChemicalEntity relationships.\n      id:\n        pattern: ''inputs''\n\n  BiologicalProcessOutputsChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: BiologicalProcessOutputsChemicalEntityPredicate\n\n  BiologicalProcessOutputsChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessOutputsChemicalEntity relationships.\n      id:\n        pattern: ''outputs''\n\n  BiologicalProcessGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: Gene\n      predicate:\n        range: BiologicalProcessGenePredicate\n\n  BiologicalProcessGenePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessGene relationships.\n\n  MolecularActivityInvolvedInBiologicalProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MolecularActivity\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: MolecularActivityInvolvedInBiologicalProcessPredicate\n\n  MolecularActivityInvolvedInBiologicalProcessPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MolecularActivityInvolvedInBiologicalProcess relationships.\n      id:\n        pattern: ''involved in''\n\n  BiologicalProcess:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: the name of the biological process\n      description:\n        description: a textual description of the biological process\n      synonyms:\n        description: alternative names of the biological process\n        multivalued: true\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: sqlite:obo:hgnc\n\n  CellType:\n    is_a: NamedEntity\n    id_prefixes:\n      - CL\n    annotations:\n      annotators: sqlite:obo:cl\n\n  MolecularActivity:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi"}');
INSERT INTO embeddings_queue VALUES(427,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','biotic_interaction.txt_3',X'','FLOAT32','{"type": "txt", "source": "biotic_interaction.txt", "content": "id: https://w3id.org/ontogpt/biotic_interaction\ndefault_range: string\nname: biotic-interaction-template\ntitle: Biotic Interaction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for biotic interactions\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MESH: http://identifiers.org/mesh/\n  NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_\n  RO: http://purl.obolibrary.org/obo/RO_\n  bp: http://w3id.org/ontogpt/biotic-interaction-template\n  col: https://www.catalogueoflife.org/data/taxon/\n  gbif: https://www.gbif.org/species/\n  itis: https://www.itis.gov/servlet/SingleRpt/SingleRpt?search_topic=TSN&search_value=\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  TaxonTaxonRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Taxon\n      predicate:\n        range: TaxonTaxonPredicate\n      environment:\n        description: >-\n          The environment in which the interaction occurs.\n          This should be a short description of the environment, e.g., \"forest\",\n          \"desert\", \"ocean\", etc. If the environment is not specified, leave\n          this field blank. The value here should be no more than a few words.\n        range: string\n    annotations:\n      prompt.examples: Carcharodon carcharias eats elephant seal; Pandarus sinuatus parasitizes Carcharodon carcharias; orca eats Carcharodon carcharias\n\n  TaxonTaxonPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - MESH\n      - ECOCORE\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:ro, sqlite:obo:bero\n      #prompt.example: eat, competes with, parasitizes, subsist on a diet, kill, compete, prey consists, hunting, killed by, compete for, dominate, competitors\n    attributes:\n      label:\n        description: The predicate for the TaxonTaxon relationships.\n\n  Taxon:\n    is_a: NamedEntity\n    description: A name of a single plant or animal taxon.\n    annotations:\n      prompt.examples: bear, grass, Ursoidea, Halichoerus grypus, Panicum virgatum, Odocoileus virginianus sleeps on Panicum virgatum\n    # id_prefixes:\n    #   - NCBITaxon\n    #   - SNOMEDCT\n    # annotations:\n    #   annotators: bioportal:SNOMEDCT"}');
INSERT INTO embeddings_queue VALUES(428,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','cell_type.txt_4',X'','FLOAT32','{"type": "txt", "source": "cell_type.txt", "content": "id: http://w3id.org/ontogpt/cell_type\ndefault_range: string\nname: cell_type\ntitle: Composite Disease\ndescription: >-\n  A template for representing cell types\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  AUTO: http://w3id.org/ontogpt/auto/\n  BFO: http://purl.obolibrary.org/obo/BFO_\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  CL: http://purl.obolibrary.org/obo/CL_\n  FBbt: http://purl.obolibrary.org/obo/FBbt_\n  WBbt: http://purl.obolibrary.org/obo/WBbt_\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  HP: http://purl.obolibrary.org/obo/HP_\n  IAO: http://purl.obolibrary.org/obo/IAO_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  NCIT: http://purl.obolibrary.org/obo/NCIT_\n  PW: http://purl.obolibrary.org/obo/PW_\n  RO: http://purl.obolibrary.org/obo/RO_\n  UBERON: http://purl.obolibrary.org/obo/UBERON_\n  DRUGBANK: http://purl.obolibrary.org/obo/DRUGBANK_\n  cell_type: http://w3id.org/ontogpt/cell_type/\n  linkml: https://w3id.org/linkml/\n  skos: http://www.w3.org/2004/02/skos/core#\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  CellTypeEquivalentToCellOntologyTermRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: CellOntologyTerm\n      predicate:\n        range: CellTypeEquivalentToCellOntologyTermPredicate\n\n  CellTypeEquivalentToCellOntologyTermPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeEquivalentToCellOntologyTerm relationships.\n      id:\n        pattern: ''equivalent to''\n\n  CellTypeSubclassOfCellTypeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: CellType\n      predicate:\n        range: CellTypeSubclassOfCellTypePredicate\n\n  CellTypeSubclassOfCellTypePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeSubclassOfCellType relationships.\n      id:\n        pattern: ''subclass of''\n\n  CellTypeSubclassOfCellOntologyTermRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: CellOntologyTerm\n      predicate:\n        range: CellTypeSubclassOfCellOntologyTermPredicate\n\n  CellTypeSubclassOfCellOntologyTermPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeSubclassOfCellOntologyTerm relationships.\n      id:\n        pattern: ''subclass of''\n\n  CellTypeExpressesGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: Gene\n      predicate:\n        range: CellTypeExpressesGenePredicate\n\n  CellTypeExpressesGenePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the CellTypeExpressesGene relationships.\n      id:\n        pattern: ''expresses''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  CellTypeDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: Disease\n      predicate:\n        range: CellTypeDiseasePredicate\n\n  CellTypeDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeDisease relationships.\n\n  CellTypeCapableOfBiologicalProcessRelationship:\n    is_a: Triple\n    description: >-\n      Roles (e.g. biological processes) that this cell type plays.\n      These should be short descriptive terms corresponding to ontology\n      terms in the GO biological process hierarchy.\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: CellTypeCapableOfBiologicalProcessPredicate\n\n  CellTypeCapableOfBiologicalProcessPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the CellTypeCapableOfBiologicalProcess relationships.\n    annotations:\n      annotators: sqlite:obo:ro\n      \n  CellTypePartOfAnatomicalStructureRelationship:\n    is_a: Triple\n    description: Anatomical structures in which this cell type is localized\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: AnatomicalStructure\n      predicate:\n        range: CellTypePartOfAnatomicalStructurePredicate\n\n  CellTypePartOfAnatomicalStructurePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - BFO\n    attributes:\n      label:\n        description: The predicate for the CellTypePartOfAnatomicalStructure relationships.\n    annotations:\n      annotators: sqlite:obo:bfo\n\n  ImmuneCellHasSurfaceMarkersProteinOrComplexRelationship:\n    is_a: Triple\n    description: Proteins or complexes expressed on the surface of the cell\n    slot_usage:\n      subject:\n        range: ImmuneCell\n      object:\n        range: ProteinOrComplex\n      predicate:\n        range: ImmuneCellHasSurfaceMarkersProteinOrComplexPredicate\n\n  ImmuneCellHasSurfaceMarkersProteinOrComplexPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ImmuneCellHasSurfaceMarkersProteinOrComplex relationships.\n      id:\n        pattern: ''has surface markers''\n\n  NeuronReleasesNeurotransmitterNeurotransmitterRelationship:\n    is_a: Triple\n    description: Chemical entity that this neuron releases\n    slot_usage:\n      subject:\n        range: Neuron\n      object:\n        range: Neurotransmitter\n      predicate:\n        range: NeuronReleasesNeurotransmitterNeurotransmitterPredicate\n\n  NeuronReleasesNeurotransmitterNeurotransmitterPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the NeuronReleasesNeurotransmitterNeurotransmitter relationships.\n      id:\n        pattern: ''releases neurotransmitter''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  NeuronProjectsToOrFromBrainRegionRelationship:\n    is_a: Triple\n    description: Brain structures from which this neuron projects into or receives projections from\n    slot_usage:\n      subject:\n        range: Neuron\n      object:\n        range: BrainRegion\n      predicate:\n        range: NeuronProjectsToOrFromBrainRegionPredicate\n\n  NeuronProjectsToOrFromBrainRegionPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the NeuronProjectsToOrFromBrainRegion relationships.\n      id:\n        pattern: ''projects to or from''\n    annotations:\n      annotators: sqlite:obo:ro\n  \n  CellType:\n    is_a: NamedEntity\n    description: Represents a cell type\n    attributes:\n      id:\n        identifier: true\n        required: true\n      label:\n        range: string\n        description: the concise name of the cell type\n      definition:\n        description: A concise textual definition in genus-differentia form, i.e ''A <genus> that <differentiating characteristics>''\n  \n  ImmuneCell:\n    is_a: CellType\n  \n  Neuron:\n    is_a: CellType\n  \n  Interneuron:\n    is_a: Neuron\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: sqlite:obo:hgnc, bioportal:hgnc-nr\n\n  ProteinOrComplex:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n      - PR\n      - GO\n    annotations:\n      annotators: sqlite:obo:hgnc, bioportal:hgnc-nr, sqlite:obo:go, sqlite:obo:pr\n\n  BiologicalProcess:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n\n  Pathway:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - PW\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:pw\n\n  AnatomicalStructure:\n    is_a: NamedEntity\n    id_prefixes:\n      - UBERON\n      - FBbt\n      - WBbt\n    annotations:\n      annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi\n\n  Neurotransmitter:\n    is_a: ChemicalEntity\n    attributes:\n      neuro_transmitter_identifier:\n        required: true\n        identifier: true\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi\n\n  BrainRegion:\n    is_a: AnatomicalStructure\n    attributes:\n      brain_region_identifier:\n        required: true\n        identifier: true\n    id_prefixes:\n      - UBERON\n      - FBbt\n      - WBbt\n    annotations:\n      annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt\n\n  CellOntologyTerm:\n    is_a: NamedEntity\n    id_prefixes:\n      - CL\n      - FBbt\n      - WBbt\n    annotations:\n      annotators: sqlite:obo:cl, sqlite:obo:fbbt, sqlite:obo:wbbt\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n      - HP\n    annotations:\n      annotators: sqlite:obo:mondo, sqlite:obo:hp\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:drugbank\n"}');
INSERT INTO embeddings_queue VALUES(429,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','class_enrichment.txt_5',X'','FLOAT32','{"type": "txt", "source": "class_enrichment.txt", "content": "id: https://w3id.org/oak/class-enrichment\ndefault_range: string\ntitle: Class Enrichment Datamodel\nname: class-enrichment\ndescription: >-\n  A datamodel for representing the results of class enrichment on gene sets\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  OBI: http://purl.obolibrary.org/obo/OBI_\n  STATO: http://purl.obolibrary.org/obo/STATO_\n  bpa: https://bioportal.bioontology.org/annotator/\n  linkml: https://w3id.org/linkml/\n  oa: http://www.w3.org/ns/oa#\n  ontoenrich: https://w3id.org/oak/class-enrichment/\n  pav: http://purl.org/pav/\n  prov: http://www.w3.org/ns/prov#\n  schema: http://schema.org/\n  sh: https://w3id.org/shacl/\n  skos: http://www.w3.org/2004/02/skos/core#\n  sssom: http://w3id.org/sssom/\n\nimports:\n  - linkml:types\n\nclasses:\n  ClassEnrichmentConfiguration:\n    is_a: NamedEntity\n    description: configuration for search\n    attributes:\n      p_value_cutoff:\n        description: p-value cutoff for enrichment\n        range: float\n        required: true\n\n  ClassEnrichmentResultSet:\n    is_a: NamedEntity\n    description: A collection of enrichment results\n    attributes:\n      results:\n        description: The enrichment results\n        range: ClassEnrichmentResult\n        multivalued: true\n\n  ClassEnrichmentResult:\n    is_a: NamedEntity\n    description: A single enrichment result\n    attributes:\n      class_id:\n        description: The class id\n        range: integer\n        required: true\n        identifier: true\n      class_label:\n        description: The class label\n        range: string\n      rank:\n        description: The rank of this result\n        range: integer\n      p_value:\n        description: The p-value\n        range: float\n        required: true\n      p_value_adjusted:\n        description: The adjusted p-value\n        range: float\n      false_discovery_rate:\n        description: The false discovery rate\n        range: float\n      fold_enrichment:\n        description: The fold enrichment\n        range: float\n      probability:\n        description: The probability, as estimated by model-based approaches (its value is between 0 and 1).\n        range: float\n        minimum_value: 0\n        maximum_value: 1\n      sample_count:\n        description: The number of entities in the sample with this class\n        range: integer\n      sample_total:\n        description: The total number of entities in the sample\n        range: integer\n      background_count:\n        description: The background count\n        range: integer\n      background_total:\n        description: The background total\n        range: integer\n      ancestor_of_more_informative_result:\n        description: This term is more general than a previously reported result\n        range: boolean\n      descendant_of_more_informative_result:\n        description: This term is more specific than a previously reported result\n        range: boolean"}');
INSERT INTO embeddings_queue VALUES(430,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','composite_disease.txt_6',X'','FLOAT32','{"type": "txt", "source": "composite_disease.txt", "content": "id: http://w3id.org/ontogpt/composite_disease\n\ndefault_range: string\n\nname: composite_disease\n\ntitle: Composite Disease\n\ndescription: >-\n  A template for representing composite disease concepts\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\nprefixes:\n  linkml: https://w3id.org/linkml/\n  ontogpt: http://w3id.org/ontogpt/\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  HGNC: http://identifiers.org/hgnc/\n  HP: http://purl.obolibrary.org/obo/HP_\n  MAXO: http://purl.obolibrary.org/obo/MAXO_\n  NCIT: http://purl.obolibrary.org/obo/ncit.owl\n  MESH: http://identifiers.org/mesh/\n  GO: http://purl.obolibrary.org/obo/GO_\n  DRUGBANK: http://purl.obolibrary.org/obo/DRUGBANK_\n  composite_disease: http://w3id.org/ontogpt/composite_disease/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  TreatmentMechanismRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: Mechanism\n      predicate:\n        range: TreatmentMechanismPredicate\n  \n  TreatmentMechanismPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TreatmentMechanism relationships.\n\n  TreatmentAdverseEffectRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: AdverseEffect\n      predicate:\n        range: AdverseEffectPredicate\n    annotations:\n      prompt.examples: Imatinib*nausea\n  \n  TreatmentAdverseEffectPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TreatmentAdverseEffect relationships.\n  \n  DrugIsSubstanceThatTreatsDiseaseRelationship:\n    is_a: Triple\n    description: Therapies and treatments are indicated for treating the disease.\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: Drug\n      predicate:\n        range: DrugIsSubstanceThatTreatsDiseasePredicate\n      treatment:\n        range: Treatment\n  \n  DrugIsSubstanceThatTreatsDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DrugIsSubstanceThatTreatsDisease relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: obo:sql:hgnc, bioportal:hgnc-nr\n\n  Symptom:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n    annotations:\n      annotators: sqlite:obo:hp\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n\n  AdverseEffect:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:ncit\n\n  Treatment:\n    is_a: NamedEntity\n    attributes:\n      treatment_efficacy:\n        range: string\n        annotations:\n          prompt.examples: effective+\n      adverse_effect:\n        range: string\n        annotations:\n          prompt.examples: effective+\n      contraindications:\n        range: string\n    id_prefixes:\n      - MAXO\n      - NCIT\n      - MESH\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh, sqlite:obo:chebi\n      prompt.examples: Imatinib, exercise, surgery\n\n  Mechanism:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - NCIT\n      - MESH\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:ncit, sqlite:obo:mesh\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - DRUGBANK\n    attributes:\n      contraindications:\n        range: string\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:drugbank\n\n"}');
INSERT INTO embeddings_queue VALUES(431,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','condition.txt_7',X'','FLOAT32','{"type": "txt", "source": "condition.txt", "content": "id: http://w3id.org/ontogpt/condition\n\nname: condition\n\ntitle: condition FHIR Template\n\ndescription: >-\n  A FHIR-compliant template for conditions mentioned in a clinical note\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\nprefixes:\n  linkml: https://w3id.org/linkml/\n  condition: http://w3id.org/ontogpt/condition/\n  SNOMEDCT: https://purl.bioontology.org/ontology/SNOMEDCT\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  ConditionConditionProblemDiagnosisRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Condition\n      object:\n        range: ConditionProblemDiagnosis\n      predicate:\n        range: ConditionConditionProblemDiagnosisPredicate\n\n  ConditionConditionProblemDiagnosisPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ConditionConditionProblemDiagnosis relationships.\n\n  Condition:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: The concise name of the condition, problem, or diagnosis.\n      status:\n        description: The clinical status of the condition.\n        range: ConditionClinicalStatusType\n        required: true\n      severity:\n        description: Subjective severity of condition.\n        range: ConditionDiagnosisSeverityType\n\n  ConditionProblemDiagnosis:\n    is_a: NamedEntity\n    attributes:\n      status:\n        range: ConditionClinicalStatusType\n    id_prefixes: \n      - SNOMEDCT\n    annotations:\n      annotators: bioportal:SNOMEDCT\n\nenums:\n  ConditionClinicalStatusType:\n    permissible_values:\n      active:\n        description: The subject is currently experiencing the condition or situation, there is evidence of the condition or situation, or considered to be a significant risk.\n      recurrence:\n        description: The subject is experiencing a reoccurence or repeating of a previously resolved condition or situation, e.g. urinary tract infection, food insecurity.\n      relapse:\n        description: The subject is experiencing a return of a condition or situation after a period of improvement or remission, e.g. relapse of cancer, alcoholism.\n      inactive:\n        description: The subject is no longer experiencing the condition or situation and there is no longer evidence or appreciable risk of the condition or situation.\n      remission:\n        description: The subject is not presently experiencing the condition or situation, but there is a risk of the condition or situation returning.\n      resolved:\n        description: The subject is not presently experiencing the condition or situation and there is a negligible perceived risk of the condition or situation returning.\n      unknown:\n        description: The authoring/source system does not know which of the status values currently applies for this condition.\n  \n  ConditionDiagnosisSeverityType:\n    permissible_values:\n      severe:\n        meaning: SNOMEDCT:24484000\n      moderate:\n        meaning: SNOMEDCT:6736007\n      mild:\n        meaning: SNOMEDCT:255604002"}');
INSERT INTO embeddings_queue VALUES(432,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ctd.txt_8',X'','FLOAT32','{"type": "txt", "source": "ctd.txt", "content": "id: http://w3id.org/ontogpt/ctd\n\ndefault_range: string\n\nname: ctd\n\ntitle: Chemical to Disease Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for Chemical to Disease associations.\n\n  This template is intended to represent associations between chemicals and diseases,\n  and for evaluating Semantic Llama against BioCreative V Chemical Disease\n  Relation (CDR) Task (BC5CDR).\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MESH: http://identifiers.org/mesh/\n  MONDO: http://purl.obolibrary.org/obo/mondo.owl\n  HP: http://purl.obolibrary.org/obo/hp/hp-international.owl\n  NCIT: http://purl.obolibrary.org/obo/ncit.owl\n  DOID: http://purl.obolibrary.org/obo/doid.owl\n  MEDDRA: http://purl.obolibrary.org/obo/meddra.owl\n  DRUGBANK: http://purl.obolibrary.org/obo/DRUGBANK_\n  drug: http://w3id.org/ontogpt/drug/\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  ChemicalInducesDiseaseRelationship:\n    is_a: Triple\n    description: A triple where the subject is a chemical and the object is a disease.\n    slot_usage:\n      subject:\n        range: Chemical\n      object:\n        range: Disease\n      predicate:\n        range: ChemicalInducesDiseasePredicate\n\n  ChemicalInducesDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ChemicalInducesDisease relationships.\n      id:\n        pattern: ''induces''\n\n  ChemicalIsSubstanceThatTreatsDiseaseRelationship:\n    is_a: Triple\n    description: A triple where the subject is a chemical and the object is a disease.\n    slot_usage:\n      subject:\n        range: Chemical\n      object:\n        range: Disease\n      predicate:\n        range: ChemicalIsSubstanceThatTreatsDiseasePredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the chemical, e.g. \"high dose\" or \"intravenously administered\"\n        range: string\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the disease, e.g. \"severe\" or \"with additional complications\"\n        range: string\n  \n  ChemicalIsSubstanceThatTreatsDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the ChemicalIsSubstanceThatTreatsDisease relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations: \n      annotators: sqlite:obo:ro\n\n  Disease:\n    is_a: NamedEntity\n    description: The disease or condition that is being treated or induced by the chemical.\n    attributes:\n      id:\n        description: The unique identifier for the disease entity.\n        range: MeshDiseaseIdentifierType\n        required: true\n        identifier: true\n    id_prefixes:\n      - MESH\n      - MONDO\n      - HP\n      - NCIT\n      - DOID\n      - MEDDRA\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:ncit, sqlite:obo:doid, bioportal:meddra\n      prompt.examples: cardiac asystole, COVID-19, Headache, cancer, asthma, Hypotension\n\n  Chemical:\n    is_a: NamedEntity\n    description: The chemical substance, drug, or small molecule.\n    attributes:\n      id:\n        description: The unique identifier for the chemical entity.\n        range: MeshChemicalIdentifierType\n        required: true\n        identifier: true\n    id_prefixes:\n      - MESH\n      - CHEBI\n      - NCIT\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:chebi, sqlite:obo:ncit, sqlite:obo:drugbank, bioportal:mdm\n      prompt.examples: Lidocaine, Hydroxychloroquine, Methyldopa, Imatinib, Monosodium Glutamate\n\nenums:\n  MeshChemicalIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D000602 ## Amino Acids, Peptides, and Proteins\n        - MESH:D001685 ## Biological Factors\n        - MESH:D002241 ## Carbohydrates\n        - MESH:D004364 ## Pharmaceutical Preparations\n        - MESH:D006571 ## Heterocyclic Compounds\n        - MESH:D007287 ## Inorganic Chemicals\n        - MESH:D008055 ## Lipids\n        - MESH:D009706 ## Nucleic Acids, Nucleotides, and Nucleosides\n        - MESH:D009930 ## Organic Chemicals\n        - MESH:D011083 ## Polycyclic Compounds\n        - MESH:D013812 ## Therapeutics\n        - MESH:D019602 ## Food and Beverages\n        - MESH:D045424 ## Complex Mixtures\n        - MESH:D045762 ## Enzymes and Coenzymes\n        - MESH:D046911 ## Macromolecular Substances\n  MeshDiseaseIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D001423 ## Bacterial Infections and Mycoses\n        - MESH:D001523 ## Mental Disorders\n        - MESH:D002318 ## Cardiovascular Diseases\n        - MESH:D002943 ## Circulatory and Respiratory Physiological Phenomena\n        - MESH:D004066 ## Digestive System Diseases\n        - MESH:D004700 ## Endocrine System Diseases\n        - MESH:D005128 ## Eye Diseases\n        - MESH:D005261 ## Female Urogenital Diseases and Pregnancy Complications\n        - MESH:D006425 ## Hemic and Lymphatic Diseases\n        - MESH:D007154 ## Immune System Diseases\n        - MESH:D007280 ## Disorders of Environmental Origin\n        - MESH:D009057 ## Stomatognathic Diseases\n        - MESH:D009140 ## Musculoskeletal Diseases\n        - MESH:D009358 ## Congenital, Hereditary, and Neonatal Diseases and Abnormalities\n        - MESH:D009369 ## Neoplasms\n        - MESH:D009422 ## Nervous System Diseases\n        - MESH:D009750 ## Nutritional and Metabolic Diseases\n        - MESH:D009784 ## Occupational Diseases\n        - MESH:D010038 ## Otorhinolaryngologic Diseases\n        - MESH:D010272 ## Parasitic Diseases\n        - MESH:D012140 ## Respiratory Tract Diseases\n        - MESH:D013568 ## Pathological Conditions, Signs and Symptoms\n        - MESH:D014777 ## Virus Diseases\n        - MESH:D014947 ## Wounds and Injuries\n        - MESH:D017437 ## Skin and Connective Tissue Diseases\n        - MESH:D052801 ## Male Urogenital Diseases\n        - MESH:D064419 ## Chemically-Induced Disorders\n"}');
INSERT INTO embeddings_queue VALUES(433,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ctd_ner.txt_9',X'','FLOAT32','{"type": "txt", "source": "ctd_ner.txt", "content": "id: http://w3id.org/ontogpt/ctd_ner\ndefault_range: string\nname: ctd_ner\ntitle: Chemical and Disease Entity Recognition Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Chemical and Disease named entity recognition.\n\n  This template is intended to represent entities (chemicals and diseases),\n  and for evaluating SPIRES against the BioCreative V Disease Named Entity\n  Recognition (DNER) results. As the test set also contains chemical names,\n  it is also appropriate to use this template for evaluating chemical NER.\nsee_also:\n  - https://biocreative.bioinformatics.udel.edu/media/store/files/2015/BC5CDR_overview.final.pdf\n  - https://academic.oup.com/database/article/doi/10.1093/database/baw068/2630414\nsource: >-\n  https://biocreative.bioinformatics.udel.edu/tasks/biocreative-v/track-3-cdr/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MESH: http://identifiers.org/mesh/\n  ctdner: http://w3id.org/ontogpt/ctd_ner\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  ChemicalDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Chemical\n      object:\n        range: Disease\n      predicate:\n        range: ChemicalDiseasePredicate\n  \n  ChemicalDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ChemicalDisease relationships.\n\n  Chemical:\n    is_a: NamedEntity\n    description: A chemical substances, drug, or small molecule.\n    attributes:\n      id:\n        range: MeshChemicalIdentifierType\n        identifier: true\n        required: true\n    id_prefixes:\n      - MESH\n      - CHEBI\n      - NCIT\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:chebi, sqlite:obo:ncit, bioportal:mdm, sqlite:obo:drugbank\n      prompt.examples: Lidocaine, Hydroxychloroquine, Methyldopa, Monosodium Glutamate, Imatinib\n\n  Disease:\n    is_a: NamedEntity\n    description: A disease or condition.\n    attributes:\n      id:\n        range: MeshDiseaseIdentifierType\n        identifier: true\n        required: true\n    id_prefixes:\n      - MESH\n      - MONDO\n      - HP\n      - NCIT\n      - DOID\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:ncit, sqlite:obo:doid, bioportal:meddra\n      prompt.examples: cardiac asystole, COVID-19, Hypotension, Headache, cancer\n\nenums:\n  MeshChemicalIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D000602 ## Amino Acids, Peptides, and Proteins\n        - MESH:D001685 ## Biological Factors\n        - MESH:D002241 ## Carbohydrates\n        - MESH:D004364 ## Pharmaceutical Preparations\n        - MESH:D006571 ## Heterocyclic Compounds\n        - MESH:D007287 ## Inorganic Chemicals\n        - MESH:D008055 ## Lipids\n        - MESH:D009706 ## Nucleic Acids, Nucleotides, and Nucleosides\n        - MESH:D009930 ## Organic Chemicals\n        - MESH:D011083 ## Polycyclic Compounds\n        - MESH:D013812 ## Therapeutics\n        - MESH:D019602 ## Food and Beverages\n        - MESH:D045424 ## Complex Mixtures\n        - MESH:D045762 ## Enzymes and Coenzymes\n        - MESH:D046911 ## Macromolecular Substances\n  MeshDiseaseIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D001423 ## Bacterial Infections and Mycoses\n        - MESH:D001523 ## Mental Disorders\n        - MESH:D002318 ## Cardiovascular Diseases\n        - MESH:D002943 ## Circulatory and Respiratory Physiological Phenomena\n        - MESH:D004066 ## Digestive System Diseases\n        - MESH:D004700 ## Endocrine System Diseases\n        - MESH:D005128 ## Eye Diseases\n        - MESH:D005261 ## Female Urogenital Diseases and Pregnancy Complications\n        - MESH:D006425 ## Hemic and Lymphatic Diseases\n        - MESH:D007154 ## Immune System Diseases\n        - MESH:D007280 ## Disorders of Environmental Origin\n        - MESH:D009057 ## Stomatognathic Diseases\n        - MESH:D009140 ## Musculoskeletal Diseases\n        - MESH:D009358 ## Congenital, Hereditary, and Neonatal Diseases and Abnormalities\n        - MESH:D009369 ## Neoplasms\n        - MESH:D009422 ## Nervous System Diseases\n        - MESH:D009750 ## Nutritional and Metabolic Diseases\n        - MESH:D009784 ## Occupational Diseases\n        - MESH:D010038 ## Otorhinolaryngologic Diseases\n        - MESH:D010272 ## Parasitic Diseases\n        - MESH:D012140 ## Respiratory Tract Diseases\n        - MESH:D013568 ## Pathological Conditions, Signs and Symptoms\n        - MESH:D014777 ## Virus Diseases\n        - MESH:D014947 ## Wounds and Injuries\n        - MESH:D017437 ## Skin and Connective Tissue Diseases\n        - MESH:D052801 ## Male Urogenital Diseases\n        - MESH:D064419 ## Chemically-Induced Disorders\n"}');
INSERT INTO embeddings_queue VALUES(434,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','datasheet.txt_10',X'','FLOAT32','{"type": "txt", "source": "datasheet.txt", "content": "id: http://w3id.org/ontogpt/datasheet\ndefault_range: string\nname: datasheet\ntitle: Datasheet Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting metadata about a dataset,\n  as defined by the Datasheets for Datasets model\n  (see https://github.com/bridge2ai/data-sheets-schema),\n  itself based on Gebru et al. (2021)\n  (https://cacm.acm.org/magazines/2021/12/256932-datasheets-for-datasets/abstract)\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  d4d: http://w3id.org/ontogpt/datasheet\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  DatasetFundedByOrganizationRelationship:\n    is_a: Triple\n    description: List of organizations supporting creation of the dataset.\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: Organization\n      predicate:\n        range: DatasetFundedByOrganizationPredicate\n\n  DatasetFundedByOrganizationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetFundedByOrganization relationships.\n      id:\n        pattern: ''funded by''\n\n  Dataset:\n    is_a: NamedEntity\n    description: A document that contains a description of a dataset.\n    attributes:\n      name:\n        description: The name of the dataset.\n      subsets:\n        description: >-\n          List of names of any subsets of the dataset.\n        multivalued: true\n      authors:\n        description: >-\n          List of names of creators of the dataset.\n        multivalued: true\n      funding_identifiers:\n        description: >-\n          List of names, numbers, or other\n          identifiers for grants supporting creation of the dataset.\n        multivalued: true\n      purpose:\n        description: >-\n          The stated purpose of the dataset. This should be no more than 1\n          sentence.\n      limitations:\n        description: >-\n          Known limitations of the dataset. This should be no more than 1\n          sentence.\n      warnings:\n        description: >-\n          Warnings regarding content or application of the dataset.\n      references:\n        description: >-\n          List of publications describing the data or the\n          process used to produce it.\n        multivalued: true\n      license:\n        description: >-\n          The set of rules defining the rights of the developer and the users\n          of the dataset.\n        annotations:\n          prompt.examples: BSD-3, CC0\n  \n  Organization:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:ncit\n"}');
INSERT INTO embeddings_queue VALUES(435,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','data_sheets_schema.txt_11',X'','FLOAT32','{"type": "txt", "source": "data_sheets_schema.txt", "content": "---\nid: https://w3id.org/bridge2ai/data-sheets-schema\nname: data-sheets-schema\ntitle: data-sheets-schema\ndescription: |-\n  A LinkML schema for Datasheets for Datasets.\nlicense: MIT\nsee_also:\n  - https://bridge2ai.github.io/data-sheets-schema\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  biolink: https://w3id.org/biolink/\n  csvw: http://www.w3.org/ns/csvw#\n  data_sheets_schema: https://w3id.org/bridge2ai/data-sheets-schema/\n  datasets: https://w3id.org/linkml/report\n  dcat: http://www.w3.org/ns/dcat#\n  example: https://example.org/\n  formats: http://www.w3.org/ns/formats/\n  frictionless: https://specs.frictionlessdata.io/\n  linkml: https://w3id.org/linkml/\n  mediatypes: https://www.iana.org/assignments/media-types/\n  pav: http://purl.org/pav/\n  schema: http://schema.org/\n  sh: https://w3id.org/shacl/\n  skos: http://www.w3.org/2004/02/skos/core#\n  void: http://rdfs.org/ns/void#\ndefault_prefix: data_sheets_schema\ndefault_range: string\n\nimports:\n  - linkml:types\n\nclasses:\n\n  PersonOrganizationRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Person\n      object:\n        range: Organization\n      predicate:\n        range: PersonOrganizationPredicate\n\n  PersonOrganizationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the PersonOrganization relationships.\n\n  Person:\n    is_a: NamedEntity\n    description: An individual human being.\n    attributes:\n      email:\n        description: The email address of the person.\n        identifier: true\n        required: true\n        pattern: ''^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$''\n\n  Organization:\n    description: A collection of people acting in common interests.\n    is_a: NamedEntity\n    attributes:\n      email:\n        description: The email address of the organization.\n        identifier: true\n        required: true\n        pattern: ''^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$''\n      ror_id:\n        description: Unique ROR identifier.\n        required: true\n      wikidata_id:\n        description: Unique Wikidata identifier.\n        required: true\n\n  Software:\n    description: >-\n      A software program or library.\n    is_a: NamedEntity\n    attributes:\n      version:\n        range: string\n      license:\n        range: string\n      url:\n        range: string\n\n  File:\n    is_a: NamedEntity\n    description: A file or set of files.\n    attributes:\n      uri:\n        description: >-\n          A unique resource identifier (URI) for the file.\n          This may be a file path (beginning with file://) or URL.\n        range: string\n        identifier: true\n        required: true\n      file_attributes:\n        range: string\n        multivalued: true\n\n  Creator:\n    is_a: Person\n\n  Maintainer:\n    is_a: Person"}');
INSERT INTO embeddings_queue VALUES(436,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','desiccation.txt_12',X'','FLOAT32','{"type": "txt", "source": "desiccation.txt", "content": "id: http://w3id.org/ontogpt/desiccation\n\ndefault_range: string\n\nname: desiccation\n\ntitle: desiccationTemplate\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for extracting ChEBI, GO, NCBITAXON, PO, TO, PECO\n\nprefixes:\n  PECO: http://purl.obolibrary.org/obo/peco.owl\n  NCBITAXON: http://purl.obolibrary.org/obo/ncbitaxon.owl\n  TO: http://purl.obolibrary.org/obo/to.owl\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  desiccation: http://w3id.org/ontogpt/desiccation\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  EnvironmentalCondition:\n    is_a: NamedEntity\n    description: The name of an environmental treatment.\n    id_prefixes:\n      - PECO\n    annotations:\n      annotators: sqlite:obo:peco\n      prompt.examples: drought, salt stress, cold tolerance\n\n  Taxon:\n    is_a: NamedEntity\n    description: The name of a taxonomic name or species.\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n      prompt.examples: Bacillus subtilus, Bos taurus, blue whale\n\n  Trait:\n    is_a: NamedEntity\n    description: The description of a plant trait.\n    id_prefixes:\n      - TO\n    annotations:\n      annotators: sqlite:obo:to\n      prompt.examples: germination ratio, fruit hollowness, arid region exposure\n"}');
INSERT INTO embeddings_queue VALUES(437,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','diagnostic_procedure.txt_13',X'','FLOAT32','{"type": "txt", "source": "diagnostic_procedure.txt", "content": "id: http://w3id.org/ontogpt/diagnostic_procedure\nname: diagnostic_procedure\ntitle: Diagnostic Procedure Template\ndescription: >-\n  A template for clinical diagnostic procedures and the\n  phenotypes they may contribute to.\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  HP: http://purl.obolibrary.org/obo/HP_\n  LOINC: http://loinc.org/rdf/\n  OBA: http://purl.obolibrary.org/obo/OBA_\n  PATO: http://purl.obolibrary.org/obo/PATO_\n  RO: http://purl.obolibrary.org/obo/RO_\n  UO: http://purl.obolibrary.org/obo/UO_\n  biolink: https://w3id.org/biolink/vocab/\n  diag: http://w3id.org/ontogpt/diagnostic_procedure/\n  linkml: https://w3id.org/linkml/\n\ndefault_prefix: diag\ndefault_range: string\n\nimports:\n  - linkml:types\n  - core\n\n# TODO: LOINC isn''t great for grounding,\n# but perhaps a combo of subject, unit, and qualifier would work\n# since LOINC names are often like \"IgG [Units/volume] in Serum\"\n\nclasses:\n  DiagnosticProceduretoPhenotypeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DiagnosticProcedure\n      object:\n        range: Phenotype\n      predicate:\n        range: ProcedureToPhenotypePredicate\n\n  DiagnosticProcedureToClinicalAttributeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DiagnosticProcedure\n      object:\n        range: ClinicalAttribute\n      predicate:\n        range: DiagnosticProcedureToClinicalAttributePredicate\n\n  DiagnosticProcedure:\n    is_a: NamedEntity\n    annotations:\n      annotators: bioportal:loinc, sqlite:obo:ncit\n    id_prefixes:\n      - LOINC\n\n  Phenotype:\n    is_a: NamedEntity\n    annotations:\n      annotators: sqlite:obo:hp\n    id_prefixes:\n      - HP\n\n  ClinicalAttributeUnitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalAttribute\n      object:\n        range: Unit\n      predicate:\n        range: ClinicalAttributeUnitPredicate\n\n  ClinicalAttributeUnitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalAttributeUnit relationships.\n\n  ClinicalAttribute:\n    is_a: NamedEntity\n    annotations:\n      annotators: sqlite:obo:oba, sqlite:obo:ncit\n    id_prefixes:\n      - OBA\n\n  Quality:\n    is_a: NamedEntity\n    annotations:\n      annotators: sqlite:obo:pato\n    id_prefixes:\n      - PATO\n\n  ProcedureToPhenotypePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ProcedureToPhenotype relationships.\n\n  DiagnosticProcedureToClinicalAttributePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DiagnosticProcedureToClinicalAttribute relationships.\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n    annotations:\n      annotators: sqlite:obo:uo\n"}');
INSERT INTO embeddings_queue VALUES(438,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','dietitian_notes.txt_14',X'','FLOAT32','{"type": "txt", "source": "dietitian_notes.txt", "content": "id: http://w3id.org/ontogpt/dietician_notes\nname: dietitian_notes\ntitle: Dietitian Notes Extraction Template\ndescription: >-\n  A template for extracting clinical observations from dietitian notes.\n  Developed with guidance from Lauren Chan, PhD, RD\n  and Alyson Lawrence, RD, CNSC\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  EFO: http://www.ebi.ac.uk/efo/EFO_\n  FOODON: http://purl.obolibrary.org/obo/FOODON_\n  HP: http://purl.obolibrary.org/obo/HP_\n  MAXO: http://purl.obolibrary.org/obo/MAXO_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  UO: http://purl.obolibrary.org/obo/UO_\n  dietician_notes: http://w3id.org/ontogpt/dietitian_notes\n  linkml: https://w3id.org/linkml/\n\ndefault_prefix: dietitian_notes\ndefault_range: string\n\n# TODO: address extracted chunks that are too large\n# TODO: find additional grounding strategies\n# TODO: provide additional examples for each class\n\nimports:\n  - linkml:types\n  - core\n\nclasses:\n\n  ClinicalObservation:\n    description: >-\n      A clinical observation about a single patient at a single time.\n    is_a: NamedEntity\n    attributes:\n      is_pediatric:\n        description: >-\n            True if the patient is a child, False otherwise.\n        range: boolean\n      is_preterm:\n        description: >-\n            True if the patient''s birth was preterm, False otherwise.\n            A birth before 37 weeks gestation is preterm.\n        range: boolean\n      patient_age:\n        description: >-\n            The patient''s age at the time of the current assessment.\n        range: integer\n      patient_height:\n        description: >-\n            The patient''s height at the time of the current assessment in centimeters.\n        range: integer\n      current_patient_weight:\n        description: >-\n            The value and units of the patient''s actual body weight at the time\n            of the current assessment in kilograms. \n        range: float\n      usual_patient_weight:\n        description: >-\n            The value and units of the patient''s body weight under usual\n            conditions and/or in the recent past in kilograms.\n        range: float\n      head_circumference:\n        description: >-\n            The value and units of the patient''s head circumference in centimeters.\n            Usually abbreviated as \"HC\".\n        range: integer\n      malnutrition_status:\n        description: >-\n          Observations of the patient''s malnutrition status.\n        range: boolean\n      nil_per_os:\n        description: >-\n          True if the patient is not receiving any oral nutrition,\n          False otherwise.\n        range: boolean\n\n  ClinicalObservationDietSupplementationRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalObservation\n      object:\n        range: DietSupplementation\n      predicate:\n        range: ClinicalObservationDietSupplementationPredicate\n  \n  ClinicalObservationDietSupplementationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalObservationDietSupplementation relationships.\n\n  ClinicalObservationNutritionSupportRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalObservation\n      object:\n        range: NutritionSupport\n      predicate:\n        range: ClinicalObservationNutritionSupportPredicate\n\n  ClinicalObservationNutritionSupportPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalObservationNutritionSupport relationships.\n\n  ClinicalObservationDrugTherapyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalObservation\n      object:\n        range: DrugTherapy\n      predicate:\n        range: ClinicalObservationDrugTherapyPredicate\n\n  ClinicalObservationDrugTherapyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalObservationDrugTherapy relationships.\n\n  DietSupplementationTherapeuticMaterialRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DietSupplementation\n      object:\n        range: TherapeuticMaterial\n      predicate:\n        range: DietSupplementationTherapeuticMaterialPredicate\n\n  DietSupplementationTherapeuticMaterialPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DietSupplementationTherapeuticMaterial relationships.\n\n  DietSupplementation:\n    is_a: NamedEntity\n    attributes:\n      amount:\n        description: >-\n          The quantity or dosage of the therapy in milligrams.\n        range: integer\n      dosage_by_unit:\n        description: >-\n          The unit of a patient''s properties used to determine supplement\n          dosage in milligrams.\n        range: integer\n      duration:\n        description: >-\n          The duration of the supplementation in days.\n        range: integer\n      route_of_administration:\n        description: >-\n          The route of administration for the supplementation.\n        range: string\n\n  TherapeuticMaterial:\n    is_a: NamedEntity\n    description: >-\n      A specific material added to a patient''s diet or\n      included as part of a nutritional plan.\n    id_prefixes:\n      - FOODON\n      - MAXO\n      - EFO\n    annotations:\n      annotators: sqlite:obo:foodon, sqlite:obo:chebi, sqlite:obo:maxo, sqlite:obo:efo, sqlite:obo:mesh\n      prompt.examples: >-\n        sugar, amino acids, single vitamin supplement,\n        ginkgo biloba supplement, multi-mineral supplement,\n        biotin supplementation, glucosamine supplementation\n\n  NutritionSupport:\n    is_a: NamedEntity\n    attributes:\n      method:\n        description: >-\n          The name of a method used to provide nutritional support.\n        range: string\n      components:\n        description: >-\n          The names of specific components included in a patient''s diet.\n        range: string\n        multivalued: true\n\n  DrugTherapyDrugRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DrugTherapy\n      object:\n        range: Drug\n      predicate:\n        range: DrugTherapyDrugPredicate\n\n  DrugTherapyDrugPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DrugTherapyDrug relationships.\n\n  DrugTherapy:\n    is_a: NamedEntity\n    attributes:\n      amount:\n        description: >-\n          The quantity or dosage of the drug in milligrams.\n        range: integer\n      dosage_by_unit:\n        description: >-\n          The unit of a patient''s properties used to determine drug\n          dosage in kilograms.\n        range: integer\n      duration:\n        description: >-\n          The duration of the drug therapy in days.\n        range: integer\n      route_of_administration:\n        description: >-\n          The route of administration for the drug therapy.\n        range: string\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n      - EFO\n    annotations:\n      annotators: sqlite:obo:mondo, sqlite:obo:mesh, sqlite:obo:efo\n      prompt.examples: cardiac asystole, COVID-19, Headache, cancer\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - DRUGBANK\n      - CHEBI\n      - MESH\n    annotations:\n      annotators: sqlite:obo:drugbank, sqlite:obo:chebi, sqlite:obo:mesh\n      prompt.examples: >-\n        acetaminophen, ibuprofen, furosemide, insulin, heparin, warfarin\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n      - NCIT\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:uo, sqlite:obo:ncit, sqlite:obo:foodon"}');
INSERT INTO embeddings_queue VALUES(439,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','drug.txt_15',X'','FLOAT32','{"type": "txt", "source": "drug.txt", "content": "id: http://w3id.org/ontogpt/drug\n\ndefault_range: string\n\nname: drug\n\ntitle: Drug Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for Drugs and drug mechanism\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  CL: http://purl.obolibrary.org/obo/cl.owl\n  GO: http://purl.obolibrary.org/obo/go/extensions/go-plus.owl\n  NCBITAXON: http://purl.obolibrary.org/obo/ncbitaxon.owl\n  PR: http://purl.obolibrary.org/obo/pr.owl\n  UBERON: http://purl.obolibrary.org/obo/uberon.owl\n  MESH: https://w3id.org/biopragmatics/resources/mesh/mesh.owl.gz\n  MONDO: https://purl.obolibrary.org/obo/mondo/mondo-international.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  MechanismElementMechanismElementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MechanismElement\n      object:\n        range: MechanismElement\n      predicate:\n        range: MechanismElementMechanismElementPredicate\n      references:\n        multivalued: true\n        range: string\n        annotations:\n          prompt.skip: \"true\"\n      source_text:\n        range: string\n        annotations:\n          prompt.skip: \"true\"\n  \n  MechanismElementMechanismElementPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - BIOLINK\n      - RO\n    attributes:\n      label:\n        description: The predicate for the chemical to MechanismElementMechanismElement relationships.\n    annotations:\n      annotators: sqlite:obo:biolink, sqlite:obo:ro\n  \n  MechanismElement:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - MESH\n      - UBERON\n      - PR\n      - NCBITaxon\n      - CL\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:mesh, sqlite:obo:uberon, sqlite:obo:pr, sqlite:obo:ncbitaxon, sqlite:obo:cl\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MESH\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:mondo\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - DRUGBANK\n      - CHEBI\n      - MESH\n    annotations:\n      annotators: sqlite:obo:drugbank, sqlite:obo:chebi, sqlite:obo:mesh\n"}');
INSERT INTO embeddings_queue VALUES(440,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','drug_to_disease.txt_16',X'','FLOAT32','{"type": "txt", "source": "drug_to_disease.txt", "content": "id: http://w3id.org/ontogpt/drug\n\ndefault_range: string\n\nname: drug_to_disease\n\ntitle: Drug to Disease Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for extracting relationships between drugs and diseases\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  MONDO: https://purl.obolibrary.org/obo/mondo/mondo-international.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  DrugPreventsDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Drug\n      object:\n        range: Disease\n      predicate:\n        range: DrugPreventsDiseasePredicate\n\n  DrugPreventsDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DrugPreventsDisease relationships.\n      id:\n        pattern: ''prevents''\n\n  DrugIsSubstanceThatTreatsDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Drug\n      object:\n        range: Disease\n      predicate:\n        range: DrugIsSubstanceThatTreatsDiseasePredicate\n\n  DrugIsSubstanceThatTreatsDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DrugIsSubstanceThatTreatsDisease relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  DrugCausesOrContributesToConditionDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Drug\n      object:\n        range: Disease\n      predicate:\n        range: DrugCausesOrContributesToConditionDiseasePredicate\n\n  DrugCausesOrContributesToConditionDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DrugCausesOrContributesToConditionDisease relationships.\n      id:\n        pattern: ''causes or contributes to condition''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - DRUGBANK\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:drugbank, sqlite:obo:chebi\n"}');
INSERT INTO embeddings_queue VALUES(441,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ecosim_methods.txt_17',X'','FLOAT32','{"type": "txt", "source": "ecosim_methods.txt", "content": "id: http://w3id.org/ontogpt/ecosim_methods\n\ndefault_range: string\n\nname: ecosim_methods\n\ntitle: EcoSIM Methods Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  EcoSIM Methods Extraction Template\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ecosim_simple: http://w3id.org/ontogpt/ecosim_simple\n  ecosim: http://purl.obolibrary.org/obo/ecosim\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  EquipmentMeasuresVariableRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Equipment\n      object:\n        range: Variable\n      predicate:\n        range: EquipmentVariablePredicate\n    annotations:\n      prompt.examples: >-\n        NMR spectrometer was used to measure\n        chemical content\n  \n  EquipmentMeasuresVariablePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the chemical to EquipmentMeasuresVariable relationships.\n      id:\n        pattern: ''measures''\n  \n  Location:\n    is_a: NamedEntity\n    description: The name of a location used in research.\n    annotations:\n      prompt.examples: Vermont, New York City, Ethiopia\n\n  Method:\n    is_a: NamedEntity\n    description: >-\n      The name of a method used in environment and\n      earth science research.\n    annotations:\n      annotators: bioportal:ECOSIM\n      prompt.examples: sampling, spectroscopy\n\n  Variable:\n    is_a: NamedEntity\n    description: >-\n      The name of a variable measured in environment and\n      earth science research.\n    annotations:\n      annotators: bioportal:ECOSIM\n      prompt.examples: root shape, biomass, water turbidity\n\n  Equipment:\n    is_a: NamedEntity\n    description: >-\n      The name of a piece of equipment used in\n      environment and earth science research.\n"}');
INSERT INTO embeddings_queue VALUES(442,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ecosim_simple.txt_18',X'','FLOAT32','{"type": "txt", "source": "ecosim_simple.txt", "content": "id: http://w3id.org/ontogpt/ecosim_simple\n\ndefault_range: string\n\nname: ecosim_simple\n\ntitle: Simple EcoSIM Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  Simple EcoSIM Extraction Template\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ecosim_simple: http://w3id.org/ontogpt/ecosim_simple\n  ecosim: http://purl.obolibrary.org/obo/ecosim\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Term:\n    is_a: NamedEntity\n    description: The name of a variable for earth system simulation. Do not include abbreviations in parentheses, e.g., \"Carbon (C)\"\n    annotations:\n      annotators: bioportal:ECOSIM\n      prompt.examples: carbon, carboxylation, sodium, underground irrigation\n"}');
INSERT INTO embeddings_queue VALUES(443,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','emapa_simple.txt_19',X'','FLOAT32','{"type": "txt", "source": "emapa_simple.txt", "content": "id: http://w3id.org/ontogpt/emapa_simple\n\ndefault_range: string\n\nname: emapa_simple\n\ntitle: Simple EMAPA Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  Simple Mouse Developmental Anatomy Ontology Extraction Template\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  EMAPA: http://purl.obolibrary.org/obo/EMAPA_\n  GO: http://purl.obolibrary.org/obo/GO_\n  emapa_simple: http://w3id.org/ontogpt/emapa_simple\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  OntologyTerm:\n    is_a: NamedEntity\n    description: The name of a Mouse Developmental Anatomy Ontology term.\n    id_prefixes:\n      - EMAPA\n    annotations:\n      annotators: sqlite:obo:emapa\n      prompt.examples: >-\n        common carotid artery,\n        cerebellum anterior vermis, tailgut,\n        gastro-esophageal junction mesentery,\n        hindlimb digit 3 phalanx\n"}');
INSERT INTO embeddings_queue VALUES(444,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','environmental_metadata.txt_20',X'','FLOAT32','{"type": "txt", "source": "environmental_metadata.txt", "content": "id: http://w3id.org/ontogpt/environmental-metadata\n\ndefault_range: string\n\nname: environmental-metadata\n\ntitle: Environmental sample metadata\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for categorizing Environmental Data Initiative\n  data entries. See https://github.com/EDIorg/EDIorg-repository-index\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ENVO: http://purl.obolibrary.org/obo/envo.owl\n  GAZ: http://purl.obolibrary.org/obo/gaz.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  DatasetTopicRelationship:\n    is_a: Triple\n    description: The general scientific area of study concerning the sample(s).\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: Topic\n      predicate:\n        range: DatasetTopicPredicate\n\n  DatasetTopicPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetTopic relationships.\n\n  DatasetLocationRelationship:\n    is_a: Triple\n    description: The geographic location where the sample was isolated.\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: Location\n      predicate:\n        range: DatasetLocationPredicate\n\n  DatasetLocationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetLocation relationships.\n\n  DatasetEnvironmentalMaterialRelationship:\n    is_a: Triple\n    description: The environmental material that was sampled.\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: EnvironmentalMaterial\n      predicate:\n        range: DatasetEnvironmentalMaterialPredicate\n\n  DatasetEnvironmentalMaterialPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetEnvironmentalMaterial relationships.\n\n  DatasetEnvironmentRelationship:\n    is_a: Triple\n    description: The environmental context in which the study was conducted.\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: Environment\n      predicate:\n        range: DatasetEnvironmentsPredicate\n\n  DatasetEnvironmentPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetEnvironment relationships.\n\n  DatasetMethodRelationship:\n    is_a: Triple\n    description: The methods used in the study.\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: Method\n      predicate:\n        range: DatasetMethodPredicate\n\n  DatasetMethodPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetMethod relationships.\n\n  Dataset:\n    is_a: NamedEntity\n    attributes:\n      packageid:\n        description: The internal identifier for the dataset\n        required: true\n        identifier: true\n        range: string\n\n  Topic:\n    is_a: NamedEntity\n    description: The general scientific area of study concerning the sample(s)\n    annotations:\n      annotators: bioportal:ENVTHES\n\n  Location:\n    is_a: NamedEntity\n    description: The geographic location where the sample was isolated\n    id_prefixes:\n      - ENVO\n      - GAZ\n    annotations:\n      annotators: sqlite:obo:envo, sqlite:obo:gaz\n\n  EnvironmentalMaterial:\n    is_a: NamedEntity\n    description: The environmental material that was sampled\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:ENVTHES\n\n  Environment:\n    is_a: NamedEntity\n    description: The environmental context in which the study was conducted\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:ENVTHES\n\n  Method:\n    is_a: NamedEntity\n    annotations:\n      annotators: bioportal:ENVTHES\n"}');
INSERT INTO embeddings_queue VALUES(445,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','environmental_sample.txt_21',X'','FLOAT32','{"type": "txt", "source": "environmental_sample.txt", "content": "id: http://w3id.org/ontogpt/environmental-sample\ndefault_range: string\nname: environmental-sample\ntitle: Environmental Sample Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Environmental Samples\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  ENVO: http://purl.obolibrary.org/obo/ENVO_\n  PATO: http://purl.obolibrary.org/obo/PATO_\n  UO: http://purl.obolibrary.org/obo/UO_\n  linkml: https://w3id.org/linkml/\n  sample: http://w3id.org/ontogpt/environmental-sample/\n\ndefault_prefix: sample\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  StudyLocatedInLocationRelationship:\n    is_a: Triple\n    description: The sites at which the study was conducted.\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Location\n      predicate:\n        range: StudyLocatedInLocationPredicate\n  \n  StudyLocatedInLocationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyLocatedInLocation relationships.\n      id:\n        pattern: ''located in''\n\n  StudySamplesEnvironmentalMaterialRelationship:\n    is_a: Triple\n    description: The environmental material that was sampled in a study.\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: EnvironmentalMaterial\n      predicate:\n        range: StudySamplesEnvironmentalMaterialPredicate\n\n  StudySamplesEnvironmentalMaterialPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudySamplesEnvironmentalMaterial relationships.\n      id:\n        pattern: ''samples''\n\n  StudyEnvironmentRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Environment\n      predicate:\n        range: StudyEnvironmentPredicate\n\n  StudyEnvironmentPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyEnvironment relationships.\n\n  StudyMeasurementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Measurement\n      predicate:\n        range: StudyMeasurementPredicate\n\n  StudyMeasurementPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyMeasurement relationships.\n\n  Study:\n    is_a: NamedEntity\n\n  UnitMeasuresUnitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Unit\n      object:\n        range: Unit\n      predicate:\n        range: UnitMeasuresUnitPredicate\n      value:\n        description: the value of the measurement\n        range: float\n  \n  UnitMeasuresUnitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the UnitMeasuresUnit relationships.\n      id:\n        pattern: ''measures''\n\n  VariableCausesVariableRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Variable\n      object:\n        range: Variable\n      predicate:\n        range: VariableCausesVariablePredicate\n      study:\n        range: Study\n\n  VariableCausesVariablePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the VariableCausesVariable relationships.\n      id:\n        pattern: ''causes''\n  \n  Location:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:gaz, bioportal:envthes\n\n  EnvironmentalMaterial:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:envthes\n\n  Environment:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:envthes\n\n  Variable:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n      - PATO\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:bero, bioportal:envthes, sqlite:obo:pato\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:uo, sqlite:obo:ncit\n"}');
INSERT INTO embeddings_queue VALUES(446,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','figure.txt_22',X'','FLOAT32','{"type": "txt", "source": "figure.txt", "content": "id: https://w3id.org/ontogpt/figure\n\ndefault_range: string\n\nname: figure-template\n\ntitle: Plazi Figure Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for Plazi figures and sub-parts\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  fig: http://w3id.org/ontogpt/figure-template\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  FigureCaptionSubpanelRelationship:\n    is_a: Triple\n    description: A caption for a figure from a scientific paper. The caption may contain multiple subpanel descriptions.\n    slot_usage:\n      subject:\n        range: FigureCaption\n      object:\n        range: SubPanel\n      predicate:\n        range: FigureCaptionSubpanelPredicate\n    annotations:\n      prompt.examples: \"1A: A side view of the foo; 1B: A frontal view of the foo\"\n\n  FigureCaptionSubpanelPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the FigureCaptionSubpanel relationships.\n\n  FigureCaption:\n    is_a: NamedEntity\n    attributes:\n      title:\n        description: the overall title of the figure caption\n\n  SubPanel:\n    is_a: NamedEntity\n    description: A subcomponent of the overall figure caption.\n    attributes:\n      id:\n        description: The identifier for this figure subpanel\n        identifier: true\n        required: true\n      text:\n        description: The text associated with this figure subpanel\n      info:\n        description: any information from the overall figure caption that applies to that subpanel (which may be duplicated across other subpanels).\n    annotations:\n      prompt.examples: \"1A: A side view of the foo, 1B: A frontal view of the foo\"\n"}');
INSERT INTO embeddings_queue VALUES(447,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','food.txt_23',X'','FLOAT32','{"type": "txt", "source": "food.txt", "content": "id: http://w3id.org/ontogpt/food\n\ndefault_range: string\n\nname: food\n\ntitle: Food Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for extracting food names and terms from text.\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  FOODON: http://purl.obolibrary.org/obo/foodon.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  FoodTerm:\n    is_a: NamedEntity\n    description: The name of a food.\n    id_prefixes:\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:foodon\n      prompt.examples: >-\n        apple juice, okra pod, chocolate substitute,\n        breakfast cereal, tuna (flaked, canned),\n        beef chuck roast\n"}');
INSERT INTO embeddings_queue VALUES(448,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','foodon_simple.txt_24',X'','FLOAT32','{"type": "txt", "source": "foodon_simple.txt", "content": "id: http://w3id.org/ontogpt/foodon_simple\ndefault_range: string\nname: foodon_simple\ntitle: Simple FOODON Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  Simple Food Ontology Extraction Template\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  foodon: http://purl.obolibrary.org/obo/foodon_\n  GO: http://purl.obolibrary.org/obo/GO_\n  foodon_simple: http://w3id.org/ontogpt/foodon_simple\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  OntologyTerm:\n    is_a: NamedEntity\n    description: >-\n      The name of a Food Ontology term.\n    id_prefixes:\n      - FOODON\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:foodon, sqlite:obo:chebi\n      prompt.examples: >-\n        vitamin A, apple juice, okra pod, chocolate substitute,\n        breakfast cereal, tuna (flaked or canned),\n        beef chuck roast\n"}');
INSERT INTO embeddings_queue VALUES(449,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','genesummary.txt_25',X'','FLOAT32','{"type": "txt", "source": "genesummary.txt", "content": "id: http://w3id.org/ontogpt/gocam\ndefault_range: string\nname: genesummary-template\ntitle: genesummary Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for genesummary\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CL: http://purl.obolibrary.org/obo/CL_\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  PR: http://purl.obolibrary.org/obo/PR_\n  UniProtKB: http://purl.uniprot.org/uniprot/\n  genesummary: http://w3id.org/ontogpt/genesummary/\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Gene:\n    is_a: NamedEntity\n    attributes:\n      id:\n        description: >-\n          A unique identifier for the named entity\n        identifier: true\n    id_prefixes:\n      - HGNC\n      - PR\n      - UniProtKB\n    annotations:\n      annotators: >-\n        bioportal:hgnc-nr, sqlite:obo:hgnc, sqlite:obo:pr, sqlite:obo:uniprotkb\n"}');
INSERT INTO embeddings_queue VALUES(450,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','gene_description_term.txt_26',X'','FLOAT32','{"type": "txt", "source": "gene_description_term.txt", "content": "id: https://w3id.org/ontogpt/go_term\n\ndefault_range: string\n\nname: go-term-template\n\ntitle: GO Term Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A simple GO term template for NER\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  MESH: http://identifiers.org/mesh/\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  bp: http://w3id.org/ontogpt/biological-process-template\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  GeneGeneOntologyTermRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: GeneOntologyTerm\n      predicate:\n        range: GeneGeneOntologyTermPredicate\n\n  GeneGeneOntologyTermPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneGeneOntologyTerm relationships.\n\n  GeneOntologyTerm:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: the name of the GO term\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:mondo, sqlite:obo:uberon, sqlite:obo:mesh\n    id_prefixes:\n      - GO\n      - MONDO\n      - UBERON\n      - MESH\n\n  Gene:\n    is_a: NamedEntity\n    attributes:\n      about:\n        description: >-\n          The official symbol of the gene that is described.\n        range: string\n      narrative_summary:\n        description: >-\n          A free text summary describing the function of the gene\n        range: string\n    id_prefixes:\n      - HGNC\n      - GO\n      - MONDO\n      - UBERON\n      - MESH\n    annotations:\n      annotators: sqlite:obo:hgnc, sqlite:obo:go, sqlite:obo:mondo, sqlite:obo:uberon, sqlite:obo:mesh\n"}');
INSERT INTO embeddings_queue VALUES(451,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','gene_extraction.txt_27',X'','FLOAT32','{"type": "txt", "source": "gene_extraction.txt", "content": "id: http://w3id.org/ontogpt/gene_extraction\n\ndefault_range: string\n\nname: gene_extraction\n\ntitle: Gene Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template demonstrating a general strategy for extracting gene symbols from\n  ambiguous context.\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  HGNC: http://identifiers.org/hgnc/\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Gene:\n    is_a: NamedEntity\n    attributes:\n      symbol:\n        range: string\n        description: >-\n          A single gene symbol. Gene symbols may resemble acronyms referring to\n          diseases or phenotypes, and may be surrounded by punctuation or other text.\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: sqlite:obo:HGNC, bioportal:gexo\n      prompt.examples: BRCA1, TP53, EGR2, ITGB6, PRKCD\n"}');
INSERT INTO embeddings_queue VALUES(452,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','gocam.txt_28',X'','FLOAT32','{"type": "txt", "source": "gocam.txt", "content": "id: http://w3id.org/ontogpt/gocam\ndefault_range: string\nname: gocam-template\ntitle: GO-CAM Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO-CAMs\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  CL: http://purl.obolibrary.org/obo/CL_\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_\n  PR: http://purl.obolibrary.org/obo/PR_\n  PW: http://purl.obolibrary.org/obo/PW_\n  UBERON: http://purl.obolibrary.org/obo/UBERON_\n  gocam: http://w3id.org/ontogpt/gocam/\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  GeneOrganismRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: Organism\n      predicate:\n        range: GeneOrganismPredicate\n  \n  GeneOrganismPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneOrganism relationships.\n\n  GeneMolecularActivityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: MolecularActivity\n      predicate:\n        range: GeneMolecularActivityPredicate\n      target:\n        description: the name of the molecular entity that is the target of the molecular activity.\n        range: Molecule\n    annotations:\n      prompt.example: >-\n        \"gene: HGNC:1234\",\n        \"molecular_activity: GO:0003674\"\n  \n  GeneMolecularActivityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneMolecularActivity relationships.\n\n  GeneGeneLocationRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: GeneLocation\n      predicate:\n        range: GeneGeneLocationPredicate\n    annotations:\n      prompt.examples: \"gene1 / cytoplasm, gene2 / mitochondrion\"\n\n  GeneGeneLocationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneGeneLocation relationships.\n\n  GeneGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: Gene\n      predicate:\n        range: GeneGenePredicate\n  \n  GeneGenePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneGene relationships.\n  \n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n      - PR\n    annotations:\n      annotators: bioportal:hgnc-nr, sqlite:obo:pr\n  \n  Pathway:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - PW\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:pw\n  \n  CellularProcess:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n  \n  MolecularActivity:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n  \n  GeneLocation:\n    is_a: NamedEntity\n    attributes:\n      id:\n        range: GOCellComponentType\n        identifier: true\n        required: true\n    id_prefixes:\n      - GO\n      - CL\n      - UBERON\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:cl, sqlite:obo:uberon\n  \n  Organism:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n  \n  Molecule:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - PR\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:pr\n\nenums:\n\n  GOCellComponentType:\n    reachable_from:\n      source_ontology: obo:go\n      source_nodes:\n        - GO:0005575 ## cellular_component\n"}');
INSERT INTO embeddings_queue VALUES(453,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','go_simple.txt_29',X'','FLOAT32','{"type": "txt", "source": "go_simple.txt", "content": "id: http://w3id.org/ontogpt/go_simple\ndefault_range: string\nname: go_simple\ntitle: Simple Gene Ontology Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  Simple Gene Ontology Extraction Template\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  go_simple: http://w3id.org/ontogpt/go_simple\n  GO: http://purl.obolibrary.org/obo/GO_\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  OntologyTerm:\n    is_a: NamedEntity\n    description: The name of a Gene Ontology term.\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: >-\n        regulation of dehydroepiandrosterone secretion,\n        lignan metabolic process, ITP catabolic process,\n        determination of imaginal disc primordium,\n        kinetoplast\n"}');
INSERT INTO embeddings_queue VALUES(454,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','go_terms.txt_30',X'','FLOAT32','{"type": "txt", "source": "go_terms.txt", "content": "id: http://w3id.org/ontogpt/go_terms\ndefault_range: string\nname: go_terms\ntitle: Gene Ontology Term and CURIE Extraction\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO Term and ID extraction.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  go_terms: http://w3id.org/ontogpt/go_terms\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  BiologicalProcess:\n    is_a: NamedEntity\n    attributes:\n      id:\n        range: GOBiologicalProcessType\n        identifier: true\n        required: true\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: >-\n        nuclear axial expansion, intracellular transport,\n        medial surface of mandible, ribosomal subunit export from nucleus,\n        pole cell development\n\n  CellularComponent:\n    is_a: NamedEntity\n    attributes:\n      id:\n        range: GOCellComponentType\n        identifier: true\n        required: true\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: >-\n        tubulin complex, proteasome complex, cytoplasm, keratohyalin granule,\n        nucleus\n\n  MolecularFunction:\n    is_a: NamedEntity\n    attributes:\n      id:\n        range: GOMolecularFunctionType\n        identifier: true\n        required: true\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: >-\n        catalytic activity, amine binding,\n        peptide receptor activity, oxygen carrier activity,\n        structural constituent of cytoskeleton\n\nenums:\n  GOBiologicalProcessType:\n    reachable_from:\n      source_ontology: obo:go\n      source_nodes:\n        - GO:0008150  # biological_process\n\n  GOCellComponentType:\n    reachable_from:\n      source_ontology: obo:go\n      source_nodes:\n        - GO:0005575  # cellular_component\n\n  GOMolecularFunctionType:\n    reachable_from:\n      source_ontology: obo:go\n      source_nodes:\n        - GO:0003674  # molecular_function\n"}');
INSERT INTO embeddings_queue VALUES(455,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','go_terms_relational.txt_31',X'','FLOAT32','{"type": "txt", "source": "go_terms_relational.txt", "content": "id: http://w3id.org/ontogpt/go_terms_relational\ndefault_range: string\nname: go_terms_relational\ntitle: Gene Ontology Relation and CURIE Extraction\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO Term and ID extraction,\n  as relations involving specific proteins.\n  Note this does not make a distinction between\n  GO term types.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  go_terms_relational: http://w3id.org/ontogpt/go_terms_relational\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  ProteinHasAnnotationGOTermRelationship:\n    is_a: Triple\n    description: >-\n      A triple where the subject is a protein and the object is a GO term.\n    slot_usage:\n      subject:\n        range: Protein\n      object:\n        range: GOTerm\n      predicate:\n        range: ProteinHasAnnotationGOTermPredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the protein.\n        range: string\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the GO term.\n        range: string\n    annotations:\n      prompt.examples: >-\n        RPS7B has annotation structural constituent of ribosome;\n        granzyme M has annotation endopeptidase activity;\n        Mknk1 has annotation nucleoplasm\n\n  ProteinHasAnnotationGOTermPredicate:\n    is_a: RelationshipType\n    slot_usage:\n      label:\n        description: The predicate for the ProteinHasAnnotationGOTerm relationships.\n      id:\n        pattern: ''has annotation''\n\n  Protein:\n    is_a: NamedEntity\n    description: >-\n      Technically gene or protein. Can also be UniProt accession, etc\n    id_prefixes:\n      - PR\n    annotations:\n      annotators: bioportal:hgnc-nr, sqlite:obo:pr\n      prompt.examples: >-\n        Klp61F, GATA binding protein 3, S-formylglutathione, ydrolase, RPS7B,\n        granzyme M, Mknk1\n\n  GOTerm:\n    is_a: NamedEntity\n    description: The Gene Ontology term\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: >-\n        nuclear axial expansion, intracellular transport,\n        medial surface of mandible, ribosomal subunit export from nucleus,\n        pole cell development, tubulin complex, proteasome complex, cytoplasm,\n        keratohyalin granule, catalytic activity, amine binding,\n        peptide receptor activity, oxygen carrier activity,\n        structural constituent of cytoskeleton, cytosol,\n        plasma cell differentiation, small-subunit processome,\n        structural constituent of ribosome, endopeptidase activity,\n        nucleoplasm\n"}');
INSERT INTO embeddings_queue VALUES(456,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','halo.txt_32',X'','FLOAT32','{"type": "txt", "source": "halo.txt", "content": "id: https://w3id.org/ontogpt/halo\ndefault_range: string\nname: ontology-class\ntitle: Ontology Class Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Ontology Classes\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  oc: http://w3id.org/ontogpt/ontology-class-template\n  BFO: http://purl.obolibrary.org/obo/BFO_\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  OntologyElementCategoryRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: OntologyElement\n      object:\n        range: Category\n      predicate:\n        range: OntologyElementCategoryPredicate\n\n  OntologyElementCategoryPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyElementCategory relationships.\n\n  OntologyElementSubclassOfOntologyElementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: OntologyElement\n      object:\n        range: OntologyElement\n      predicate:\n        range: OntologyElementSubclassOfOntologyElementPredicate\n\n  OntologyElementSubclassOfOntologyElementPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyElementSubclassOfOntologyElement relationships.\n      id:\n        pattern:\n          ''subclass of''\n\n  OntologyElementPartOfOntologyElementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: OntologyElement\n      object:\n        range: OntologyElement\n      predicate:\n        range: OntologyElementPartOfOntologyElementPredicate\n\n  OntologyElementPartOfOntologyElementPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - BFO\n    attributes:\n      label:\n        description: The predicate for the OntologyElementPartOfOntologyElement relationships.\n      id:\n        pattern:\n          ''part of''\n    annotations:\n      annotators: sqlite:obo:bfo\n\n  OntologyElement:\n    is_a: NamedEntity\n    attributes:\n      name:\n        identifier: true\n        required: true\n        description: the name of the entity\n      context:\n        description: the ontology to which this belongs (single-valued)\n      description:\n        description: a textual description of the entity (single-valued)\n      synonyms:\n        description: a list of alternative names of the entity\n        multivalued: true\n      equivalent_to:\n        description: an OWL class expression with the necessary and sufficient conditions for this entity to be an instance of this class\n        range: string\n\n  Category:\n    is_a: OntologyElement"}');
INSERT INTO embeddings_queue VALUES(457,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','human_phenotype.txt_33',X'','FLOAT32','{"type": "txt", "source": "human_phenotype.txt", "content": "id: http://w3id.org/ontogpt/human_phenotype\ndefault_range: string\nname: human_phenotype-template\ntitle: Human Phenotype Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting human phenotypes to HPO terms\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  HP: http://purl.obolibrary.org/obo/HP_\n  human_phenotype: http://w3id.org/ontogpt/human_phenotype\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  HumanPhenotype:\n    is_a: NamedEntity\n    description: the name of a human phenotype or symptom.\n    id_prefixes:\n      - HP\n      - MONDO\n      - MESH\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:mondo, sqlite:obo:mesh, sqlite:obo:ncit\n      prompt.examples: >-\n        ascites, fever, pain, seizure, increased intracranial pressure,\n        lactic acidosis\n"}');
INSERT INTO embeddings_queue VALUES(458,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ibd.txt_34',X'','FLOAT32','{"type": "txt", "source": "ibd.txt", "content": "id: http://w3id.org/ontogpt/gocam\ndefault_range: string\nname: gocam-template\ntitle: GO-CAM Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO-CAMs\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  gocam: http://w3id.org/ontogpt/gocam/\n  GO: http://purl.obolibrary.org/obo/GO_\n  CL: http://purl.obolibrary.org/obo/CL_\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  GeneOrganismRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: Organism\n      predicate:\n        range: GeneOrganismPredicate\n  \n  GeneOrganismPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneOrganism relationships.\n\n  GeneMolecularActivityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: MolecularActivity\n        annotations:\n          prompt.examples: ubiquitination\n      predicate:\n        range: GeneMolecularActivityPredicate\n  \n  GeneMolecularActivityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneMolecularActivity relationships.\n\n  MolecularActivityMoleculeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MolecularActivity\n      object:\n        range: Molecule\n      predicate:\n        range: MolecularActivityMoleculePredicate\n  \n  MolecularActivityMoleculePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MolecularActivityMolecule relationships.\n\n  GeneGeneLocationRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: GeneLocation\n      predicate:\n        range: GeneGeneLocationPredicate\n    annotations:\n      prompt.examples: >-\n        gene1 / cytoplasm, gene2 / mitochondrion\n\n  GeneGeneLocationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneGeneLocation relationships.\n\n  GeneInteractsWithGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: Gene\n      predicate:\n        range: GeneInteractsWithGenePredicate\n\n  GeneInteractsWithGenePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the GeneInteractsWithGene relationships.\n      id:\n        pattern: ''interacts with''\n    annotations:\n      annotators: sqlite:obo:ro\n  \n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n      - PR\n      - UniProtKB\n    annotations:\n      annotators: bioportal:hgnc-nr, sqlite:obo:hgnc, sqlite:obo:pr, sqlite:obo:uniprotkb\n  \n  Pathway:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - PW\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:pw\n  \n  CellularProcess:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n  \n  MolecularActivity:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: ubiquitination\n  \n  GeneLocation:\n    is_a: NamedEntity\n    attributes:\n      id:\n        identifier: true\n        required: true\n        range: GeneLocationType\n    id_prefixes:\n      - GO\n      - CL\n      - UBERON\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:cl, sqlite:obo:uberon\n  \n  Organism:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCBITaxon\n      - EFO\n    annotations:\n      annotators: sqlite:obo:ncbitaxon, sqlite:obo:ebo\n  \n  Molecule:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - PR\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:pr\n\nenums:\n\n  GeneLocationType:\n    reachable_from:\n      source_ontology: obo:sqlite:go, obo:sqlite:cl\n      source_nodes:\n        - GO:0005575 ## cellular_component\n        - CL:0000000 ## cell"}');
INSERT INTO embeddings_queue VALUES(459,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ibd_literature.txt_35',X'','FLOAT32','{"type": "txt", "source": "ibd_literature.txt", "content": "id: http://w3id.org/ontogpt/ibd_literature\ndefault_range: string\nname: ibd-literature-template\ntitle: IBD Literature Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting information from IBD literature\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  ECTO: http://purl.obolibrary.org/obo/ECTO_\n  ExO: http://purl.obolibrary.org/obo/ExO_\n  HGNC: http://identifiers.org/hgnc/\n  NCIT: http://purl.obolibrary.org/obo/NCIT_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  GO: http://purl.obolibrary.org/obo/GO_\n  core: http://w3id.org/ontogpt/core/\n  ibdlit: http://w3id.org/ontogpt/ibd_literature/\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  ChemicalExposureGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ChemicalExposure\n      object:\n        range: Gene\n      predicate:\n        range: ChemicalExposureGenePredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the chemical exposure.\n        range: string\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the gene.\n        range: string\n\n  ChemicalExposureGenePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the ChemicalExposureGene relationships.\n    annotations:\n      annotators: sqlite:obo:ro\n  \n  DiseaseCellularProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Disease\n      object:\n        range: CellularProcess\n      predicate:\n        range: DiseaseCellularProcessPredicate\n\n  DiseaseCellularProcessPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DiseaseCellularProcess relationships.\n    annotations:\n      annotators: sqlite:obo:ro\n  \n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n      - PR\n    annotations:\n      annotators: sqlite:obo:hgnc, sqlite:obo:pr\n\n  ChemicalExposure:\n    is_a: NamedEntity\n    description: the name of the exposure, such as a exposure to a chemical toxin i.e. a chemical or molecule whose direct or indirect effects cause one or more entities to experience biological change\n    id_prefixes:\n      - CHEBI\n      - ECTO\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:ecto, sqlite:obo:chebi, sqlite:obo:ncit\n      prompt: \"CHEBI:17968 butyrate\"\n  \n  Disease:\n    is_a: NamedEntity\n    description: the name of the disease\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n  \n  CellularProcess:\n    is_a: NamedEntity\n    description: the name of the cellular process\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n"}');
INSERT INTO embeddings_queue VALUES(460,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','kidney.txt_36',X'','FLOAT32','{"type": "txt", "source": "kidney.txt", "content": "id: https://w3id.org/ontogpt/biological_process\ndefault_range: string\nname: kidney-template\ntitle: kidney-template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting kidney info from literature\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  kidney: http://w3id.org/ontogpt/kidney-template\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  CellType:\n    is_a: NamedEntity\n    id_prefixes:\n      - CL\n      - UBERON\n    annotations:\n      annotators: sqlite:obo:cl, sqlite:obo:uberon\n      prompt.examples: >-\n        tubule epithelial cell, macula densa cell, glomerular endothelial cell,\n        podocyte, mesangial cell, parietal epithelial cell\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: sqlite:obo:hgnc\n"}');
INSERT INTO embeddings_queue VALUES(461,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','maxo.txt_37',X'','FLOAT32','{"type": "txt", "source": "maxo.txt", "content": "id: http://w3id.org/ontogpt/maxo\ndefault_range: string\nname: maxo\ntitle: Template for Medical Action Extraction\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting relationships relevant to the\n  MAXO medical action ontology.\nprefixes:\n  HP: http://purl.obolibrary.org/obo/HP_\n  MAXO: http://purl.obolibrary.org/obo/MAXO_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  PATO: http://purl.obolibrary.org/obo/PATO_\n  RO: http://purl.obolibrary.org/obo/RO_\n  biolink: https://w3id.org/biolink/vocab/\n  linkml: https://w3id.org/linkml/\n  maxo_extract: http://w3id.org/ontogpt/maxo\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  OBI: http://purl.obolibrary.org/obo/OBI_\n  OGMS: http://purl.obolibrary.org/obo/ogms.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  MedicalActionSymptomRelationship:\n    is_a: Triple\n    description: >-\n      An association representing a relationships between a disease,\n      the mentioned signs and symptoms associated with that disease,\n      the medical actions relating to each symptom, and the type of\n      relationship between each action and symptom (usually TREATS\n      or PREVENTS).\n    slot_usage:\n      subject:\n        range: MedicalAction\n      object:\n        range: Symptom\n      predicate:\n        range: MedicalActionSymptomPredicate\n      qualifier:\n        description: >-\n          The primary disease the relationship is about, or specifically\n          the disease the symptom is related to.\n        range: Disease\n      subject_extension:\n        description: >-\n          A chemical or drug mentioned in the relationship between the\n          medical action and the symptom, for example,\n          \"analgesic agent therapy\" has the aspect \"analgesic\"\n        range: Chemical\n  \n  MedicalActionSymptomPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MedicalActionSymptom relationships.\n\n  MedicalAction:\n    is_a: NamedEntity\n    description: >-\n      A clinically prescribed procedure, therapy, intervention, or\n      recommendation.\n    id_prefixes:\n      - MAXO\n      - OGMS\n      - NCIT\n      - OBI\n    annotations:\n      annotators: sqlite:obo:maxo, sqlite:obo:ogms, sqlite:obo:ncit, sqlite:obo:obi\n      prompt.examples: >-\n        blood transfusion, radiation therapy,\n        cardiac catheterization, pulse oximetry, otoscopy\n\n  Disease:\n    is_a: NamedEntity\n    description: >-\n      A disposition to undergo pathological processes that exists in an organism\n      because of one or more disorders in that organism.\n    id_prefixes:\n      - MONDO\n      - HP\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:ncit\n      prompt.examples: >-\n        Beck-Fahrner syndrome, hereditary retinoblastoma, progeria,\n        diabetes mellitus, infectious otitis media\n\n  Symptom:\n    is_a: NamedEntity\n    description: >-\n      A condition or phenotype resulting from an abnormal health state.\n    id_prefixes:\n      - HP\n      - MONDO\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:mondo, sqlite:obo:ncit\n      prompt.examples: >-\n        Low serum calcitriol, hypoplasia of the thymus,\n        chronic cough, aortic stiffness, low pulse pressure\n\n  Chemical:\n    is_a: NamedEntity\n    description: >-\n      A substance that has a defined molecular structure and is produced by or\n      used in a chemical process. Includes drugs used as part of\n      medical actions.\n    id_prefixes:\n      - CHEBI\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:ncit\n      prompt.examples: >-\n        corticosteroid, folic acid, opioid analgesic\n"}');
INSERT INTO embeddings_queue VALUES(462,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','mendelian_disease.txt_38',X'','FLOAT32','{"type": "txt", "source": "mendelian_disease.txt", "content": "id: http://w3id.org/ontogpt/mendelian_disease\ndefault_range: string\nname: mendelian_disease-template\ntitle: GO-CAM Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO-CAMs\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  HGNC: http://identifiers.org/hgnc/\n  HP: http://purl.obolibrary.org/obo/HP_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  linkml: https://w3id.org/linkml/\n  mendelian_disease: http://w3id.org/ontogpt/mendelian_disease/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  MendelianDiseaseSymptomRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MendelianDisease\n      object:\n        range: Symptom\n      predicate:\n        range: MendelianDiseaseSymptomPredicate\n  \n  MendelianDiseaseSymptomPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MendelianDiseaseSymptom relationships.\n\n  MendelianDiseaseSubclassOfCategoryRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MendelianDisease\n      object:\n        range: DiseaseCategory\n      predicate:\n        range: MendelianDiseaseSubclassOfCategoryPredicate\n\n  MendelianDiseaseSubclassOfCategoryPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MendelianDiseaseCategory relationships.\n      id:\n        pattern: ''subclass of''\n\n  MendelianDiseaseInheritanceRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MendelianDisease\n      object:\n        range: Inheritance\n      predicate:\n        range: MendelianDiseaseInheritancePredicate\n\n  MendelianDiseaseInheritancePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MendelianDiseaseInheritance relationships.\n\n  MendelianDiseaseGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MendelianDisease\n      object:\n        range: Gene\n      predicate:\n        range: MendelianDiseaseGenePredicate\n\n  MendelianDiseaseGenePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MendelianDiseaseGene relationships.\n\n  MendelianDiseaseOnsetRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MendelianDisease\n      object:\n        range: Onset\n      predicate:\n        range: MendelianDiseaseOnsetPredicate\n\n  MendelianDiseaseOnsetPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MendelianDiseaseOnset relationships.\n\n  MendelianDisease:\n    is_a: DiseaseCategory\n    attributes:\n      name:\n        description: the name of the disease\n      description:\n        description: a description of the disease\n      synonyms:\n        multivalued: true\n\n  DiseaseCategory:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n      prompt.examples: >-\n        peroxisome biogenesis disorder, Zellweger syndrome spectrum (PBD-ZSS),\n        lysosomal disease, autosomal recessive disorder\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - PR\n    annotations:\n      annotators: bioportal:hgnc-nr, sqlite:obo:pr\n      prompt.examples: PEX1, PEX2, PEX3\n\n  Symptom:\n    is_a: NamedEntity\n    attributes:\n      characteristic:\n        range: string\n      affects:\n        range: string\n      severity:\n        range: string\n      onset_of_symptom:\n        range: Onset\n    id_prefixes:\n      - HP\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:mondo\n      prompt.examples: >-\n        PBD-ZSS, sensorineural hearing loss, pigmentary retinal degeneration\n\n  Onset:\n    is_a: NamedEntity\n    attributes:\n      years_old:\n        range: integer\n      decades:\n        range: integer\n        multivalued: true\n      juvenile_or_adult:\n        range: string\n    id_prefixes:\n      - HP\n      - HSAPDV\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:hsapdv\n      prompt.examples: adult, juvenile, first decade\n\n  Inheritance:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n      - GENO\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:geno\n      prompt.examples: autosomal recessive\n"}');
INSERT INTO embeddings_queue VALUES(463,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','metabolic_process.txt_39',X'','FLOAT32','{"type": "txt", "source": "metabolic_process.txt", "content": "id: https://w3id.org/ontogpt/metabolic_process\ndefault_range: string\nname: metabolic-process-template\ntitle: metabolic Process Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO-CAMs\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  bp: http://w3id.org/ontogpt/metabolic-process-template\n  GO: http://purl.obolibrary.org/obo/go/extensions/go-plus.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  MetabolicProcessSubclassOfMetabolicProcessCategoryRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MetabolicProcess\n      object:\n        range: MetabolicProcessCategory\n      predicate:\n        range: MetabolicProcessSubclassOfMetabolicProcessCategoryPredicate\n  \n  MetabolicProcessSubclassOfMetabolicProcessCategoryPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetabolicProcessSubclassOfMetabolicProcessCategory relationships.\n      id:\n        pattern: ''subclass of''\n\n  MetabolicProcessInputsChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MetabolicProcess\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: MetabolicProcessInputsChemicalEntityPredicate\n  \n  MetabolicProcessInputsChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetabolicProcessInputsChemicalEntity relationships.\n      id:\n        pattern: ''inputs''\n\n  MetabolicProcessOutputsChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MetabolicProcess\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: MetabolicProcessOutputsChemicalEntityPredicate\n  \n  MetabolicProcessOutputsChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetabolicProcessOutputsChemicalEntity relationships.\n      id:\n        pattern: ''outputs''\n\n  MetabolicProcess:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: the name of the metabolic process\n      description:\n        description: a textual description of the metabolic process\n      synonyms:\n        description: alternative names of the metabolic process\n        multivalued: true\n\n  MetabolicProcessCategory:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi\n"}');
INSERT INTO embeddings_queue VALUES(464,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','metagenome_study.txt_40',X'','FLOAT32','{"type": "txt", "source": "metagenome_study.txt", "content": "id: http://w3id.org/ontogpt/metagenome\ndefault_range: string\nname: environmental-metagenome\ntitle: Environmental Metagenome Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Environmental Metagenome Studies\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  eg: http://w3id.org/ontogpt/environmental-metagenome/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  StudyConductedInEnvironmentRelationship:\n    is_a: Triple\n    description: List of environmental systems or biomes in which the study was conducted.\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Environment\n      predicate:\n        range: StudyConductedInEnvironmentPredicate\n\n  StudyConductedInEnvironmentPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyConductedInEnvironment relationships.\n      id:\n        pattern: ''conducted in''\n\n  StudyAppliesTreatmentRelationship:\n    is_a: Triple\n    description: List of treatments applied in the study.\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Treatment\n      predicate:\n        range: StudyAppliesTreatmentPredicate\n\n  StudyAppliesTreatmentPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyAppliesTreatment relationships.\n      id:\n        pattern: ''applies''\n\n  StudyMeasurementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Measurement\n      predicate:\n        range: StudyMeasurementPredicate\n\n  StudyMeasurementPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyMeasurement relationships.\n\n  StudyConductedInLocationRelationship:\n    is_a: Triple\n    description: List of sites at which the study was conducted.\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Location\n      predicate:\n        range: StudyConductedInLocationPredicate\n\n  StudyConductedInLocationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyConductedInLocation relationships.\n      id:\n        pattern: ''conducted in''\n\n  StudySamplesEnvironmentalMaterialRelationship:\n    is_a: Triple\n    description: List the environmental material that was sampled.\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: EnvironmentalMaterial\n      predicate:\n        range: StudySamplesEnvironmentalMaterialPredicate\n\n  StudySamplesEnvironmentalMaterialPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudySamplesEnvironmentalMaterial relationships.\n      id:\n        pattern: ''samples''\n\n  StudySequencingTechnologyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: SequencingTechnology\n      predicate:\n        range: StudySequencingTechnologyPredicate\n\n  StudySequencingTechnologyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudySequencingTechnology relationships.\n\n  StudyOrganismRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Study\n      object:\n        range: Organism\n      predicate:\n        range: StudyOrganismPredicate\n\n  StudyOrganismPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the StudyOrganism relationships.\n\n  Study:\n    is_a: NamedEntity\n\n  Location:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n      - GAZ\n    annotations:\n      annotators: sqlite:obo:envo, bioportal:gaz\n\n  EnvironmentalMaterial:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo\n\n  Environment:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo\n\n  Variable:\n    is_a: NamedEntity\n    id_prefixes:\n      - ENVO\n      - MIXS\n      - PATO\n    annotations:\n      annotators: sqlite:obo:envo, sqlite:obo:mixs, sqlite:obo:pato, bioportal:bero\n      prompt.examples: temperature, pH, salinity\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:uo, bioportal:ncit\n  \n  SequencingTechnology:\n    is_a: NamedEntity\n    id_prefixes:\n      - IDO\n      - EFO\n    annotations:\n      annotators: sqlite:obo:ido, sqlite:obo:efo, bioportal:bero\n\n  Treatment:\n    is_a: NamedEntity\n    id_prefixes:\n      - PECO\n      - OBI\n    annotations:\n      annotators: sqlite:obo:peco, sqlite:obo:obi, bioportal:bero\n\n  Organism:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n\n  UnitMeasurementUnitRelationship:\n    is_a: Triple\n    slot_usage:  \n      subject:\n        range: Unit\n      object:\n        range: Unit\n      predicate:\n        range: UnitMeasurementUnitPredicate\n      value:\n        description: the value of the measurement  \n        range: float\n  \n  UnitMeasurementUnitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the UnitMeasurementUnit relationships.\n      id:\n        pattern: ''measurement''\n\n  VariableCausesVariableRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Variable\n      object:\n        range: Variable\n      predicate:\n        range: VariableCausesVariablePredicate\n      study:\n        range: Study\n\n  VariableCausesVariablePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the VariableCausesVariable relationships.\n      id:\n        pattern: ''causes''\n"}');
INSERT INTO embeddings_queue VALUES(465,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','mic.txt_41',X'','FLOAT32','{"type": "txt", "source": "mic.txt", "content": "id: http://w3id.org/ontogpt/mic\ndefault_range: string\nname: mic\ntitle: Micronutrient Information Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for micronutrient information from text,\n  including its participation in biochemical pathways\n  and relationships to genes and diseases.\n  Intended for use with the Micronutrient Information\n  Center, a resource curated and managed by the Linus\n  Pauling Institute at Oregon State University.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  foodon: http://purl.obolibrary.org/obo/foodon_\n  chebi: http://purl.obolibrary.org/obo/CHEBI_\n  GO: http://purl.obolibrary.org/obo/GO_\n  mic: http://w3id.org/ontogpt/mic\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  NutrientAssociatedWithFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Feature\n      predicate:\n        range: NutrientAssociatedWithFeaturePredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A associated with Systemic Lupus Erythematosus (5,6);\n        Vitamin A associated with Rheumatoid Arthritis (5,6)\",\n        \"Iron supplementation associated with anemia (5,6)\",\n        \"Vitamin A associated with bone cancer (8)\"\n  \n  NutrientAssociatedWithFeaturePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientAssociatedWithFeature relationships.\n      id:\n        pattern: ''associated with''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientIsSubstanceThatTreatsFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Feature\n      predicate:\n        range: NutrientIsSubstanceThatTreatsFeaturePredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A is substance that treats Systemic Lupus Erythematosus (5,6);\n        Vitamin A is substance that treats Rheumatoid Arthritis (5,6)\",\n        \"Iron supplementation is substance that treats anemia (5,6)\",\n        \"Vitamin A is substance that treats bone cancer (8)\"\n\n  NutrientIsSubstanceThatTreatsFeaturePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientIsSubstanceThatTreatsFeature relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientIncreasesRiskOfFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Feature\n      predicate:\n        range: NutrientIncreasesRiskOfFeaturePredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A increases risk of Systemic Lupus Erythematosus (5,6);\n        Vitamin A increases risk of Rheumatoid Arthritis (5,6)\",\n        \"Iron supplementation increases risk of anemia (5,6)\",\n        \"Vitamin A increases risk of bone cancer (8)\"\n\n  NutrientIncreasesRiskOfFeaturePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientIncreasesRiskOfFeature relationships.\n      id:\n        pattern: ''increases risk of''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientDecreasesRiskOfFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Feature\n      predicate:\n        range: NutrientDecreasesRiskOfFeaturePredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A decreases risk of Systemic Lupus Erythematosus (5,6);\n        Vitamin A decreases risk of Rheumatoid Arthritis (5,6)\",\n        \"Iron supplementation decreases risk of anemia (5,6)\",\n        \"Vitamin A decreases risk of bone cancer (8)\"\n\n  NutrientDecreasesRiskOfFeaturePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientDecreasesRiskOfFeature relationships.\n      id:\n        pattern: ''decreases risk of''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientPreventsFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Feature\n      predicate:\n        range: NutrientPreventsFeaturePredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A prevents Systemic Lupus Erythematosus (5,6);\n        Vitamin A prevents Rheumatoid Arthritis (5,6)\",\n        \"Iron supplementation prevents anemia (5,6)\",\n        \"Vitamin A prevents bone cancer (8)\"\n\n  NutrientPreventsFeaturePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientPreventsFeature relationships.\n      id:\n        pattern: ''prevents''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientParticipatesInBiologicalProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: NutrientParticipatesInBiologicalProcessPredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A participates in Insulin Signaling (5,6);\n        Vitamin A participates in DNA repair (5,6)\",\n        \"Vitamin A participates in Insulin Signaling (5,6)\"\n\n  NutrientParticipatesInBiologicalProcessPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientParticipatesInBiologicalProcess relationships.\n      id:\n        pattern: ''participates in''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientAssociatedWithBiologicalProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: NutrientAssociatedWithBiologicalProcessPredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A associated with Insulin Signaling (5,6);\n        Vitamin A associated with DNA repair (5,6)\",\n        \"Vitamin A associated with Insulin Signaling (5,6)\"\n  \n  NutrientAssociatedWithBiologicalProcessPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientAssociatedWithBiologicalProcess relationships.\n      id:\n        pattern: ''associated with''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientInteractsWithNutrientRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Nutrient\n      predicate:\n        range: NutrientInteractsWithNutrientPredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A interacts with Vitamin D (5,6);\n        Vitamin A interacts with Vitamin E (5,6)\",\n        \"Vitamin A interacts with Vitamin D (5,6)\"\n\n  NutrientInteractsWithNutrientPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientInteractsWithNutrient relationships.\n      id:\n        pattern: ''interacts with''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientSupportsHealthOfAnatomyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: Anatomy\n      predicate:\n        range: NutrientSupportsHealthOfAnatomyPredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A supports the health of teeth (5,6);\n        Vitamin A supports the health of skin (5,6)\",\n\n  NutrientSupportsHealthOfAnatomyPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientSupportsHealthOfAnatomy relationships.\n      id:\n        pattern: ''supports health of''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n\n  NutrientProvidedByFoodOrSupplementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Nutrient\n      object:\n        range: FoodOrSupplement\n      predicate:\n        range: NutrientProvidedByFoodOrSupplementPredicate\n    annotations:\n      prompt.examples: >-\n        \"Vitamin A provided by butter (5,6);\n        \"Vitamin A provided by apple (5,6)\"\n\n  NutrientProvidedByFoodOrSupplementPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - biolink\n    attributes:\n      label:\n        description: The predicate for the NutrientProvidedByFoodOrSupplement relationships.\n      id:\n        pattern: ''provided by''\n    annotations:\n      annotators: sqlite:obo:ro, sqlite:obo:biolink\n  \n  Nutrient:\n    is_a: NamedEntity\n    description: >-\n      The name of a nutrient, including vitamins and\n      minerals.\n    id_prefixes:\n      - CHEBI\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:foodon\n\n  Feature:\n    is_a: NamedEntity\n    description: >-\n      The name of a biological feature or\n      other health statuses, as well as observable\n      properties of an organism.\n    id_prefixes:\n      - MONDO\n      - HP\n      - EFO\n    annotations:\n      annotators: sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:efo\n      prompt.examples: >-\n        disease, symptom, abnormality, body weight,\n        insulin degradation, Alzheimer''s disease, systemic lupus erythematosus,\n        rheumatoid arthritis, sickle cell anemia, or Barth syndrome,\n        fever, headache, short attention span, petechiae,\n        telangiectasia\n\n  BiologicalProcess:\n    is_a: NamedEntity\n    description: >-\n      A biological process is an activity or series of\n      activities that occur in a cell or organism\n    attributes:\n      id:\n        range: GOBiologicalProcessType\n        identifier: true\n        required: true\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n      prompt.examples: >-\n        lipid metabolism,\n        nuclear axial expansion,\n        intracellular transport, ribosomal subunit export from nucleus,\n        insulin signaling, DNA repair\n\n  Anatomy:\n    is_a: NamedEntity\n    description: >-\n      The name of an anatomical part or system.\n    id_prefixes:\n      - UBERON\n    annotations:\n      annotators: sqlite:obo:uberon\n      prompt.examples: >-\n        teeth, skin, cardiovascular system, digestive system,\n        liver\n\n  FoodOrSupplement:\n    is_a: NamedEntity\n    description: The name of a food or supplement.\n    id_prefixes:\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:foodon\n      prompt.examples: >-\n        butter, apple, watermelon, beef, breakfast cereal\n\nenums:\n  GOBiologicalProcessType:\n    reachable_from:\n      source_ontology: sqlite:obo:go\n      source_nodes:\n        - GO:0008150  # biological_process\n"}');
INSERT INTO embeddings_queue VALUES(466,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','miro.txt_42',X'','FLOAT32','{"type": "txt", "source": "miro.txt", "content": "id: http://w3id.org/ontogpt/miro\ndefault_range: string\nname: miro\ntitle: MIRO Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting the minimal information for reporting\n  an ontology, as per the MIRO guidelines.\n  See doi:10.1186/s13326-017-0172-7\n  The target for this template should be a report or publication\n  describing a single ontology.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  onto_usage: http://w3id.org/ontogpt/onto_usage\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  OntologyIncorporatesCitedOntologyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: CitedOntology\n      predicate:\n        range: OntologyIncorporatesCitedOntologyPredicate\n  \n  OntologyIncorporatesCitedOntologyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyIncorporatesCitedOntology relationships.\n      id:\n        pattern: ''incorporates''\n\n  OntologyCompetesWithCitedOntologyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: CitedOntology\n      predicate:\n        range: OntologyCompetesWithCitedOntologyPredicate\n\n  OntologyCompeteWithCitedOntologyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyCompetesWithCitedOntology relationships.\n      id:\n        pattern: ''competes with''\n\n  OntologyOwnerRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: Owner\n      predicate:\n        range: OntologyOwnerPredicate\n\n  OntologyOwnerPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyOwner relationships.\n\n  OntologyUseExampleRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: UseExample\n      predicate:\n        range: OntologyUseExamplePredicate\n\n  OntologyUseExamplePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyUseExample relationships.\n\n  Ontology:\n    is_a: NamedEntity\n    attributes:\n      name:\n        description: >-\n          The full name of the ontology, including the acronym and the\n          version number referred to in the report.\n        range: string\n      license:\n        description: >-\n          The licence which governs the permissions surrounding the ontology.\n        range: string\n      url:\n        description: >-\n          The web location where the ontology file is available.\n        range: string\n      repository:\n        description: >-\n          The web location (URL) of the version control system where current\n          and previous versions of the ontology can be found.\n        range: string\n      methodological_framework:\n        description: >-\n          A name or description of the steps taken to develop the ontology.\n          This should describe the overall organisation of the ontology\n          development process.\n        range: string\n      need:\n        description: >-\n          Justification of why the ontology is required.\n        range: string\n      target_audience:\n        description: >-\n          The community or organisation performing some task or use for which\n          the ontology was developed.\n        range: string\n      scope_and_coverage:\n        description: >-\n          The domain or field of interest for the ontology and the boundaries,\n          granularity of representation and coverage of the ontology. State\n          the requirements of the ontology, such as the competency questions\n          it should satisfy. A visualisation or tabular representation is\n          optional, but often helpful to illustrate the scope.\n        range: string\n      development_community:\n        description: >-\n          The person, group of people or organisation that actually creates\n          the content of the ontology. This is distinct from the Ontology\n          Owner that is concerned with the management of the\n          ontology''s development.\n        range: string\n      communication:\n        description: >-\n          Location, usually URL, of the email list and/or the issue tracking\n          systems used for development and managing feature requests for the\n          ontology.\n        range: string\n      knowledge_acquisition_method:\n        description: >-\n          How the knowledge in the ontology was gathered, sorted, verified,\n          etc.\n        range: string\n      source_knowledge_location:\n        description: >-\n          The location of the source whence the knowledge was gathered.\n        range: string\n      content_selection:\n        description: >-\n          The prioritisation of entities to be represented in the ontology\n          and how that prioritisation was achieved. Some knowledge is more\n          important or of greater priority to be in the ontology to support\n          the requirements of that ontology.\n        range: string\n      knowledge_representation_language:\n        description: >-\n          The knowledge representation language used and why it was used. For\n          a language like OWL, indicate the OWL profile and expressivity.\n        range: string\n      development_environment:\n        description: >-\n          The tool(s) used in developing the ontology.\n        range: string\n      ontology_metrics:\n        description: >-\n          List of the numbers of classes, properties,\n          axioms and types of axioms, rules and individuals in the ontology.\n        range: string\n        multivalued: true\n      entity_naming_convention:\n        description: >-\n          The naming scheme for the entities in the ontology, capturing\n          orthography, organisation rules, acronyms, and so on.\n        range: string\n      identifier_generation_policy:\n        description: >-\n          The scheme used for creating identifiers for entities in the\n          ontology. State whether identifiers are semantic-free or meaningful.\n        range: string\n      entity_metadata_policy:\n        description: >-\n          What metadata for each entity is to be present. This could include,\n          but not be limited to: A natural language definition, editor, edit\n          history, examples, entity label and synonyms, etc.\n        range: string\n      upper_ontology:\n        description: >-\n          If an upper ontology is used, which one is used and why is it used?\n          If not used, then why not?\n        range: string\n      ontology_relationships:\n        description: >-\n          The relationships or properties used in the ontology, which were\n          used and why? Were new relationships required? Why?\n        range: string\n      axiom_patterns:\n        description: >-\n          An axiom pattern is a regular design of axioms or a template for\n          axioms used to represent a category of entities or common aspects\n          of a variety of types of entities. An axiom pattern may comprise\n          both asserted and inferred axioms. The aim of a pattern is to\n          achieve a consistent style of representation. An important family\n          of axiom patterns are Ontology Design pattern (ODP) which are\n          commonly used solutions for issues in representation.\n        range: string\n      dereferencable_iri:\n        description: >-\n          State whether or not the IRI used are dereferenceable to a Web\n          resource. Provide any standard prefix (CURIE).\n        range: string\n      sustainability_plan:\n        description: >-\n          State whether the ontology will be actively maintained and\n          developed. Describe a plan for how the ontology will be kept up to\n          date.\n        range: string\n      deprecation_strategy:\n        description: >-\n          Describe the procedures for managing entities that become removed,\n          split or redefined.\n        range: string\n      versioning_policy:\n        description: >-\n          State or make reference to the policy that governs when new versions\n          of the ontology are created and released.\n        range: string\n      testing:\n        description: >-\n          Description of the procedure used to judge whether the ontology\n          achieves the claims made for the ontology. State, for example,\n          whether the ontology is logically consistent, answers the queries\n          it claims to answer, and whether it can answer them in a time that\n          is reasonable for the projected use case scenario (benchmarking).\n        range: string\n      evaluation:\n        description: >-\n          A determination of whether the ontology is of value and\n          significance. An evaluation should show that the motivation is\n          justified and that the objectives of the ontology\u2019s development are\n          met effectively and satisfactorily. Describe whether or not the\n          ontology meets its stated requirements, competency questions and\n          goals.\n        range: string\n      institutional_endorsement:\n        description: >-\n          State whether the ontology is endorsed by the W3C, the OBO foundry\n          or some organisation representing a community.\n        range: string\n      evidence_of_use:\n        description: >-\n          An illustration of active projects and applications that use the\n          ontology.\n        range: string\n\n  Owner:\n    is_a: NamedEntity\n    attributes:\n      name:\n        description: >-\n          The name of a person, group of people, organization, or consortium\n          that manages development of the ontology.\n        range: string\n      affiliation:\n        description: >-\n          The name of the organization with which the owner is affiliated.\n        range: string\n      contact:\n        description: >-\n          The contact details of the owner. This is typically an email address.\n        range: string\n\n  CitedOntology:\n    is_a: Ontology\n    attributes:\n      version:\n        description: >-\n          The version of the ontology being cited.\n        range: string\n      citation:\n        description: >-\n          The citation for the ontology being cited.\n        range: string\n      integration:\n        description: >-\n          A description of how the ontology being cited is integrated into the\n          ontology being reported.\n        range: string\n\n  UseExample:\n    is_a: NamedEntity\n    attributes:\n      example_description:\n        description: >-\n          A description of the ontology in use in its application setting or\n          use case.\n        range: string\n"}');
INSERT INTO embeddings_queue VALUES(467,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','mondo_simple.txt_43',X'','FLOAT32','{"type": "txt", "source": "mondo_simple.txt", "content": "id: http://w3id.org/ontogpt/mondo_simple\ndefault_range: string\nname: mondo_simple\ntitle: Simple MONDO Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  Simple MONDO Disease Ontology Extraction Template\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  linkml: https://w3id.org/linkml/\n  mondo_simple: http://w3id.org/ontogpt/emapa_simple\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  OntologyTerm:\n    is_a: NamedEntity\n    description: The name of a MONDO Disease Ontology term.\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n      prompt.examples: >-\n        neurothekoma, retinal vasculitis,\n        chicken monocytic leukemia, neoplasm of spinal cord,\n        moyamoya disease 3\n"}');
INSERT INTO embeddings_queue VALUES(468,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','nmdc_schema_data.txt_44',X'','FLOAT32','{"type": "txt", "source": "nmdc_schema_data.txt", "content": "id: http://w3id.org/ontogpt/nmdc-schema-data\ndefault_range: string\nname: nmdc-schema-data\ntitle: nmdc-schema-data\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for populating nmdc-schema required slots\n  from data entries. Primarily, this involves three different\n  levels corresponding to ENVO terms, as well as conversion\n  of NLCD values and FAO soil taxonomy classes to ENVO.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  nmdcsd: http://w3id.org/ontogpt/nmdc-schema-data\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  EnvironmentalMaterial:\n    is_a: NamedEntity\n    description: >-\n      The environmental material that was sampled\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo\n\n  Environment:\n    is_a: NamedEntity\n    description: >-\n      The environmental context in which the study was conducted\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo\n"}');
INSERT INTO embeddings_queue VALUES(469,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','ontology_class.txt_45',X'','FLOAT32','{"type": "txt", "source": "ontology_class.txt", "content": "id: https://w3id.org/ontogpt/ontology_class\ndefault_range: string\nname: ontology-class\ntitle: Ontology Class Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Ontology Classes\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  oc: http://w3id.org/ontogpt/ontology-class-template\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  OntologyOntologyCategoryRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: OntologyCategory\n      predicate:\n        range: OntologyOntologyCategoryPredicate\n\n  OntologyOntologyCategoryPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyOntologyCategory relationships.\n\n  OntologySubclassOfOntologyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: Ontology\n      predicate:\n        range: OntologySubclassOfOntologyPredicate\n  \n  OntologySubclassOfOntologyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologySubclassOfOntology relationships.\n      id:\n        pattern: ''subclass of''\n\n  OntologyLogicalDefinitionOntologyRelationship:\n    is_a: Triple\n    description: >-\n      The necessary and sufficient conditions for an entity to be an instance of a class\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: Ontology\n      predicate:\n        range: OntologyLogicalDefinitionOntologyPredicate\n    annotations:\n      prompt.examples: bone part of hand\n  \n  OntologyLogicalDefinitionOntologyPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the OntologyLogicalDefinitionOntology relationships.\n      id:\n        pattern: ''logical definition''\n    annotations:\n      annotators: sqlite:obo:ro\n  \n  Ontology:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: the name of the main entity being defined\n      description:\n        description: a textual description of the entity\n      synonyms:\n        description: alternative names of the entity\n        multivalued: true\n  \n  OntologyCategory:\n    is_a: NamedEntity\n    description: >-\n      the category to which this entity belongs.\n      This may be taken from an upper level ontology such as COB,\n      BioLink, or UMLS semantic types.\n"}');
INSERT INTO embeddings_queue VALUES(470,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','onto_usage.txt_46',X'','FLOAT32','{"type": "txt", "source": "onto_usage.txt", "content": "id: http://w3id.org/ontogpt/onto_usage\ndefault_range: string\nname: onto_usage\ntitle: Ontology Usage Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting statements about the usage of ontologies in\n  scientific literature.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  onto_usage: http://w3id.org/ontogpt/onto_usage\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  OntologyUsedForUseCaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ontology\n      object:\n        range: UseCase\n      predicate:\n        range: OntologyUsedForUseCasePredicate\n    annotations:\n      prompt.examples: >-\n        Gene Ontology USED FOR gene function prediction,\n        MONDO Disease Ontology USED FOR disease diagnosis\n  \n  OntologyUsedForUseCasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the OntologyUsedForUseCase relationships.\n      id:\n        pattern: ''used for''\n\n  Ontology:\n    is_a: NamedEntity\n    description: a single ontology name or abbreviation.\n    annotations:\n      prompt.examples: >-\n        Gene Ontology, GO, Human Phenotype Ontology, HPO,\n        MONDO Disease Ontology\n  \n  UseCase:\n    is_a: NamedEntity\n    description: >-\n      a specific application or context in which\n      an ontology is used\n    annotations:\n      prompt.examples: >-\n        gene function prediction, disease diagnosis\n"}');
INSERT INTO embeddings_queue VALUES(471,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','pathology.txt_47',X'','FLOAT32','{"type": "txt", "source": "pathology.txt", "content": "id: http://w3id.org/ontogpt/pathology\ndefault_range: string\nname: pathology\ntitle: Pathology Grounding Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting and grounding pathology descriptions from text.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  PATO: http://purl.obolibrary.org/obo/PATO_\n  UBERON: http://purl.obolibrary.org/obo/UBERON_\n  linkml: https://w3id.org/linkml/\n  pathology: http://w3id.org/ontogpt/pathology\nkeywords:\n  - pathology\n  - phenotype\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Pathology:\n    is_a: NamedEntity\n    attributes:\n      severity:\n        description: >-\n          The severity of the pathology.\n        range: SeverityLevelType\n      is_benign:\n        description: >-\n          Whether the overall pathology appears to be benign and not malignant.\n        range: boolean\n      overall_classification_one:\n        description: >-\n          The final classification of the overall pathology.\n        range: PathologyClassificationOneType\n      overall_classification_two:\n        description: >-\n          The final classification of the overall pathology.\n        range: PathologyClassificationTwoType\n\n  PathologyDiagnosisRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Pathology\n      object:\n        range: Diagnosis\n      predicate:\n        range: PathologyDiagnosisPredicate\n\n  PathologyDiagnosisPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the PathologyDiagnosis relationships.\n\n  PathologyQualifierRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Pathology\n      object:\n        range: Qualifier\n      predicate:\n        range: PathologyQualifierPredicate\n\n  PathologyStatementQualifierPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the PathologyStatementQualifier relationships.\n\n  PathologyAnatomicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Pathology\n      object:\n        range: AnatomicalEntity\n      predicate:\n        range: PathologyAnatomicalEntityPredicate\n\n  PathologyAnatomicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the PathologyAnatomicalEntity relationships.\n\n  Diagnosis:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCIT\n      - MESH\n      - MONDO\n    annotations:\n      annotators: bioportal:SNOMEDCT, bioportal:ICD10CM, sqlite:obo:ncit, sqlite:obo:mesh, sqlite:obo:mondo\n      prompt.example: >-\n        duodenum, colonic mucosa, liver, colon, gastric mucosa\n\n  AnatomicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - UBERON\n    annotations:\n      annotators: sqlite:obo:uberon\n\n  Risk:\n    is_a: NamedEntity\n    description: >-\n      A risk factor for development of more severe pathologies,\n      including but not limited to cancer. These will be in the format\n      \"risk factor (potential pathology)\".\n    attributes:\n      risk_factor:\n        description: >-\n          The risk factor for development of more severe pathologies.\n        range: string\n      potential_pathology:\n        description: >-\n          The pathology that the risk factor is a risk for.\n        range: Diagnosis\n\n  Qualifier:\n    is_a: NamedEntity\n    id_prefixes:\n      - PATO\n    annotations:\n      annotators: sqlite:obo:pato\n      prompt.example: active, chronic, focal\n\nenums:\n  SeverityLevelType:\n    description: >-\n      The severity of a pathology.\n    permissible_values:\n      mild:\n        description: >-\n          A pathology that is mild in severity.\n        meaning: PATO:0000394\n      moderate:\n        description: >-\n          A pathology that is moderate in severity.\n        meaning: PATO:0000395\n      severe:\n        description: >-\n          A pathology that is severe in severity.\n        meaning: PATO:0000396\n      Not Specified:\n        description: >-\n          The severity of the pathology is not specified.\n  PathologyClassificationOneType:\n    description: >-\n      The final classification of the overall pathology. This uses\n      a system of five categories, identified numerically.\n    permissible_values:\n      1:\n        description: >-\n          No significant pathological abnormality was observed.\n      2:\n        description: >-\n          Neoplastic malignant growth was observed.\n      3:\n        description: >-\n          Dysplastic pathology was observed (i.e., abnormal or atypical cell\n          growth and/or appearance).\n      4:\n        description: >-\n          Proliferative non-neoplastic pathology was observed.\n      5:\n        description: >-\n          Inflammatory or other non-proliferative abnormalities were observed.\n  PathologyClassificationTwoType:\n    description: >-\n      The final classification of the overall pathology. This must be a\n      code, \"2\" or \"2a\".\n    permissible_values:\n      1:\n        description: >-\n          No significant pathological abnormality was observed.\n      2:\n        description: >-\n          Neoplastic malignant pathology was observed.\n      2a:\n        description: >-\n          Carcinoma was observed.\n      2b:\n        description: >-\n          Sarcoma was observed.\n      2c:\n        description: >-\n          Lymphoma was observed.\n      2d:\n        description: >-\n          Other neoplastic malignant growth was observed.\n      3:\n        description: >-\n          Dysplastic pathology was observed (i.e., abnormal or atypical cell\n          growth and/or appearance).\n      3a:\n        description: >-\n          High grade dysplasia was observed.\n      3b:\n        description: >-\n          Low grade dysplasia was observed.\n      4:\n        description: >-\n          Proliferative non-neoplastic pathology was observed.\n      5:\n        description: >-\n          Inflammatory or other non-proliferative abnormalities were observed.\n      5a:\n        description: >-\n          Acute or active inflammation was observed.\n      5b:\n        description: >-\n          Chronic inflammation was observed.\n      5c:\n        description: >-\n          Eosinophils were present.\n      5d:\n        description: >-\n          Granulomas / histiocytes / macrophages were present.\n      5e:\n        description: >-\n          Organisms (Bacterial, Viral, Parasitic, Fungal) were present.\n      5f:\n        description: >-\n          Collagen abnormalities were observed.\n      5g:\n        description: >-\n          Vessel abnormalities were observed.\n      5h:\n        description: >-\n          Apoptosis was observed.\n      5i:\n        description: >-\n          Mast cells were observed.\n      5j:\n        description: >-\n          Amyloid was observed.\n"}');
INSERT INTO embeddings_queue VALUES(472,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','personinfo.txt_48',X'','FLOAT32','{"type": "txt", "source": "personinfo.txt", "content": "id: https://w3id.org/linkml/examples/personinfo\ndefault_range: string\nname: personinfo\ntitle: Person Info\nprefixes:\n  linkml: https://w3id.org/linkml/\n  personinfo: https://w3id.org/linkml/examples/personinfo/\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Person:\n    is_a: NamedEntity\n    description: A person.\n    attributes:\n      full_name:\n        description: >-\n          The full name of the person.\n        range: string\n      id:\n        description: >-\n          A unique identifier for the person.\n          This is their full name without spaces\n          or special characters.\n        identifier: true\n        required: True\n        range: string\n"}');
INSERT INTO embeddings_queue VALUES(473,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','phenopackets.txt_49',X'','FLOAT32','{"type": "txt", "source": "phenopackets.txt", "content": "id: http://w3id.org/ontogpt/phenopackets\ndefault_range: string\nname: phenopackets\ntitle: Phenopackets Schema v2\ndescription: >-\n  A template for extracting a phenopacket, an anonymous\n  phenotypic description of an individual or biosample\n  with potential genes of interest and/or diagnoses.\n  This template is based on the Phenopackets schema v2,\n  originally defined in Protobuf. All classes are\n  defined in a single schema here, with their corresponding\n  module provided in a comment (e.g., core/individual).\n  Much of this modeling is adapted from Chris Mungall''s\n  linkml-phenopackets\n  (see https://github.com/cmungall/linkml-phenopackets).\nprefixes:\n  ARGO: https://docs.icgc-argo.org/dictionary/\n  EFO: http://www.ebi.ac.uk/efo/EFO_\n  GENO: http://purl.obolibrary.org/obo/GENO_\n  HP: http://purl.obolibrary.org/obo/HP_\n  LOINC: https://loinc.org/\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  NCIT: http://purl.obolibrary.org/obo/NCIT_\n  UBERON: http://purl.obolibrary.org/obo/UBERON_\n  UCUM: http://unitsofmeasure.org/\n  UO: http://purl.obolibrary.org/obo/UO_\n  linkml: https://w3id.org/linkml/\n  phenopackets_schema: http://w3id.org/ontogpt/phenopackets\nsee_also:\n  - https://github.com/phenopackets/phenopacket-schema\n  - https://github.com/cmungall/linkml-phenopackets\nkeywords:\n  - phenotype\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Person:\n    is_a: NamedEntity\n    description: An individual human being.\n\n  FamilyContainsPersonRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Family\n      object:\n        range: Person\n      predicate:\n        range: FamilyContainsPersonPredicate\n\n  FamilyContainsPersonPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the FamilyContainsPerson relationships.\n      id:\n        pattern: ''contains''\n\n  Family:\n    is_a: NamedEntity\n    description: >-\n      Phenotype, sample and pedigree data required for a genomic diagnosis.\n    attributes:\n      id:\n        description: An identifier specific for this family.\n        range: string\n        identifier: true\n        required: true\n      consanguinous_parents:\n        description: >-\n          Flag to indicate that parents are consanguinous.\n        range: boolean\n\n  CohortCharacterizedByPhenotypicFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Cohort\n      object:\n        range: PhenotypicFeature\n      predicate:\n        range: CohortCharacterizedByPhenotypicFeaturePredicate\n\n  CohortCharacterizedByPhenotypicFeaturePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CohortCharacterizedByPhenotypicFeature relationships.\n      id:\n        pattern: ''characterized by''\n\n  CohortContainsPersonRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Cohort\n      object:\n        range: Person\n      predicate:\n        range: CohortContainsPersonPredicate\n\n  CohortContainsPersonPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CohortContainsPerson relationships.\n      id:\n        pattern: ''contains''\n\n  Cohort:\n    is_a: NamedEntity\n    description: >-\n      A group of individuals related in some phenotypic or genotypic aspect.\n    attributes:\n      id:\n        description: An identifier specific for this cohort.\n        range: string\n        identifier: true\n        required: true\n\n  BioSamplePhenotypicFeatureRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BioSample\n      object:\n        range: PhenotypicFeature\n      predicate:\n        range: BioSamplePhenotypicFeaturePredicate\n\n  BioSamplePhenotypicFeaturePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BioSamplePhenotypicFeature relationships.\n\n  Biosample:\n    is_a: NamedEntity\n    description: >-\n      A Biosample refers to a unit of biological material from which the\n      substrate molecules (e.g. genomic DNA, RNA, proteins) for molecular\n      analyses (e.g. sequencing, array hybridisation, mass-spectrometry) are\n      extracted.\n    attributes:\n      id:\n        description: >-\n          A unique identifier for the biosample.\n        range: string\n        identifier: true\n        required: true\n        annotations:\n          prompt.examples: Patient1_Biosample1, SAMN08666232\n\n  Disease:\n    is_a: NamedEntity\n    description: >-\n      Message to indicate a disease (diagnosis) and its recorded onset.\n    attributes:\n      diseaseStage:\n        description: >-\n          List of disease staging terms. These\n          describe the extent to which a disease has developed.\n        multivalued: true\n        range: string\n        annotations:\n          prompt.examples: >-\n            Stage IA, Stage M2, Stage R, Postoperative Stage\n      onset:\n        description: >-\n          The onset of the disease in terms of the individual''s age.\n        range: string\n\n  DiagnosisDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Diagnosis\n      object:\n        range: Disease\n      predicate:\n        range: DiagnosisDiseasePredicate\n  \n  DiagnosisDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DiagnosisDisease relationships.\n\n  Diagnosis:\n    is_a: NamedEntity\n    description: Diagnosis of clinical findings.\n    attributes:\n      genomicInterpretations:\n        description: >-\n          genomic features containing the status of their contribution towards\n          the diagnosis.\n        multivalued: true\n        range: string\n\n  PhenotypicFeature:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n    annotations:\n      annotators: obo:sqlite:hp\n    attributes:\n      description:\n        description: >-\n          A free-text description of the observed phenotype. \n        range: string\n      modifiers:\n        description: >-\n          Modifiers for the phenotype.\n        multivalued: true\n        range: string\n        annotations:\n          prompt.examples: >-\n            tender, compression fracture, triggered by stress\n      onset:\n        description: >-\n          The onset of the phenotype, or the period of life in which\n          this phenotype was first observed in the individual.\n        range: string\n        annotations:\n          prompt: >-\n            \"Late onset\", \"Congenital onset\", \"Early young adult onset\"\n      resolution:\n        description: Time required to resolve the phenotype in days, if applicable.\n        range: integer\n      severity:\n        description: >-\n          The severity of the phenotype.\n        range: string\n        annotations:\n          prompt.examples: >-\n            borderline, mild, moderate, profound, severe"}');
INSERT INTO embeddings_queue VALUES(474,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','phenotype.txt_50',X'','FLOAT32','{"type": "txt", "source": "phenotype.txt", "content": "id: http://w3id.org/ontogpt/eq\ndefault_range: string\nname: eq-template\ntitle: EQ Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Computational Phenotypes\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  PATO: http://purl.obolibrary.org/obo/PATO_\n  PR: http://purl.obolibrary.org/obo/PR_\n  UBERON: http://purl.obolibrary.org/obo/UBERON_\n  HP: http://purl.obolibrary.org/obo/HP_\n  linkml: https://w3id.org/linkml/\n  phenotype: http://w3id.org/ontogpt/phenotype/\nkeywords:\n  - phenotype\n  - traits\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  TraitQualityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Trait\n      object:\n        range: Quality\n      predicate:\n        range: TraitQualityPredicate\n\n  TraitQualityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TraitQuality relationships.\n\n  TraitAnatomicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Trait\n      object:\n        range: AnatomicalEntity\n      predicate:\n        range: TraitAnatomicalEntityPredicate\n\n  TraitAnatomicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TraitAnatomicalEntity relationships.\n\n  TraitChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Trait\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: TraitChemicalEntityPredicate\n\n  TraitChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TraitChemicalEntity relationships.\n\n  Quality:\n    is_a: NamedEntity\n    description: >-\n      The property being measured, or changes in this property\n    id_prefixes:\n      - PATO\n    annotations:\n      annotators: sqlite:obo:pato\n      prompt.examples: >-\n        amount, level, increased amount, decreased concentration\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    description: >-\n      The chemical entity that is being measured\n    id_prefixes:\n      - CHEBI\n      - PR\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:pr\n      prompt.examples: lysine, metabolite\n\n  AnatomicalEntity:\n    is_a: NamedEntity\n    description: >-\n      The anatomical location that the chemical entity is measured in\n    id_prefixes:\n      - UBERON\n    annotations:\n      annotators: sqlite:obo:uberon\n      prompt.examples: liver, heart, brain, finger\n\n  Trait:\n    is_a: NamedEntity\n    description: >-\n      The observable characteristic or feature of the organism\n    id_prefixes:\n      - HP\n    annotations:\n      annotators: sqlite:obo:hp\n      prompt.examples: arythmia, hypertension, diabetes"}');
INSERT INTO embeddings_queue VALUES(475,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','predator_prey.txt_51',X'','FLOAT32','{"type": "txt", "source": "predator_prey.txt", "content": "id: https://w3id.org/ontogpt/predator_prey\ndefault_range: string\nname: predator-prey-template\ntitle: Predator Prey Relationship Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting information about predator-prey relationships in ecological contexts\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_\n  RO: http://purl.obolibrary.org/obo/RO_\n  linkml: https://w3id.org/linkml/\n  pp: http://w3id.org/ontogpt/predator-prey-template\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  PredatorPreyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Animal\n      object:\n        range: Animal  \n      predicate:\n        range: PredatorPreyPredicate\n      habitat_context:\n        description: >-\n          List the environments or habitats where this predator-prey interaction typically occurs.\n          If there are multiple habitats, provide them as a semicolon-delimited list.\n        range: string\n        multivalued: true\n      seasonal_pattern:\n        description: any seasonal patterns in the predator-prey relationship\n        range: string\n  \n  PredatorPreyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the PredatorPrey relationships.\n\n  AnimalTaxonomicRankRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Animal\n      object:\n        range: TaxonomicRank\n      predicate:\n        range: AnimalTaxonomicRankPredicate\n\n  AnimalTaxonomicRankPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the AnimalTaxonomicRank relationships.\n\n  Animal:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: common name of the animal\n      scientific_name:\n        description: the scientific (Latin) name of the animal\n      diet_type:\n        description: >-\n          The type of diet of the animal.\n        range: DietType\n        multivalued: true\n\n  TaxonomicRank:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n      prompt.examples: species, genus, family\n\nenums:\n  DietType:\n    permissible_values:\n      CARNIVORE:\n        description: An animal that primarily eats meat\n      HERBIVORE:\n        description: An animal that primarily eats plant material\n      OMNIVORE:\n        description: An animal that eats both meat and plant material\n      INSECTIVORE:\n        description: An animal that primarily eats insects\n      PISCIVORE:\n        description: An animal that primarily eats fish\n"}');
INSERT INTO embeddings_queue VALUES(476,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','reaction.txt_52',X'','FLOAT32','{"type": "txt", "source": "reaction.txt", "content": "id: https://w3id.org/ontogpt/reaction\ndefault_range: string\nname: reaction-template\ntitle: reaction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for reactions\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  ECO: http://purl.obolibrary.org/obo/ECO_\n  GO: http://purl.obolibrary.org/obo/GO_\n  MS: http://purl.obolibrary.org/obo/MS_\n  NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_\n  OBI: http://purl.obolibrary.org/obo/OBI_\n  linkml: https://w3id.org/linkml/\n  reaction: http://w3id.org/ontogpt/reaction/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  GeneReactionGroupingRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: ReactionGrouping\n      predicate:\n        range: GeneReactionGroupingPredicate\n      organism:\n        range: Organism\n      has_evidence:\n        range: Evidence\n        description: evidence for the reaction\n        multivalued: true\n  \n  GeneReactionGroupingPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneReactionGrouping relationships.\n\n  GeneReactionRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: Reaction\n      predicate:\n        range: GeneReactionPredicate\n      organism:\n        range: Organism\n      has_evidence:\n        range: Evidence\n        description: evidence for the reaction\n        multivalued: true\n  \n  GeneReactionPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneReaction relationships.\n  \n  Reaction:\n    is_a: ReactionGrouping\n    attributes:\n      label:\n        description: the name of the reaction\n      description:\n        description: a textual description of the reaction\n      synonyms:\n        description: alternative names of the reaction\n        multivalued: true\n\n  ReactionIsOnTheLeftSideOfChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: ReactionIsOnTheLeftSideOfChemicalEntityPredicate\n      organism:\n        range: Organism\n      has_evidence:\n        range: Evidence\n        description: evidence for the reaction\n        multivalued: true\n  \n  ReactionIsOnTheLeftSideOfChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ReactionIsOnTheLeftSideOfChemicalEntity relationships.\n      id:\n        pattern: ''is on the left side of''\n    \n  ReactionIsOnTheRightSideOfChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: ReactionIsOnTheRightSideOfChemicalEntityPredicate\n      organism:\n        range: Organism\n      has_evidence:\n        range: Evidence\n        description: evidence for the reaction\n        multivalued: true\n  \n  ReactionIsOnTheRightSideOfChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ReactionIsOnTheRightSideOfChemicalEntity relationships.\n      id:\n        pattern: ''is on the right side of''\n\n  ReactionGrouping:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi\n\n  Evidence:\n    is_a: NamedEntity\n    id_prefixes:\n      - OBI\n      - ECO\n      - MS\n    annotations:\n      annotators: sqlite:obo:obi, sqlite:obo:eco, sqlite:obo:ms\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - PR\n    annotations:\n      annotators: bioportal:hgnc-nr, sqlite:obo:pr\n\n  Organism:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n"}');
INSERT INTO embeddings_queue VALUES(477,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','recipe.txt_53',X'','FLOAT32','{"type": "txt", "source": "recipe.txt", "content": "id: https://w3id.org/ontogpt/recipe\ndefault_range: string\nname: recipe-template\ntitle: Food Recipe Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for food recipes\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  recipe: http://w3id.org/ontogpt/recipe/\n  FOODON: http://purl.obolibrary.org/obo/FOODON_\n  UO: http://purl.obolibrary.org/obo/UO_\n  dcterms: http://purl.org/dc/terms/\n  HANCESTRO: http://purl.obolibrary.org/obo/HANCESTRO_\n  BFO: http://purl.obolibrary.org/obo/BFO_\n  AUTO: http://example.org/auto/\n  RO: http://purl.obolibrary.org/obo/RO_\n  qudt: http://qudt.org/schema/qudt/\n  dbpediaont: http://dbpedia.org/ontology/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  FoodItemQuantityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: FoodItem\n      object:\n        range: Quantity\n      predicate:\n        range: FoodItemQuantityPredicate\n  \n  FoodItemQuantityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the FoodItemQuantity relationships.\n  \n  UnitQuantityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Unit\n      object:\n        range: Quantity\n      predicate:\n        range: UnitQuantityPredicate\n  \n  UnitQuantityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the UnitQuantity relationships.\n  \n  FoodItemDevelopsIntoFoodItemRelationship:\n    is_a: Triple\n    slot_usage:\n      action:\n        range: Action\n        required: true\n      subject:\n        range: FoodItem\n      object:\n        range: FoodItem\n      predicate:\n        range: FoodItemDevelopsIntoFoodItemPredicate\n      utensils:\n        range: UtensilType\n      recipe:\n        range: Recipe\n\n  FoodItemDevelopsIntoFoodItemPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the FoodItemDevelopsIntoFoodItem relationships.\n      id:\n        pattern: ''develops into''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  RecipeIngredientRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Recipe\n      object:\n        range: Ingredient\n      predicate:\n        range: RecipeIngredientPredicate\n      quantity:\n        range: Quantity\n        required: true\n\n  RecipeIngredientPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the RecipeIngredient relationships.\n\n  Recipe:\n    is_a: NamedEntity\n    attributes:\n      url:\n        identifier: true\n        required: true\n        range: string\n      label:\n        description: the name of the recipe\n      description:\n        description: a brief textual description of the recipe\n      categories:\n        range: RecipeCategory\n        multivalued: true\n\n  FoodItem:\n    is_a: NamedEntity\n    id_prefixes:\n      - FOODON\n      - dbpediaont\n    annotations:\n      annotators: sqlite:obo:foodon, sqlite:obo:dbpediaont\n    attributes:\n      food:\n        description: the food item\n        range: FoodType\n      state:\n        description: the state of the food item\n        annotations:\n          prompt.examples: chopped, diced\n  \n  Quantity:\n    is_a: NamedEntity\n    description: the quantity of the ingredient\n    attributes:\n      value:\n        description: the value of the quantity\n        range: float\n        annotations:\n          prompt.examples: 2 lbs\n  \n  RecipeCategory:\n    is_a: NamedEntity\n    id_prefixes:\n      - dbpediaont\n      - FOODON\n      - HANCESTRO\n    annotations:\n      annotators: sqlite:obo:dbpediaont, sqlite:obo:foodon, sqlite:obo:hancestro\n\n  Action:\n    is_a: NamedEntity\n    id_prefixes:\n      - dbpediaont\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:dbpediaont, sqlite:obo:foodon\n      prompt.examples: mix, add\n\n  UtensilType:\n    is_a: NamedEntity\n    id_prefixes:\n      - dbpediaont\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:dbpediaont, sqlite:obo:foodon\n      prompt.examples: pan, bowl\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n      - NCIT\n      - dbpediaont\n    annotations:\n      annotators: sqlite:obo:uo, sqlite:obo:ncit, sqlite:obo:dbpediaont\n      prompt.examples: grams, cups\n\n  IngredientFoodItemRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ingredient\n      object:\n        range: FoodItem\n      predicate:\n        range: IngredientFoodItemPredicate\n\n  IngredientFoodItemPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the IngredientFoodItem relationships.\n\n  IngredientQuantityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Ingredient\n      object:\n        range: Quantity\n      predicate:\n        range: IngredientQuantityPredicate\n\n  IngredientQuantityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the IngredientQuantity relationships.\n\n  Ingredient:\n    is_a: NamedEntity"}');
INSERT INTO embeddings_queue VALUES(478,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','storms.txt_54',X'','FLOAT32','{"type": "txt", "source": "storms.txt", "content": "id: https://w3id.org/ontogpt/storms\nname: storms-template\ntitle: Storms Evaluation Template\ndescription: >-\n  A template for extracting information using STORMS checklist\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nsee_also:\n  - https://www.nature.com/articles/s41591-021-01552-x\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  storms: http://w3id.org/ontogpt/storms/\n\ndefault_prefix: storms\ndefault_range: string\n\nimports:\n  - linkml:types\n  - core\n\nclasses:\n  STORMSChecklist:\n    is_a: NamedEntity\n    description: A checklist of items that should be reported in a microbiome study. Try and provide a value for ALL items. If an item is not reported, say NOT REPORTED.\n    attributes:\n      abstract_structured_or_unstructured:\n        description: Abstract should include information on background, methods, results, and conclusions in structured or unstructured format.\n        range: string\n      abstract_study_design:\n        description: Study design in abstract.\n        range: string\n      abstract_sequencing_methods:\n        description: Strategy used for metagenomic classification.\n        range: string\n      abstract_specimens:\n        description: Body site(s) studied.\n        range: string\n        multivalued: true\n      introduction_background_and_rationale:\n        description: Underlying background, scientific evidence, or theory driving the current hypothesis as well as the study objectives.\n        range: string\n      introduction_hypotheses:\n        description: Pre-specified hypothesis. If the study is exploratory, state any pre-specified study objectives.\n        range: string\n      methods_study_design:\n        description: Study design.\n        range: string\n      methods_participants:\n        description: Population of interest, and the method by which participants are sampled from that population.\n        range: string\n      methods_geographic_location:\n        description: Geographic region(s) where participants were sampled from.\n        range: string\n        multivalued: true\n      methods_relevant_dates:\n        description: Start and end dates for recruitment, follow-up, and data collection.\n        range: string\n      methods_eligibility_criteria:\n        description: Criteria for inclusion and exclusion of recruited participants.\n        range: string\n        multivalued: true\n      methods_antibiotics_usage:\n        description: What is known about antibiotics usage before or during sample collection.\n        range: string\n        multivalued: true\n      methods_analytic_sample_size:\n        description: How the final analytic sample size was calculated, including the number of cases and controls if relevant, and reasons for dropout at each stage of the study.\n        range: string\n      methods_longitudinal_studies:\n        description: For longitudinal studies, how many follow-ups were conducted, sample size at follow-up by group or condition, and any loss to follow-up.\n        range: string\n        multivalued: true\n      methods_matching:\n        description: For matched studies, matching criteria.\n        range: string\n        multivalued: true\n      methods_ethics:\n        description: Name of the institutional review board that approved the study and protocols, protocol number and date of approval, and procedures for obtaining informed consent from participants.\n        range: string\n        multivalued: true\n      methods_laboratory_methods:\n        description: Laboratory/center where laboratory work was done.\n        range: string\n      methods_specimen_collection:\n        description: Body site(s) sampled from and how specimens were collected.\n        range: string\n        multivalued: true\n      methods_shipping:\n        description: How samples were stored and shipped to the laboratory.\n        range: string\n      methods_storage:\n        description: How the laboratory stored samples, including time between collection and storage and any preservation buffers or refrigeration used.\n        range: string\n      methods_dna_extraction:\n        description: DNA extraction method, including kit and version if relevant.\n        range: string\n      methods_human_dna_sequence_depletion_or_microbial_dna_enrichment:\n        description: Whether human DNA sequence depletion or enrichment of microbial or viral DNA was performed.\n        range: boolean\n      methods_primer_selection:\n        description: Primer selection and DNA amplification methods as well as variable region sequenced (if applicable).\n        range: string\n        multivalued: true\n      methods_positive_controls:\n        description: Any positive controls (mock communities) if used.\n        range: string\n        multivalued: true\n      methods_negative_controls:\n        description: Any negative controls if used.\n        range: string\n        multivalued: true\n      methods_contaminant_mitigation_and_identification:\n        description: Any laboratory or computational methods used to control for or identify microbiome contamination from the environment, reagents, or laboratory.\n        range: string\n        multivalued: true\n      methods_replication:\n        description: Any biological or technical replicates included in the sequencing, including which steps were replicated between them.\n        range: string\n        multivalued: true\n      methods_sequencing_strategy:\n        description: Major divisions of strategy, such as shotgun or amplicon sequencing.\n        range: string\n        multivalued: true\n      methods_sequencing_methods:\n        description: Whether experimental quantification was used (QMP/cell count based, spike-in based) or whether relative abundance methods were applied.\n        range: boolean\n      methods_batch_effects:\n        description: Any blocking or randomization used in study design to avoid confounding of batches with exposures or outcomes. Includes any likely sources of batch effects, if known.\n        range: string\n        multivalued: true\n      methods_metatranscriptomics:\n        description: Whether any mRNA enrichment was performed and whether/how retrotranscription was performed prior to sequencing. Includes size range of isolated transcripts. Also, whether the sequencing library was stranded or not. Includes details on sequencing methods and platforms.\n        range: boolean\n      methods_metaproteomics:\n        description: Which protease was used for digestion. Includes details on proteomic methods and platforms (e.g. LC-MS/MS, instrument type, column type, mass range, resolution, scan speed, maximum injection time, isolation window, normalised collision energy, and resolution).\n        range: string\n      methods_metabolomics:\n        description: The analytic method used (such as nuclear magnetic resonance spectroscopy or mass spectrometry). For mass spectrometry, includes which fractions were obtained (polar and/or non polar) and how these were analyzed. Includes also details on metabolomics methods and platforms (e.g. derivatization, instrument type, injection type, column type and instrument settings).\n        range: string\n      results_descriptive_data:\n        description: Characteristics of study participants (e.g. dietary, demographic, clinical, social) and information on exposures and potential confounders.\n        range: string\n        multivalued: true\n      results_microbiome_data:\n        description: Descriptive findings for microbiome analyses with all applicable outcomes and covariates.\n        range: string\n        multivalued: true\n      results_taxonomy:\n        description: Taxonomy using standardized taxon classifications that are sufficient to uniquely identify taxa.\n        range: string\n      results_differential_abundance:\n        description: Results of differential abundance analysis by the variable of interest and (if applicable) by time, clearly indicating the direction of change and total number of taxa tested.\n        range: string\n        multivalued: true\n      results_other_data_types:\n        description: Other data analyzed--e.g. metabolic function, functional potential, MAG assembly, and RNAseq.\n        range: string\n        multivalued: true\n      results_other_statistical_analysis:\n        description: Any statistical data analysis not covered above.\n        range: string\n      discussion_key_results:\n        description: Key results with reference to study objectives.\n        range: string\n        multivalued: true\n      discussion_interpretation:\n        description: A cautious overall interpretation of results considering objectives, limitations, multiplicity of analyses, results from similar studies, and other relevant evidence.\n        range: string\n      discussion_limitations:\n        description: Limitations of the study, taking into account sources of potential bias or imprecision.\n        range: string\n        multivalued: true\n      discussion_bias:\n        description: Any potential for bias to influence study findings.\n        range: string\n      discussion_generalizability:\n        description: The generalizability (external validity) of the study results.\n        range: string\n      discussion_ongoing_future_work:\n        description: Potential future research or ongoing research based on the study''s findings.\n        range: string\n      other_information_funding:\n        description: The source of funding and the role of the funders for the present study and, if applicable, for the original study on which the present article is based.\n        range: string\n      other_information_acknowledgements:\n        description: Acknowledgements of those who contributed to the research but did not meet criteria for authorship.\n        range: string\n      other_information_conflicts_of_interest:\n        description: A conflicts of interest statement.\n        range: string\n      other_information_supplements:\n        description: Where supplements may be accessed and what materials they contain.\n        range: string\n      other_information_supplementary_data:\n        description: Supplementary data files of results with all taxa and all outcome variables analyzed. Includes the taxonomic level of all taxa.\n        range: string\n\n"}');
INSERT INTO embeddings_queue VALUES(479,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','table_arrays.txt_55',X'','FLOAT32','{"type": "txt", "source": "table_arrays.txt", "content": "id: https://w3id.org/ontogpt/table_arrays\ndefault_range: string\nname: SimpleTableExtraction\ntitle: Simple Table Extraction\ndescription: >-\n  An OntoGPT schema for extracting simple numerical\n  tables with a separate header row, label row, and\n  data arrays\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Table:\n    is_a: NamedEntity\n    description: >-\n      A table extracted from a publication, containing rows and columns in array form.\n    attributes:\n      table_id:\n        description: Identifier for the table\n        identifier: true\n        required: true\n        range: string\n        annotations:\n          prompt.examples: Table 1, Table 2\n      source_document:\n        description: Identifier or reference to the PDF or publication source.\n        range: string\n      caption:\n        description: Text of the table caption or title.\n        range: string\n\n  TableTableHeaderRowRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Table\n      object:\n        range: TableHeaderRow\n      predicate:\n        range: TableTableHeaderRowPredicate\n\n  TableTableHeaderRowPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TableTableHeaderRow relationships.\n\n  TableTableLabelRowRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Table\n      object:\n        range: TableLabelRow\n      predicate:\n        range: TableTableLabelRowPredicate\n\n  TableTableLabelRowPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TableTableLabelRow relationships.\n\n  TableTableDataRowRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Table\n      object:\n        range: TableDataRow\n      predicate:\n        range: TableTableDataRowPredicate\n\n  TableTableDataRowPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TableTableDataRow relationships.\n\n  TableHeaderRow:\n    is_a: NamedEntity\n    description: A single row containing all column headers.\n    attributes:\n      header_values:\n        description: An array of strings corresponding to each column header.\n        range: string\n        multivalued: true\n  \n  TableLabelRow:\n    is_a: NamedEntity\n    description: A single row containing the labels for each of the data rows.\n    attributes:\n      label_values:\n        description: An array of strings corresponding to each row label, aligning with data_rows.\n        range: string\n        multivalued: true\n  \n  TableDataRow:\n    is_a: NamedEntity\n    description: A row of data in the table body, indexed and containing an array of numeric values.\n    attributes:\n      row_index:\n        description: Numeric index of this row (starting from 0 or 1).\n        range: integer\n      values:\n        description: An array of numeric values in this data row.\n        range: float\n        multivalued: true\n      note:\n        description: Optional note or comment about this particular row.\n        range: string\n"}');
INSERT INTO embeddings_queue VALUES(480,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','table_values.txt_56',X'','FLOAT32','{"type": "txt", "source": "table_values.txt", "content": "id: https://w3id.org/ontogpt/table_values\nname: SimpleTableExtraction\ntitle: Simple Table Extraction\ndescription: >-\n  An OntoGPT schema for extracting simple\n  numerical tables with row/column labels\n  from PDF publications\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  STE: https://w3id.org/your-namespace/\n  RO: http://purl.obolibrary.org/obo/RO_\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  Table:\n    is_a: NamedEntity\n    description: >-\n      A table extracted from a publication, containing rows and columns of numerical data.\n    attributes:\n      table_id:\n        description: Identifier for the table\n        range: string\n        identifier: true\n        required: true\n        annotations:\n          prompt.examples: Table 1, Table 2\n      source_document:\n        description: Identifier or reference to the PDF or publication source.\n        range: string\n      caption:\n        description: Text of the table caption or title.\n        range: string\n\n  TableTableRowRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Table\n      object:\n        range: TableRow\n      predicate:\n        range: TableTableRowPredicate\n\n  TableTableRowPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TableTableRow relationships.\n\n  TableTableColumnRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Table\n      object:\n        range: TableColumn\n      predicate:\n        range: TableTableColumnPredicate\n\n  TableTableColumnPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TableTableColumn relationships.\n\n  TableTableCellRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Table\n      object:\n        range: TableCell\n      predicate:\n        range: TableTableCellPredicate\n\n  TableTableCellPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TableTableCell relationships.\n  \n  TableRow:\n    is_a: NamedEntity\n    description: >-\n      A single row in the table, with a label identifying the row.\n    attributes:\n      row_label:\n        description: Label describing the row\n        range: string\n        annotations:\n          prompt.examples: variable, category, subject\n      row_index:\n        description: Numeric index of this row (starting from 0 or 1).\n        range: integer\n  \n  TableColumn:\n    is_a: NamedEntity\n    description: >-\n      A single column in the table, with a label identifying the column.\n    attributes:\n      column_label:\n        description: Label describing the column.\n        range: string\n        annotations:\n          prompt.examples: timepoint, parameter\n      column_index:\n        description: Numeric index of this column (starting from 0 or 1).\n        range: integer\n  \n  TableCell:\n    is_a: NamedEntity\n    description: >-\n      An individual cell in the table, containing a numerical value and optional qualifiers.\n    attributes:\n      row_index:\n        description: Numeric index of this row (starting from 0 or 1).\n        range: integer\n      column_index:\n        description: Numeric index of this column (starting from 0 or 1).\n        range: integer\n      value:\n        description: Numeric value in this cell.\n        range: float\n      unit:\n        description: Optional unit.\n        range: string\n        annotations:\n          prompt.examples: mg, kg, mL\n      note:\n        description: Optional note or comment about this particular cell.\n        range: string\n"}');
INSERT INTO embeddings_queue VALUES(481,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','traits.txt_57',X'','FLOAT32','{"type": "txt", "source": "traits.txt", "content": "id: http://w3id.org/ontogpt/traits\ndefault_range: string\nname: traits\ntitle: Traits Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Traits\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  traits: http://w3id.org/ontogpt/traits/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  TaxonHasPreferredEnvironmentTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasPreferredEnvironmentTraitPredicate\n\n  TaxonHasPreferredEnvironmentTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasPreferredEnvironmentTrait relationships.\n      id:\n        pattern: ''has preferred environment trait''\n\n  TaxonHasPhenotypicPlasticityTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasPhenotypicPlasticityTraitPredicate\n\n  TaxonHasPhenotypicPlasticityTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasPhenotypicPlasticityTrait relationships.\n      id:\n        pattern: ''has phenotypic plasticity trait''\n\n  TaxonHasSurvivalTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasSurvivalTraitPredicate\n\n  TaxonHasSurvivalTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasSurvivalTrait relationships.\n      id:\n        pattern: ''has survival trait''\n\n  TaxonHasReproductiveTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasReproductiveTraitPredicate\n\n  TaxonHasReproductiveTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasReproductiveTrait relationships.\n      id:\n        pattern: ''has reproductive trait''\n\n  TaxonHasEcologicalTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasEcologicalTraitPredicate\n\n  TaxonHasEcologicalTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasEcologicalTrait relationships.\n      id:\n        pattern: ''has ecological trait''\n\n  TaxonHasCellularTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasCellularTraitPredicate\n\n  TaxonHasCellularTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasCellularTrait relationships.\n      id:\n        pattern: ''has cellular trait''\n\n  TaxonHasGeneticTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasGeneticTraitPredicate\n\n  TaxonHasGeneticTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasGeneticTrait relationships.\n      id:\n        pattern: ''has genetic trait''\n\n  TaxonHasMorphologicalTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasMorphologicalTraitPredicate\n\n  TaxonHasMorphologicalTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasMorphologicalTrait relationships.\n      id:\n        pattern: ''has morphological trait''\n\n  TaxonHasMetabolicTraitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Trait\n      predicate:\n        range: TaxonHasMetabolicTraitPredicate\n\n  TaxonHasMetabolicTraitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TaxonHasMetabolicTrait relationships.\n      id:\n        pattern: ''has metabolic trait''\n\n  Taxon:\n    is_a: NamedEntity\n    description: The taxonomic group or species of an organism.\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n      prompt: >-\n        Examples are \"human\", \"mouse\", \"rat\", \"Rhesus macaque\",\n        \"canine\", \"marmoset\", \"fruit fly\", \"C. elegans\", \"S. cerevisiae\".\n\n  Trait:\n    is_a: NamedEntity\n    id_prefixes:\n      - ECOCORE\n      - PATO\n      - GO\n      - OBA\n      - BIODIVTHES\n    annotations:\n      annotators: >-\n        sqlite:obo:ecocore, sqlite:obo:pato, sqlite:obo:go, sqlite:obo:oba, bioportal:biodivthes\n        bioportal:envthes\n"}');
INSERT INTO embeddings_queue VALUES(482,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','treatment.txt_58',X'','FLOAT32','{"type": "txt", "source": "treatment.txt", "content": "id: http://w3id.org/ontogpt/treatment\ndefault_range: string\nname: treatment-template\ntitle: MAXO treatment Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for MAXO treatments\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  HGNC: http://identifiers.org/hgnc/\n  HP: http://purl.obolibrary.org/obo/HP_\n  MAXO: http://purl.obolibrary.org/obo/MAXO_\n  linkml: https://w3id.org/linkml/\n  treatment: http://w3id.org/ontogpt/treatments/\nkeywords:\n  - treatments\n  - drugs\n  - therapies\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  TreatmentMechanismRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: Mechanism\n      predicate:\n        range: TreatmentMechanismPredicate\n  \n  TreatmentMechanismPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TreatmentMechanism relationships.\n\n  TreatmentAdverseEffectRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: AdverseEffect\n        multivalued: true\n      predicate:\n        range: TreatmentAdverseEffectPredicate\n  \n  TreatmentAdverseEffectPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TreatmentAdverseEffect relationships.\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: obo:sql:hgnc, bioportal:hgnc-nr\n\n  Symptom:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n    annotations:\n      annotators: sqlite:obo:hp\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n\n  AdverseEffect:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:ncit\n      prompt.examples: Imatinib*nausea\n\n  Treatment:\n    is_a: NamedEntity\n    attributes:\n      efficacy:\n        range: string\n        annotations:\n          prompt.examples: Imatinib*effective\n      NCITDrugType:\n        range: NCITDrugType\n      NCITTreatmentType:\n        range: NCITTreatmentType\n      NCITActivityType:\n        range: NCITActivityType\n      MAXOTreatmentType:\n        range: MAXOTreatmentType\n      MESHTherapeuticType:\n        range: MESHTherapeuticType\n      CHEBIDrugType:\n        range: CHEBIDrugType\n    id_prefixes:\n      - MAXO\n      - NCIT\n      - MESH\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh, sqlite:obo:chebi\n      prompt.examples: Imatinib, exercise, surgery, Beta-blockers\n\n  Mechanism:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - NCIT\n      - MESH\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:ncit, sqlite:obo:mesh\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:drugbank\n\nenums:\n  NCITDrugType:\n    reachable_from:\n      source_ontology: obo:ncit\n      source_nodes:\n        - NCIT:C1908 ## Drug, Food, Chemical or Biomedical Material\n\n  NCITTreatmentType:\n    reachable_from:\n      source_ontology: obo:ncit\n      source_nodes:\n        - NCIT:C25218 ## Intervention or Procedure\n\n  NCITTActivityType:\n    reachable_from:\n      source_ontology: obo:ncit\n      source_nodes:\n        - NCIT:C43431 ## Activity\n\n  MAXOActionType:\n    reachable_from:\n      source_ontology: obo:maxo\n      source_nodes:\n        - MAXO:0000001 ## Medical Action\n\n  MESHTherapeuticType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D013812 ## Therapeutics\n\n  CHEBIDrugType:\n    reachable_from:\n      source_ontology: obo:chebi\n      source_nodes:\n        - CHEBI:23888 ## drug\n      relationship_types:\n        - rdfs:subClassOf\n        - RO:0000087\n"}');
INSERT INTO embeddings_queue VALUES(483,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','vbo_char.txt_59',X'','FLOAT32','{"type": "txt", "source": "vbo_char.txt", "content": "id: http://w3id.org/ontogpt/vbo_char\ndefault_range: string\nname: vbo_char\ntitle: Extraction Template for Animal Breeds and their Characteristics\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  An extraction template for animal names present in VBO,\n  along with the characteristics of each breed\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  vbo_char: http://w3id.org/ontogpt/vbo_char\n  vbo: http://purl.obolibrary.org/obo/vbo\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  BreedCharacteristicRelationship:\n    is_a: Triple\n    description: >- \n      A triple in which the subject is an animal breed, the object is\n      a characteristic. Each statement should contain just one pair of\n      breed name and characteristic.\n    slot_usage:\n      subject:\n        range: BreedName\n      object:\n        range: Characteristic\n      predicate:\n        range: BreedCharacteristicPredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the breed.\n        range: string\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the characteristic.\n          This is generally a descriptor of the characteristic.\n        range: Descriptor\n    annotations:\n      prompt.examples: >-\n        \"Breed IS Characteristic\", \"Breed HAS Characteristic\",\n        \"Gimbsheimer Enten IS blue\", \"Debao pony IS short\",\n        \"Baixi IS circular\", \"Breed IS tall\", \"Breed is wide\"\n  \n  BreedCharacteristicPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BreedCharacteristic relationships.\n\n  AnimalName:\n    is_a: NamedEntity\n    description: >-\n      The name of a grouping category of vertebrate animal breeds.\n    id_prefixes:\n      - VBO\n    annotations:\n      annotators: sqlite:obo:vbo\n      prompt.examples: >-\n        cat breed, pig breed\n\n  BreedName:\n    is_a: NamedEntity\n    description: >-\n      The name of a vertebrate animal breed.\n    id_prefixes:\n      - VBO\n    annotations:\n      annotators: sqlite:obo:vbo\n      prompt.examples: >-\n        Gimbsheimer Enten, Debao pony, Baixi, blue fin\n\n  Characteristic:\n    is_a: NamedEntity\n    description: >-\n      The characteristic may be color, dimensions, physical properties,\n      abilities, or other features.\n    id_prefixes:\n      - UBERON\n      - PATO\n    annotations:\n      annotators: sqlite:obo:uberon, sqlite:obo:pato\n      prompt.examples: fin\n\n  Descriptor:\n    is_a: NamedEntity\n    description: >-\n      A descriptor for a characteristic.\n    id_prefixes:\n      - PATO\n    annotations:\n      annotators: sqlite:obo:pato\n      prompt.examples: blue\n"}');
INSERT INTO embeddings_queue VALUES(484,'2025-08-30 12:53:19',0,'persistent://default/default/ff00cb32-abe7-433f-910f-01636e615fd5','vbo_names.txt_60',X'','FLOAT32','{"type": "txt", "source": "vbo_names.txt", "content": "id: http://w3id.org/ontogpt/vbo_names\ndefault_range: string\nname: vbo_names\ntitle: Extraction Template for Animal Names\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  An extraction template for animal names present in VBO\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  vbo_names: http://w3id.org/ontogpt/ecosim_simple\n  vbo: http://purl.obolibrary.org/obo/vbo\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  AnimalName:\n    is_a: NamedEntity\n    description: >-\n      The name of a grouping category of vertebrate\n      animal breeds.\n    id_prefixes:\n      - VBO\n    annotations:\n      annotators: sqlite:obo:vbo\n      prompt.examples: >-\n        cat breed, pig breed\n\n  BreedName:\n    is_a: NamedEntity\n    description: >-\n      The name of a vertebrate animal breed.\n    id_prefixes:\n      - VBO\n    annotations:\n      annotators: sqlite:obo:vbo\n      prompt.examples: >-\n        Gimbsheimer Enten, Debao pony, Baixi\n"}');
