INSERT INTO embedding_metadata VALUES(362,'chroma:document','  MedicalActionSymptomRelationship:     is_a: Triple     description: >-       An association representing a relationships between a disease,       the mentioned signs and symptoms associated with that disease,       the medical actions relating to each symptom, and the type of       relationship between each action and symptom (usually TREATS       or PREVENTS).     slot_usage:       subject:         range: MedicalAction       object:         range: Symptom       predicate:         range: MedicalActionSymptomPredicate       qualifier:         description: >-           The primary disease the relationship is about, or specifically           the disease the symptom is related to.         range: Disease       subject_extension:         description: >-           A chemical or drug mentioned in the relationship between the           medical action and the symptom, for example,           "analgesic agent therapy" has the aspect "analgesic"         range: Chemical      MedicalActionSymptomPredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the MedicalActionSymptom relationships.    MedicalAction:     is_a: NamedEntity     description: >-       A clinically prescribed procedure, therapy, intervention, or       recommendation.     id_prefixes:       - MAXO       - OGMS       - NCIT       - OBI     annotations:       annotators: sqlite:obo:maxo, sqlite:obo:ogms, sqlite:obo:ncit, sqlite:obo:obi       prompt.examples: >-         blood transfusion, radiation therapy,         cardiac catheterization, pulse oximetry, otoscopy    Symptom:     is_a: NamedEntity     description: >-       A condition or phenotype resulting from an abnormal health state.     id_prefixes:       - HP       - MONDO       - NCIT     annotations:       annotators: sqlite:obo:hp, sqlite:obo:mondo, sqlite:obo:ncit       prompt.examples: >-         Low serum calcitriol, hypoplasia of the thymus,         chronic cough, aortic stiffness, low pulse pressure    Disease:     is_a: NamedEntity     description: >-       A disposition to undergo pathological processes that exists in an organism       because of one or more disorders in that organism.     id_prefixes:       - MONDO       - HP       - NCIT     annotations:       annotators: sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:ncit       prompt.examples: >-         Beck-Fahrner syndrome, hereditary retinoblastoma, progeria,         diabetes mellitus, infectious otitis media    Chemical:     is_a: NamedEntity     description: >-       A substance that has a defined molecular structure and is produced by or       used in a chemical process. Includes drugs used as part of       medical actions.     id_prefixes:       - CHEBI       - NCIT     annotations:       annotators: sqlite:obo:chebi, sqlite:obo:ncit       prompt.examples: >-         corticosteroid, folic acid, opioid analgesic ',NULL,NULL,NULL);
