INSERT INTO embedding_metadata VALUES(375,'chroma:document','  NeuronProjectsToOrFromBrainRegionRelationship:     is_a: Triple     description: Brain structures from which this neuron projects into or receives projections from     slot_usage:       subject:         range: Neuron       object:         range: BrainRegion       predicate:         range: NeuronProjectsToOrFromBrainRegionPredicate    NeuronProjectsToOrFromBrainRegionPredicate:     is_a: RelationshipType     id_prefixes:       - RO     attributes:       label:         description: The predicate for the NeuronProjectsToOrFromBrainRegion relationships.       id:         pattern: ''projects to or from''     annotations:       annotators: sqlite:obo:ro    CellType:     is_a: NamedEntity     description: Represents a cell type     attributes:       id:         identifier: true         required: true       label:         range: string         description: the concise name of the cell type       definition:         description: A concise textual definition in genus-differentia form, i.e ''A <genus> that <differentiating characteristics>''    Neuron:     is_a: CellType    AnatomicalStructure:     is_a: NamedEntity     id_prefixes:       - UBERON       - FBbt       - WBbt     annotations:       annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt    BrainRegion:     is_a: AnatomicalStructure     attributes:       brain_region_identifier:         required: true         identifier: true     id_prefixes:       - UBERON       - FBbt       - WBbt     annotations:       annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt',NULL,NULL,NULL);
