INSERT INTO embedding_metadata VALUES(421,'chroma:document','  TaxonHasSurvivalTraitRelationship:     is_a: Triple     slot_usage:       subject:         range: Taxon       object:         range: Trait       predicate:         range: TaxonHasSurvivalTraitPredicate    TaxonHasSurvivalTraitPredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the TaxonHasSurvivalTrait relationships.       id:         pattern: ''has survival trait''    Taxon:     is_a: NamedEntity     description: The taxonomic group or species of an organism.     id_prefixes:       - NCBITaxon     annotations:       annotators: sqlite:obo:ncbitaxon       prompt: >-         Examples are "human", "mouse", "rat", "Rhesus macaque",         "canine", "marmoset", "fruit fly", "C. elegans", "S. cerevisiae".    Trait:     is_a: NamedEntity     id_prefixes:       - ECOCORE       - PATO       - GO       - OBA       - BIODIVTHES     annotations:       annotators: >-         sqlite:obo:ecocore, sqlite:obo:pato, sqlite:obo:go, sqlite:obo:oba, bioportal:biodivthes         bioportal:envthes ',NULL,NULL,NULL);
