INSERT INTO embedding_metadata VALUES(426,'chroma:document','  TreatmentAdverseEffectRelationship:     is_a: Triple     slot_usage:       subject:         range: Treatment       object:         range: AdverseEffect         multivalued: true       predicate:         range: TreatmentAdverseEffectPredicate      TreatmentAdverseEffectPredicate:     is_a: RelationshipType     attributes:       label:         description: The predicate for the TreatmentAdverseEffect relationships.    Treatment:     is_a: NamedEntity     attributes:       efficacy:         range: string         annotations:           prompt.examples: Imatinib*effective       NCITDrugType:         range: NCITDrugType       NCITTreatmentType:         range: NCITTreatmentType       NCITActivityType:         range: NCITActivityType       MAXOTreatmentType:         range: MAXOTreatmentType       MESHTherapeuticType:         range: MESHTherapeuticType       CHEBIDrugType:         range: CHEBIDrugType     id_prefixes:       - MAXO       - NCIT       - MESH       - CHEBI     annotations:       annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh, sqlite:obo:chebi       prompt.examples: Imatinib, exercise, surgery, Beta-blockers    AdverseEffect:     is_a: NamedEntity     id_prefixes:       - HP       - NCIT     annotations:       annotators: sqlite:obo:hp, sqlite:obo:ncit       prompt.examples: Imatinib*nausea  enums:   NCITDrugType:     reachable_from:       source_ontology: obo:ncit       source_nodes:         - NCIT:C1908 ## Drug, Food, Chemical or Biomedical Material    NCITTreatmentType:     reachable_from:       source_ontology: obo:ncit       source_nodes:         - NCIT:C25218 ## Intervention or Procedure    NCITTActivityType:     reachable_from:       source_ontology: obo:ncit       source_nodes:         - NCIT:C43431 ## Activity    MAXOActionType:     reachable_from:       source_ontology: obo:maxo       source_nodes:         - MAXO:0000001 ## Medical Action    MESHTherapeuticType:     reachable_from:       source_ontology: obo:mesh       source_nodes:         - MESH:D013812 ## Therapeutics    CHEBIDrugType:     reachable_from:       source_ontology: obo:chebi       source_nodes:         - CHEBI:23888 ## drug       relationship_types:         - rdfs:subClassOf         - RO:0000087 ',NULL,NULL,NULL);
