INSERT INTO embedding_metadata VALUES(433,'chroma:document','id: http://w3id.org/ontogpt/all_disease_grounding default_range: string name: all_disease_grounding title: Template for grounding disease names description: Template for grounding disease names prefixes:   rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#   linkml: https://w3id.org/linkml/   ontogpt: http://w3id.org/ontogpt/   MONDO: http://purl.obolibrary.org/obo/mondo.owl   OMIM: http://purl.bioontology.org/ontology/OMIM/ imports:   - ontogpt:core   - linkml:types classes:   Disease:     is_a: NamedEntity     description: The name of a disease, with specific subtype if provided.     id_prefixes:       - MONDO     annotations:       annotators: sqlite:obo:mondo, bioportal:OMIM       prompt.examples: neurothekoma, retinal vasculitis,         chicken monocytic leukemia, neoplasm of spinal cord,         moyamoya disease 3, noninsulin-dependent diabetes mellitus         with deafness, Teebi hypertelorism syndrome 1,         multiple pterygium syndrome escobar variant,         Otopalatodigital syndrome type II,         Alzheimer disease type 3 ',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(434,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(434,'source','all_disease_grounding.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(434,'content',replace('id: http://w3id.org/ontogpt/all_disease_grounding\ndefault_range: string\nname: all_disease_grounding\ntitle: Template for grounding disease names\ndescription: Template for grounding disease names\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ontogpt: http://w3id.org/ontogpt/\n  MONDO: http://purl.obolibrary.org/obo/mondo.owl\n  OMIM: http://purl.bioontology.org/ontology/OMIM/\nimports:\n  - ontogpt:core\n  - linkml:types\nclasses:\n  Disease:\n    is_a: NamedEntity\n    description: The name of a disease, with specific subtype if provided.\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo, bioportal:OMIM\n      prompt.examples: neurothekoma, retinal vasculitis,\n        chicken monocytic leukemia, neoplasm of spinal cord,\n        moyamoya disease 3, noninsulin-dependent diabetes mellitus\n        with deafness, Teebi hypertelorism syndrome 1,\n        multiple pterygium syndrome escobar variant,\n        Otopalatodigital syndrome type II,\n        Alzheimer disease type 3\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(435,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(435,'source','alzrd.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(435,'content',replace('id: http://w3id.org/ontogpt/alzrd\ndefault_range: string\nname: alzrd\ntitle: Template for extracting Alzheimer''s Disease Phenotypes\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  Template for extracting phenotypes of Alzheimer''s disease and related\n  dementias along with experimental metrics and model organisms.\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ontogpt: http://w3id.org/ontogpt/\n  MONDO: http://purl.obolibrary.org/obo/mondo.owl\n  MAXO: http://purl.obolibrary.org/obo/maxo.owl\n  MP: http://purl.obolibrary.org/obo/mp/mp-international.owl\n  NBO: http://purl.obolibrary.org/obo/nbo.owl\n  NCIT: http://purl.obolibrary.org/obo/ncit.owl\n  HP: http://purl.obolibrary.org/obo/hp/hp-international.owl\n  NCBITAXON: http://purl.obolibrary.org/obo/ncbitaxon.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n  ENVO: http://purl.obolibrary.org/obo/envo.owl\n  MESH: http://identifiers.org/mesh/\nimports:\n  - ontogpt:core\n  - linkml:types\nclasses:\n  MetricOrIndicatorToTaxonRelationship:\n    is_a: Triple\n    description: >-\n      A triple where the subject is a MetricOrIndicator and where the object is\n      a Taxon. A triple where the subject is an experimental metric, the object\n      is an taxon, metric, and the predicate describes the relationship between\n      the metric and the taxon, usually MEASURED_IN.\n    slot_usage:\n      subject:\n        range: MetricOrIndicator\n      object:\n        range: Taxon\n      predicate:\n        range: MetricOrIndicatorToTaxonPredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the experimental metric.\n          This may include the method of measurement or the specific assay used.\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the taxon.\n          This may include a strain or genetic background of the model organism.\n      direct_or_indirect:\n        description: >-\n          Whether the relationship between the metric and the taxon is direct\n          or indirect. UNKNOWN if this is not specified in the text\n          or is unclear.\n        range: string\n  MetricOrIndicatorToTaxonPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetricOrIndicatorToTaxon relationships.\n  MetricOrIndicatorToDiseaseRelationship:\n    is_a: Triple\n    description: >-\n      A triple where the subject is a MetricOrIndicator and where the object is\n      a Disease. A triple where the subject is an experimental metric, the\n      object is a disease or condition, and the predicate describes the\n      relationship between the metric and the disease, usually USED_TO_MODEL.\n    slot_usage:\n      subject:\n        range: MetricOrIndicator\n      object:\n        range: Disease\n      predicate:\n        range: MetricOrIndicatorToDiseasePredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the experimental metric.\n          This may include the method of measurement or the specific assay used.\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the disease or condition.\n          This may include the stage or subtype of the disease.\n      direct_or_indirect:\n        description: >-\n          Whether the relationship between the metric and the disease is direct\n          or indirect. UNKNOWN if this is not specified in the text\n          or is unclear.\n        range: string\n      association:\n        description: >-\n          The type of any observed association between the value of the metric\n          and the disease. May be "positive", "negative", "inconclusive", or\n          UNKNOWN if this is not specified in the text or is unclear.\n        range: string\n  MetricOrIndicatorToDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MetricOrIndicatorToDisease relationships.\n  Disease:\n    is_a: NamedEntity\n    description: >-\n      The name of a disease or condition.\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n      prompt.examples: Alzheimer''s disease, Parkinson''s disease, Huntington''s disease\n  MetricOrIndicator:\n    is_a: NamedEntity\n    description: >-\n      The name of an experimental metric, sign, symptom, or outcome used to\n      measure the effects of treatments on symptoms or diagnostics, or of the\n      progression of Alzheimer''s disease and related dementias. In experimental\n      animal models these are analogues of cognitive impairment or indicators of\n      disease progression modeling those observed in humans.\n    id_prefixes:\n      - MAXO\n      - MONDO\n      - MP\n      - NBO\n      - NCIT\n      - MESH\n      - HP\n    annotations:\n      annotators: >-\n        sqlite:obo:maxo, sqlite:obo:mondo, sqlite:obo:mp, sqlite:obo:nbo,\n        sqlite:obo:ncit, sqlite:obo:hp, sqlite:obo:mesh, bioportal:SNOMEDCT\n      prompt.examples: Amyloid beta (Aβ) levels, Morris water maze test, tau phosphorylation, neurofibrillary tangles, and cognitive decline.\n  Diagnostic:\n    is_a: NamedEntity\n    description: >-\n      The name of a diagnostic procedure or test.\n    id_prefixes:\n      - MAXO\n      - NCIT\n      - MESH\n    annotations:\n      annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh\n      prompt.examples: MRI, PET scan, lumbar puncture, blood test, biopsy.\n  Taxon:\n    is_a: NamedEntity\n    description: >-\n      The taxonomic group or species of a model organism.\n    id_prefixes:\n      - NCBITAXON\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n      prompt.examples:  human, mouse, rat, Rhesus macaque, canine, marmoset, fruit fly, C. elegans, S. cerevisiae\n  Chemical:\n    is_a: NamedEntity\n    description: >-\n      The name of a chemical, drug, or other substance.\n    id_prefixes:\n      - CHEBI\n      - MESH\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:mesh\n      prompt.examples: donepezil, Aβ42, Aβ40, tau, insulin, caffeine, nicotine, alcohol\n  EnvironmentalExposure:\n    is_a: NamedEntity\n    description: >-\n      The name of an environmental exposure or condition.\n    id_prefixes:\n      - ENVO\n    annotations:\n      annotators: sqlite:obo:envo\n      prompt.examples: pesticides, chronic stress, air pollution, heavy metals, radiation, heat stress','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(436,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(436,'source','biological_process.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(436,'content',replace('id: https://w3id.org/ontogpt/biological_process\ndefault_range: string\nname: biological-process-template\ntitle: Biological Process Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for GO-CAMs\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  CL: http://purl.obolibrary.org/obo/CL_\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  bp: http://w3id.org/ontogpt/biological-process-template\n  linkml: https://w3id.org/linkml/\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  GeneMolecularActivityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Gene\n      object:\n        range: MolecularActivity\n      predicate:\n        range: GeneMolecularActivityPredicate\n      biological_process:\n        range: BiologicalProcess\n\n  GeneMolecularActivityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the GeneMolecularActivity relationships.\n  \n  BiologicalProcessSubclassOfBiologicalProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: BiologicalProcessSubclassOfBiologicalProcessPredicate\n\n  BiologicalProcessSubclassOfBiologicalProcessPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessSubclassOfBiologicalProcess relationships.\n      id:\n        pattern: ''subclass of''\n\n  BiologicalProcessInputsChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: BiologicalProcessInputsChemicalEntityPredicate\n\n  BiologicalProcessInputsChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessInputsChemicalEntity relationships.\n      id:\n        pattern: ''inputs''\n\n  BiologicalProcessOutputsChemicalEntityRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: ChemicalEntity\n      predicate:\n        range: BiologicalProcessOutputsChemicalEntityPredicate\n\n  BiologicalProcessOutputsChemicalEntityPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessOutputsChemicalEntity relationships.\n      id:\n        pattern: ''outputs''\n\n  BiologicalProcessGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: BiologicalProcess\n      object:\n        range: Gene\n      predicate:\n        range: BiologicalProcessGenePredicate\n\n  BiologicalProcessGenePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the BiologicalProcessGene relationships.\n\n  MolecularActivityInvolvedInBiologicalProcessRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MolecularActivity\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: MolecularActivityInvolvedInBiologicalProcessPredicate\n\n  MolecularActivityInvolvedInBiologicalProcessPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the MolecularActivityInvolvedInBiologicalProcess relationships.\n      id:\n        pattern: ''involved in''\n\n  BiologicalProcess:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: the name of the biological process\n      description:\n        description: a textual description of the biological process\n      synonyms:\n        description: alternative names of the biological process\n        multivalued: true\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: sqlite:obo:hgnc\n\n  CellType:\n    is_a: NamedEntity\n    id_prefixes:\n      - CL\n    annotations:\n      annotators: sqlite:obo:cl\n\n  MolecularActivity:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(437,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(437,'source','biotic_interaction.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(437,'content',replace('id: https://w3id.org/ontogpt/biotic_interaction\ndefault_range: string\nname: biotic-interaction-template\ntitle: Biotic Interaction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for biotic interactions\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MESH: http://identifiers.org/mesh/\n  NCBITaxon: http://purl.obolibrary.org/obo/NCBITAXON_\n  RO: http://purl.obolibrary.org/obo/RO_\n  bp: http://w3id.org/ontogpt/biotic-interaction-template\n  col: https://www.catalogueoflife.org/data/taxon/\n  gbif: https://www.gbif.org/species/\n  itis: https://www.itis.gov/servlet/SingleRpt/SingleRpt?search_topic=TSN&search_value=\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  TaxonTaxonRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Taxon\n      object:\n        range: Taxon\n      predicate:\n        range: TaxonTaxonPredicate\n      environment:\n        description: >-\n          The environment in which the interaction occurs.\n          This should be a short description of the environment, e.g., "forest",\n          "desert", "ocean", etc. If the environment is not specified, leave\n          this field blank. The value here should be no more than a few words.\n        range: string\n    annotations:\n      prompt.examples: Carcharodon carcharias eats elephant seal; Pandarus sinuatus parasitizes Carcharodon carcharias; orca eats Carcharodon carcharias\n\n  TaxonTaxonPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n      - MESH\n      - ECOCORE\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:ro, sqlite:obo:bero\n      #prompt.example: eat, competes with, parasitizes, subsist on a diet, kill, compete, prey consists, hunting, killed by, compete for, dominate, competitors\n    attributes:\n      label:\n        description: The predicate for the TaxonTaxon relationships.\n\n  Taxon:\n    is_a: NamedEntity\n    description: A name of a single plant or animal taxon.\n    annotations:\n      prompt.examples: bear, grass, Ursoidea, Halichoerus grypus, Panicum virgatum, Odocoileus virginianus sleeps on Panicum virgatum\n    # id_prefixes:\n    #   - NCBITaxon\n    #   - SNOMEDCT\n    # annotations:\n    #   annotators: bioportal:SNOMEDCT','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(438,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(438,'source','cell_type.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(438,'content',replace('id: http://w3id.org/ontogpt/cell_type\ndefault_range: string\nname: cell_type\ntitle: Composite Disease\ndescription: >-\n  A template for representing cell types\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  AUTO: http://w3id.org/ontogpt/auto/\n  BFO: http://purl.obolibrary.org/obo/BFO_\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  CL: http://purl.obolibrary.org/obo/CL_\n  FBbt: http://purl.obolibrary.org/obo/FBbt_\n  WBbt: http://purl.obolibrary.org/obo/WBbt_\n  GO: http://purl.obolibrary.org/obo/GO_\n  HGNC: http://identifiers.org/hgnc/\n  HP: http://purl.obolibrary.org/obo/HP_\n  IAO: http://purl.obolibrary.org/obo/IAO_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  NCIT: http://purl.obolibrary.org/obo/NCIT_\n  PW: http://purl.obolibrary.org/obo/PW_\n  RO: http://purl.obolibrary.org/obo/RO_\n  UBERON: http://purl.obolibrary.org/obo/UBERON_\n  DRUGBANK: http://purl.obolibrary.org/obo/DRUGBANK_\n  cell_type: http://w3id.org/ontogpt/cell_type/\n  linkml: https://w3id.org/linkml/\n  skos: http://www.w3.org/2004/02/skos/core#\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  CellTypeEquivalentToCellOntologyTermRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: CellOntologyTerm\n      predicate:\n        range: CellTypeEquivalentToCellOntologyTermPredicate\n\n  CellTypeEquivalentToCellOntologyTermPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeEquivalentToCellOntologyTerm relationships.\n      id:\n        pattern: ''equivalent to''\n\n  CellTypeSubclassOfCellTypeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: CellType\n      predicate:\n        range: CellTypeSubclassOfCellTypePredicate\n\n  CellTypeSubclassOfCellTypePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeSubclassOfCellType relationships.\n      id:\n        pattern: ''subclass of''\n\n  CellTypeSubclassOfCellOntologyTermRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: CellOntologyTerm\n      predicate:\n        range: CellTypeSubclassOfCellOntologyTermPredicate\n\n  CellTypeSubclassOfCellOntologyTermPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeSubclassOfCellOntologyTerm relationships.\n      id:\n        pattern: ''subclass of''\n\n  CellTypeExpressesGeneRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: Gene\n      predicate:\n        range: CellTypeExpressesGenePredicate\n\n  CellTypeExpressesGenePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the CellTypeExpressesGene relationships.\n      id:\n        pattern: ''expresses''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  CellTypeDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: Disease\n      predicate:\n        range: CellTypeDiseasePredicate\n\n  CellTypeDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the CellTypeDisease relationships.\n\n  CellTypeCapableOfBiologicalProcessRelationship:\n    is_a: Triple\n    description: >-\n      Roles (e.g. biological processes) that this cell type plays.\n      These should be short descriptive terms corresponding to ontology\n      terms in the GO biological process hierarchy.\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: BiologicalProcess\n      predicate:\n        range: CellTypeCapableOfBiologicalProcessPredicate\n\n  CellTypeCapableOfBiologicalProcessPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the CellTypeCapableOfBiologicalProcess relationships.\n    annotations:\n      annotators: sqlite:obo:ro\n      \n  CellTypePartOfAnatomicalStructureRelationship:\n    is_a: Triple\n    description: Anatomical structures in which this cell type is localized\n    slot_usage:\n      subject:\n        range: CellType\n      object:\n        range: AnatomicalStructure\n      predicate:\n        range: CellTypePartOfAnatomicalStructurePredicate\n\n  CellTypePartOfAnatomicalStructurePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - BFO\n    attributes:\n      label:\n        description: The predicate for the CellTypePartOfAnatomicalStructure relationships.\n    annotations:\n      annotators: sqlite:obo:bfo\n\n  ImmuneCellHasSurfaceMarkersProteinOrComplexRelationship:\n    is_a: Triple\n    description: Proteins or complexes expressed on the surface of the cell\n    slot_usage:\n      subject:\n        range: ImmuneCell\n      object:\n        range: ProteinOrComplex\n      predicate:\n        range: ImmuneCellHasSurfaceMarkersProteinOrComplexPredicate\n\n  ImmuneCellHasSurfaceMarkersProteinOrComplexPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ImmuneCellHasSurfaceMarkersProteinOrComplex relationships.\n      id:\n        pattern: ''has surface markers''\n\n  NeuronReleasesNeurotransmitterNeurotransmitterRelationship:\n    is_a: Triple\n    description: Chemical entity that this neuron releases\n    slot_usage:\n      subject:\n        range: Neuron\n      object:\n        range: Neurotransmitter\n      predicate:\n        range: NeuronReleasesNeurotransmitterNeurotransmitterPredicate\n\n  NeuronReleasesNeurotransmitterNeurotransmitterPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the NeuronReleasesNeurotransmitterNeurotransmitter relationships.\n      id:\n        pattern: ''releases neurotransmitter''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  NeuronProjectsToOrFromBrainRegionRelationship:\n    is_a: Triple\n    description: Brain structures from which this neuron projects into or receives projections from\n    slot_usage:\n      subject:\n        range: Neuron\n      object:\n        range: BrainRegion\n      predicate:\n        range: NeuronProjectsToOrFromBrainRegionPredicate\n\n  NeuronProjectsToOrFromBrainRegionPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the NeuronProjectsToOrFromBrainRegion relationships.\n      id:\n        pattern: ''projects to or from''\n    annotations:\n      annotators: sqlite:obo:ro\n  \n  CellType:\n    is_a: NamedEntity\n    description: Represents a cell type\n    attributes:\n      id:\n        identifier: true\n        required: true\n      label:\n        range: string\n        description: the concise name of the cell type\n      definition:\n        description: A concise textual definition in genus-differentia form, i.e ''A <genus> that <differentiating characteristics>''\n  \n  ImmuneCell:\n    is_a: CellType\n  \n  Neuron:\n    is_a: CellType\n  \n  Interneuron:\n    is_a: Neuron\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: sqlite:obo:hgnc, bioportal:hgnc-nr\n\n  ProteinOrComplex:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n      - PR\n      - GO\n    annotations:\n      annotators: sqlite:obo:hgnc, bioportal:hgnc-nr, sqlite:obo:go, sqlite:obo:pr\n\n  BiologicalProcess:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n    annotations:\n      annotators: sqlite:obo:go\n\n  Pathway:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - PW\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:pw\n\n  AnatomicalStructure:\n    is_a: NamedEntity\n    id_prefixes:\n      - UBERON\n      - FBbt\n      - WBbt\n    annotations:\n      annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt\n\n  ChemicalEntity:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi\n\n  Neurotransmitter:\n    is_a: ChemicalEntity\n    attributes:\n      neuro_transmitter_identifier:\n        required: true\n        identifier: true\n    id_prefixes:\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:chebi\n\n  BrainRegion:\n    is_a: AnatomicalStructure\n    attributes:\n      brain_region_identifier:\n        required: true\n        identifier: true\n    id_prefixes:\n      - UBERON\n      - FBbt\n      - WBbt\n    annotations:\n      annotators: sqlite:obo:uberon, sqlite:obo:fbbt, sqlite:obo:wbbt\n\n  CellOntologyTerm:\n    is_a: NamedEntity\n    id_prefixes:\n      - CL\n      - FBbt\n      - WBbt\n    annotations:\n      annotators: sqlite:obo:cl, sqlite:obo:fbbt, sqlite:obo:wbbt\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n      - HP\n    annotations:\n      annotators: sqlite:obo:mondo, sqlite:obo:hp\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:drugbank\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(439,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(439,'source','class_enrichment.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(439,'content',replace('id: https://w3id.org/oak/class-enrichment\ndefault_range: string\ntitle: Class Enrichment Datamodel\nname: class-enrichment\ndescription: >-\n  A datamodel for representing the results of class enrichment on gene sets\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  OBI: http://purl.obolibrary.org/obo/OBI_\n  STATO: http://purl.obolibrary.org/obo/STATO_\n  bpa: https://bioportal.bioontology.org/annotator/\n  linkml: https://w3id.org/linkml/\n  oa: http://www.w3.org/ns/oa#\n  ontoenrich: https://w3id.org/oak/class-enrichment/\n  pav: http://purl.org/pav/\n  prov: http://www.w3.org/ns/prov#\n  schema: http://schema.org/\n  sh: https://w3id.org/shacl/\n  skos: http://www.w3.org/2004/02/skos/core#\n  sssom: http://w3id.org/sssom/\n\nimports:\n  - linkml:types\n\nclasses:\n  ClassEnrichmentConfiguration:\n    is_a: NamedEntity\n    description: configuration for search\n    attributes:\n      p_value_cutoff:\n        description: p-value cutoff for enrichment\n        range: float\n        required: true\n\n  ClassEnrichmentResultSet:\n    is_a: NamedEntity\n    description: A collection of enrichment results\n    attributes:\n      results:\n        description: The enrichment results\n        range: ClassEnrichmentResult\n        multivalued: true\n\n  ClassEnrichmentResult:\n    is_a: NamedEntity\n    description: A single enrichment result\n    attributes:\n      class_id:\n        description: The class id\n        range: integer\n        required: true\n        identifier: true\n      class_label:\n        description: The class label\n        range: string\n      rank:\n        description: The rank of this result\n        range: integer\n      p_value:\n        description: The p-value\n        range: float\n        required: true\n      p_value_adjusted:\n        description: The adjusted p-value\n        range: float\n      false_discovery_rate:\n        description: The false discovery rate\n        range: float\n      fold_enrichment:\n        description: The fold enrichment\n        range: float\n      probability:\n        description: The probability, as estimated by model-based approaches (its value is between 0 and 1).\n        range: float\n        minimum_value: 0\n        maximum_value: 1\n      sample_count:\n        description: The number of entities in the sample with this class\n        range: integer\n      sample_total:\n        description: The total number of entities in the sample\n        range: integer\n      background_count:\n        description: The background count\n        range: integer\n      background_total:\n        description: The background total\n        range: integer\n      ancestor_of_more_informative_result:\n        description: This term is more general than a previously reported result\n        range: boolean\n      descendant_of_more_informative_result:\n        description: This term is more specific than a previously reported result\n        range: boolean','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(440,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(440,'source','composite_disease.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(440,'content',replace('id: http://w3id.org/ontogpt/composite_disease\n\ndefault_range: string\n\nname: composite_disease\n\ntitle: Composite Disease\n\ndescription: >-\n  A template for representing composite disease concepts\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\nprefixes:\n  linkml: https://w3id.org/linkml/\n  ontogpt: http://w3id.org/ontogpt/\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  CHEBI: http://purl.obolibrary.org/obo/CHEBI_\n  HGNC: http://identifiers.org/hgnc/\n  HP: http://purl.obolibrary.org/obo/HP_\n  MAXO: http://purl.obolibrary.org/obo/MAXO_\n  NCIT: http://purl.obolibrary.org/obo/ncit.owl\n  MESH: http://identifiers.org/mesh/\n  GO: http://purl.obolibrary.org/obo/GO_\n  DRUGBANK: http://purl.obolibrary.org/obo/DRUGBANK_\n  composite_disease: http://w3id.org/ontogpt/composite_disease/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  TreatmentMechanismRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: Mechanism\n      predicate:\n        range: TreatmentMechanismPredicate\n  \n  TreatmentMechanismPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TreatmentMechanism relationships.\n\n  TreatmentAdverseEffectRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: AdverseEffect\n      predicate:\n        range: AdverseEffectPredicate\n    annotations:\n      prompt.examples: Imatinib*nausea\n  \n  TreatmentAdverseEffectPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the TreatmentAdverseEffect relationships.\n  \n  DrugIsSubstanceThatTreatsDiseaseRelationship:\n    is_a: Triple\n    description: Therapies and treatments are indicated for treating the disease.\n    slot_usage:\n      subject:\n        range: Treatment\n      object:\n        range: Drug\n      predicate:\n        range: DrugIsSubstanceThatTreatsDiseasePredicate\n      treatment:\n        range: Treatment\n  \n  DrugIsSubstanceThatTreatsDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DrugIsSubstanceThatTreatsDisease relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  Gene:\n    is_a: NamedEntity\n    id_prefixes:\n      - HGNC\n    annotations:\n      annotators: obo:sql:hgnc, bioportal:hgnc-nr\n\n  Symptom:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n    annotations:\n      annotators: sqlite:obo:hp\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n\n  AdverseEffect:\n    is_a: NamedEntity\n    id_prefixes:\n      - HP\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:hp, sqlite:obo:ncit\n\n  Treatment:\n    is_a: NamedEntity\n    attributes:\n      treatment_efficacy:\n        range: string\n        annotations:\n          prompt.examples: effective+\n      adverse_effect:\n        range: string\n        annotations:\n          prompt.examples: effective+\n      contraindications:\n        range: string\n    id_prefixes:\n      - MAXO\n      - NCIT\n      - MESH\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:maxo, sqlite:obo:ncit, sqlite:obo:mesh, sqlite:obo:chebi\n      prompt.examples: Imatinib, exercise, surgery\n\n  Mechanism:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - NCIT\n      - MESH\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:ncit, sqlite:obo:mesh\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - CHEBI\n      - DRUGBANK\n    attributes:\n      contraindications:\n        range: string\n    annotations:\n      annotators: sqlite:obo:chebi, sqlite:obo:drugbank\n\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(441,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(441,'source','condition.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(441,'content',replace('id: http://w3id.org/ontogpt/condition\n\nname: condition\n\ntitle: condition FHIR Template\n\ndescription: >-\n  A FHIR-compliant template for conditions mentioned in a clinical note\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\nprefixes:\n  linkml: https://w3id.org/linkml/\n  condition: http://w3id.org/ontogpt/condition/\n  SNOMEDCT: https://purl.bioontology.org/ontology/SNOMEDCT\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  ConditionConditionProblemDiagnosisRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Condition\n      object:\n        range: ConditionProblemDiagnosis\n      predicate:\n        range: ConditionConditionProblemDiagnosisPredicate\n\n  ConditionConditionProblemDiagnosisPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ConditionConditionProblemDiagnosis relationships.\n\n  Condition:\n    is_a: NamedEntity\n    attributes:\n      label:\n        description: The concise name of the condition, problem, or diagnosis.\n      status:\n        description: The clinical status of the condition.\n        range: ConditionClinicalStatusType\n        required: true\n      severity:\n        description: Subjective severity of condition.\n        range: ConditionDiagnosisSeverityType\n\n  ConditionProblemDiagnosis:\n    is_a: NamedEntity\n    attributes:\n      status:\n        range: ConditionClinicalStatusType\n    id_prefixes: \n      - SNOMEDCT\n    annotations:\n      annotators: bioportal:SNOMEDCT\n\nenums:\n  ConditionClinicalStatusType:\n    permissible_values:\n      active:\n        description: The subject is currently experiencing the condition or situation, there is evidence of the condition or situation, or considered to be a significant risk.\n      recurrence:\n        description: The subject is experiencing a reoccurence or repeating of a previously resolved condition or situation, e.g. urinary tract infection, food insecurity.\n      relapse:\n        description: The subject is experiencing a return of a condition or situation after a period of improvement or remission, e.g. relapse of cancer, alcoholism.\n      inactive:\n        description: The subject is no longer experiencing the condition or situation and there is no longer evidence or appreciable risk of the condition or situation.\n      remission:\n        description: The subject is not presently experiencing the condition or situation, but there is a risk of the condition or situation returning.\n      resolved:\n        description: The subject is not presently experiencing the condition or situation and there is a negligible perceived risk of the condition or situation returning.\n      unknown:\n        description: The authoring/source system does not know which of the status values currently applies for this condition.\n  \n  ConditionDiagnosisSeverityType:\n    permissible_values:\n      severe:\n        meaning: SNOMEDCT:24484000\n      moderate:\n        meaning: SNOMEDCT:6736007\n      mild:\n        meaning: SNOMEDCT:255604002','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(442,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(442,'source','ctd.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(442,'content',replace('id: http://w3id.org/ontogpt/ctd\n\ndefault_range: string\n\nname: ctd\n\ntitle: Chemical to Disease Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for Chemical to Disease associations.\n\n  This template is intended to represent associations between chemicals and diseases,\n  and for evaluating Semantic Llama against BioCreative V Chemical Disease\n  Relation (CDR) Task (BC5CDR).\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MESH: http://identifiers.org/mesh/\n  MONDO: http://purl.obolibrary.org/obo/mondo.owl\n  HP: http://purl.obolibrary.org/obo/hp/hp-international.owl\n  NCIT: http://purl.obolibrary.org/obo/ncit.owl\n  DOID: http://purl.obolibrary.org/obo/doid.owl\n  MEDDRA: http://purl.obolibrary.org/obo/meddra.owl\n  DRUGBANK: http://purl.obolibrary.org/obo/DRUGBANK_\n  drug: http://w3id.org/ontogpt/drug/\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - ontogpt:core\n  - linkml:types\n\nclasses:\n\n  ChemicalInducesDiseaseRelationship:\n    is_a: Triple\n    description: A triple where the subject is a chemical and the object is a disease.\n    slot_usage:\n      subject:\n        range: Chemical\n      object:\n        range: Disease\n      predicate:\n        range: ChemicalInducesDiseasePredicate\n\n  ChemicalInducesDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ChemicalInducesDisease relationships.\n      id:\n        pattern: ''induces''\n\n  ChemicalIsSubstanceThatTreatsDiseaseRelationship:\n    is_a: Triple\n    description: A triple where the subject is a chemical and the object is a disease.\n    slot_usage:\n      subject:\n        range: Chemical\n      object:\n        range: Disease\n      predicate:\n        range: ChemicalIsSubstanceThatTreatsDiseasePredicate\n      subject_qualifier:\n        description: >-\n          An optional qualifier or modifier for the chemical, e.g. "high dose" or "intravenously administered"\n        range: string\n      object_qualifier:\n        description: >-\n          An optional qualifier or modifier for the disease, e.g. "severe" or "with additional complications"\n        range: string\n  \n  ChemicalIsSubstanceThatTreatsDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the ChemicalIsSubstanceThatTreatsDisease relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations: \n      annotators: sqlite:obo:ro\n\n  Disease:\n    is_a: NamedEntity\n    description: The disease or condition that is being treated or induced by the chemical.\n    attributes:\n      id:\n        description: The unique identifier for the disease entity.\n        range: MeshDiseaseIdentifierType\n        required: true\n        identifier: true\n    id_prefixes:\n      - MESH\n      - MONDO\n      - HP\n      - NCIT\n      - DOID\n      - MEDDRA\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:ncit, sqlite:obo:doid, bioportal:meddra\n      prompt.examples: cardiac asystole, COVID-19, Headache, cancer, asthma, Hypotension\n\n  Chemical:\n    is_a: NamedEntity\n    description: The chemical substance, drug, or small molecule.\n    attributes:\n      id:\n        description: The unique identifier for the chemical entity.\n        range: MeshChemicalIdentifierType\n        required: true\n        identifier: true\n    id_prefixes:\n      - MESH\n      - CHEBI\n      - NCIT\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:chebi, sqlite:obo:ncit, sqlite:obo:drugbank, bioportal:mdm\n      prompt.examples: Lidocaine, Hydroxychloroquine, Methyldopa, Imatinib, Monosodium Glutamate\n\nenums:\n  MeshChemicalIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D000602 ## Amino Acids, Peptides, and Proteins\n        - MESH:D001685 ## Biological Factors\n        - MESH:D002241 ## Carbohydrates\n        - MESH:D004364 ## Pharmaceutical Preparations\n        - MESH:D006571 ## Heterocyclic Compounds\n        - MESH:D007287 ## Inorganic Chemicals\n        - MESH:D008055 ## Lipids\n        - MESH:D009706 ## Nucleic Acids, Nucleotides, and Nucleosides\n        - MESH:D009930 ## Organic Chemicals\n        - MESH:D011083 ## Polycyclic Compounds\n        - MESH:D013812 ## Therapeutics\n        - MESH:D019602 ## Food and Beverages\n        - MESH:D045424 ## Complex Mixtures\n        - MESH:D045762 ## Enzymes and Coenzymes\n        - MESH:D046911 ## Macromolecular Substances\n  MeshDiseaseIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D001423 ## Bacterial Infections and Mycoses\n        - MESH:D001523 ## Mental Disorders\n        - MESH:D002318 ## Cardiovascular Diseases\n        - MESH:D002943 ## Circulatory and Respiratory Physiological Phenomena\n        - MESH:D004066 ## Digestive System Diseases\n        - MESH:D004700 ## Endocrine System Diseases\n        - MESH:D005128 ## Eye Diseases\n        - MESH:D005261 ## Female Urogenital Diseases and Pregnancy Complications\n        - MESH:D006425 ## Hemic and Lymphatic Diseases\n        - MESH:D007154 ## Immune System Diseases\n        - MESH:D007280 ## Disorders of Environmental Origin\n        - MESH:D009057 ## Stomatognathic Diseases\n        - MESH:D009140 ## Musculoskeletal Diseases\n        - MESH:D009358 ## Congenital, Hereditary, and Neonatal Diseases and Abnormalities\n        - MESH:D009369 ## Neoplasms\n        - MESH:D009422 ## Nervous System Diseases\n        - MESH:D009750 ## Nutritional and Metabolic Diseases\n        - MESH:D009784 ## Occupational Diseases\n        - MESH:D010038 ## Otorhinolaryngologic Diseases\n        - MESH:D010272 ## Parasitic Diseases\n        - MESH:D012140 ## Respiratory Tract Diseases\n        - MESH:D013568 ## Pathological Conditions, Signs and Symptoms\n        - MESH:D014777 ## Virus Diseases\n        - MESH:D014947 ## Wounds and Injuries\n        - MESH:D017437 ## Skin and Connective Tissue Diseases\n        - MESH:D052801 ## Male Urogenital Diseases\n        - MESH:D064419 ## Chemically-Induced Disorders\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(443,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(443,'source','ctd_ner.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(443,'content',replace('id: http://w3id.org/ontogpt/ctd_ner\ndefault_range: string\nname: ctd_ner\ntitle: Chemical and Disease Entity Recognition Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for Chemical and Disease named entity recognition.\n\n  This template is intended to represent entities (chemicals and diseases),\n  and for evaluating SPIRES against the BioCreative V Disease Named Entity\n  Recognition (DNER) results. As the test set also contains chemical names,\n  it is also appropriate to use this template for evaluating chemical NER.\nsee_also:\n  - https://biocreative.bioinformatics.udel.edu/media/store/files/2015/BC5CDR_overview.final.pdf\n  - https://academic.oup.com/database/article/doi/10.1093/database/baw068/2630414\nsource: >-\n  https://biocreative.bioinformatics.udel.edu/tasks/biocreative-v/track-3-cdr/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  MESH: http://identifiers.org/mesh/\n  ctdner: http://w3id.org/ontogpt/ctd_ner\n  linkml: https://w3id.org/linkml/\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  ChemicalDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Chemical\n      object:\n        range: Disease\n      predicate:\n        range: ChemicalDiseasePredicate\n  \n  ChemicalDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ChemicalDisease relationships.\n\n  Chemical:\n    is_a: NamedEntity\n    description: A chemical substances, drug, or small molecule.\n    attributes:\n      id:\n        range: MeshChemicalIdentifierType\n        identifier: true\n        required: true\n    id_prefixes:\n      - MESH\n      - CHEBI\n      - NCIT\n      - DRUGBANK\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:chebi, sqlite:obo:ncit, bioportal:mdm, sqlite:obo:drugbank\n      prompt.examples: Lidocaine, Hydroxychloroquine, Methyldopa, Monosodium Glutamate, Imatinib\n\n  Disease:\n    is_a: NamedEntity\n    description: A disease or condition.\n    attributes:\n      id:\n        range: MeshDiseaseIdentifierType\n        identifier: true\n        required: true\n    id_prefixes:\n      - MESH\n      - MONDO\n      - HP\n      - NCIT\n      - DOID\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:mondo, sqlite:obo:hp, sqlite:obo:ncit, sqlite:obo:doid, bioportal:meddra\n      prompt.examples: cardiac asystole, COVID-19, Hypotension, Headache, cancer\n\nenums:\n  MeshChemicalIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D000602 ## Amino Acids, Peptides, and Proteins\n        - MESH:D001685 ## Biological Factors\n        - MESH:D002241 ## Carbohydrates\n        - MESH:D004364 ## Pharmaceutical Preparations\n        - MESH:D006571 ## Heterocyclic Compounds\n        - MESH:D007287 ## Inorganic Chemicals\n        - MESH:D008055 ## Lipids\n        - MESH:D009706 ## Nucleic Acids, Nucleotides, and Nucleosides\n        - MESH:D009930 ## Organic Chemicals\n        - MESH:D011083 ## Polycyclic Compounds\n        - MESH:D013812 ## Therapeutics\n        - MESH:D019602 ## Food and Beverages\n        - MESH:D045424 ## Complex Mixtures\n        - MESH:D045762 ## Enzymes and Coenzymes\n        - MESH:D046911 ## Macromolecular Substances\n  MeshDiseaseIdentifierType:\n    reachable_from:\n      source_ontology: obo:mesh\n      source_nodes:\n        - MESH:D001423 ## Bacterial Infections and Mycoses\n        - MESH:D001523 ## Mental Disorders\n        - MESH:D002318 ## Cardiovascular Diseases\n        - MESH:D002943 ## Circulatory and Respiratory Physiological Phenomena\n        - MESH:D004066 ## Digestive System Diseases\n        - MESH:D004700 ## Endocrine System Diseases\n        - MESH:D005128 ## Eye Diseases\n        - MESH:D005261 ## Female Urogenital Diseases and Pregnancy Complications\n        - MESH:D006425 ## Hemic and Lymphatic Diseases\n        - MESH:D007154 ## Immune System Diseases\n        - MESH:D007280 ## Disorders of Environmental Origin\n        - MESH:D009057 ## Stomatognathic Diseases\n        - MESH:D009140 ## Musculoskeletal Diseases\n        - MESH:D009358 ## Congenital, Hereditary, and Neonatal Diseases and Abnormalities\n        - MESH:D009369 ## Neoplasms\n        - MESH:D009422 ## Nervous System Diseases\n        - MESH:D009750 ## Nutritional and Metabolic Diseases\n        - MESH:D009784 ## Occupational Diseases\n        - MESH:D010038 ## Otorhinolaryngologic Diseases\n        - MESH:D010272 ## Parasitic Diseases\n        - MESH:D012140 ## Respiratory Tract Diseases\n        - MESH:D013568 ## Pathological Conditions, Signs and Symptoms\n        - MESH:D014777 ## Virus Diseases\n        - MESH:D014947 ## Wounds and Injuries\n        - MESH:D017437 ## Skin and Connective Tissue Diseases\n        - MESH:D052801 ## Male Urogenital Diseases\n        - MESH:D064419 ## Chemically-Induced Disorders\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(444,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(444,'source','datasheet.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(444,'content',replace('id: http://w3id.org/ontogpt/datasheet\ndefault_range: string\nname: datasheet\ntitle: Datasheet Extraction Template\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\ndescription: >-\n  A template for extracting metadata about a dataset,\n  as defined by the Datasheets for Datasets model\n  (see https://github.com/bridge2ai/data-sheets-schema),\n  itself based on Gebru et al. (2021)\n  (https://cacm.acm.org/magazines/2021/12/256932-datasheets-for-datasets/abstract)\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  d4d: http://w3id.org/ontogpt/datasheet\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  DatasetFundedByOrganizationRelationship:\n    is_a: Triple\n    description: List of organizations supporting creation of the dataset.\n    slot_usage:\n      subject:\n        range: Dataset\n      object:\n        range: Organization\n      predicate:\n        range: DatasetFundedByOrganizationPredicate\n\n  DatasetFundedByOrganizationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DatasetFundedByOrganization relationships.\n      id:\n        pattern: ''funded by''\n\n  Dataset:\n    is_a: NamedEntity\n    description: A document that contains a description of a dataset.\n    attributes:\n      name:\n        description: The name of the dataset.\n      subsets:\n        description: >-\n          List of names of any subsets of the dataset.\n        multivalued: true\n      authors:\n        description: >-\n          List of names of creators of the dataset.\n        multivalued: true\n      funding_identifiers:\n        description: >-\n          List of names, numbers, or other\n          identifiers for grants supporting creation of the dataset.\n        multivalued: true\n      purpose:\n        description: >-\n          The stated purpose of the dataset. This should be no more than 1\n          sentence.\n      limitations:\n        description: >-\n          Known limitations of the dataset. This should be no more than 1\n          sentence.\n      warnings:\n        description: >-\n          Warnings regarding content or application of the dataset.\n      references:\n        description: >-\n          List of publications describing the data or the\n          process used to produce it.\n        multivalued: true\n      license:\n        description: >-\n          The set of rules defining the rights of the developer and the users\n          of the dataset.\n        annotations:\n          prompt.examples: BSD-3, CC0\n  \n  Organization:\n    is_a: NamedEntity\n    id_prefixes:\n      - NCIT\n    annotations:\n      annotators: sqlite:obo:ncit\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(445,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(445,'source','data_sheets_schema.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(445,'content',replace('---\nid: https://w3id.org/bridge2ai/data-sheets-schema\nname: data-sheets-schema\ntitle: data-sheets-schema\ndescription: |-\n  A LinkML schema for Datasheets for Datasets.\nlicense: MIT\nsee_also:\n  - https://bridge2ai.github.io/data-sheets-schema\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  biolink: https://w3id.org/biolink/\n  csvw: http://www.w3.org/ns/csvw#\n  data_sheets_schema: https://w3id.org/bridge2ai/data-sheets-schema/\n  datasets: https://w3id.org/linkml/report\n  dcat: http://www.w3.org/ns/dcat#\n  example: https://example.org/\n  formats: http://www.w3.org/ns/formats/\n  frictionless: https://specs.frictionlessdata.io/\n  linkml: https://w3id.org/linkml/\n  mediatypes: https://www.iana.org/assignments/media-types/\n  pav: http://purl.org/pav/\n  schema: http://schema.org/\n  sh: https://w3id.org/shacl/\n  skos: http://www.w3.org/2004/02/skos/core#\n  void: http://rdfs.org/ns/void#\ndefault_prefix: data_sheets_schema\ndefault_range: string\n\nimports:\n  - linkml:types\n\nclasses:\n\n  PersonOrganizationRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Person\n      object:\n        range: Organization\n      predicate:\n        range: PersonOrganizationPredicate\n\n  PersonOrganizationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the PersonOrganization relationships.\n\n  Person:\n    is_a: NamedEntity\n    description: An individual human being.\n    attributes:\n      email:\n        description: The email address of the person.\n        identifier: true\n        required: true\n        pattern: ''^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$''\n\n  Organization:\n    description: A collection of people acting in common interests.\n    is_a: NamedEntity\n    attributes:\n      email:\n        description: The email address of the organization.\n        identifier: true\n        required: true\n        pattern: ''^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$''\n      ror_id:\n        description: Unique ROR identifier.\n        required: true\n      wikidata_id:\n        description: Unique Wikidata identifier.\n        required: true\n\n  Software:\n    description: >-\n      A software program or library.\n    is_a: NamedEntity\n    attributes:\n      version:\n        range: string\n      license:\n        range: string\n      url:\n        range: string\n\n  File:\n    is_a: NamedEntity\n    description: A file or set of files.\n    attributes:\n      uri:\n        description: >-\n          A unique resource identifier (URI) for the file.\n          This may be a file path (beginning with file://) or URL.\n        range: string\n        identifier: true\n        required: true\n      file_attributes:\n        range: string\n        multivalued: true\n\n  Creator:\n    is_a: Person\n\n  Maintainer:\n    is_a: Person','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(446,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(446,'source','desiccation.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(446,'content',replace('id: http://w3id.org/ontogpt/desiccation\n\ndefault_range: string\n\nname: desiccation\n\ntitle: desiccationTemplate\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for extracting ChEBI, GO, NCBITAXON, PO, TO, PECO\n\nprefixes:\n  PECO: http://purl.obolibrary.org/obo/peco.owl\n  NCBITAXON: http://purl.obolibrary.org/obo/ncbitaxon.owl\n  TO: http://purl.obolibrary.org/obo/to.owl\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  desiccation: http://w3id.org/ontogpt/desiccation\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  EnvironmentalCondition:\n    is_a: NamedEntity\n    description: The name of an environmental treatment.\n    id_prefixes:\n      - PECO\n    annotations:\n      annotators: sqlite:obo:peco\n      prompt.examples: drought, salt stress, cold tolerance\n\n  Taxon:\n    is_a: NamedEntity\n    description: The name of a taxonomic name or species.\n    id_prefixes:\n      - NCBITaxon\n    annotations:\n      annotators: sqlite:obo:ncbitaxon\n      prompt.examples: Bacillus subtilus, Bos taurus, blue whale\n\n  Trait:\n    is_a: NamedEntity\n    description: The description of a plant trait.\n    id_prefixes:\n      - TO\n    annotations:\n      annotators: sqlite:obo:to\n      prompt.examples: germination ratio, fruit hollowness, arid region exposure\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(447,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(447,'source','diagnostic_procedure.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(447,'content',replace('id: http://w3id.org/ontogpt/diagnostic_procedure\nname: diagnostic_procedure\ntitle: Diagnostic Procedure Template\ndescription: >-\n  A template for clinical diagnostic procedures and the\n  phenotypes they may contribute to.\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  HP: http://purl.obolibrary.org/obo/HP_\n  LOINC: http://loinc.org/rdf/\n  OBA: http://purl.obolibrary.org/obo/OBA_\n  PATO: http://purl.obolibrary.org/obo/PATO_\n  RO: http://purl.obolibrary.org/obo/RO_\n  UO: http://purl.obolibrary.org/obo/UO_\n  biolink: https://w3id.org/biolink/vocab/\n  diag: http://w3id.org/ontogpt/diagnostic_procedure/\n  linkml: https://w3id.org/linkml/\n\ndefault_prefix: diag\ndefault_range: string\n\nimports:\n  - linkml:types\n  - core\n\n# TODO: LOINC isn''t great for grounding,\n# but perhaps a combo of subject, unit, and qualifier would work\n# since LOINC names are often like "IgG [Units/volume] in Serum"\n\nclasses:\n  DiagnosticProceduretoPhenotypeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DiagnosticProcedure\n      object:\n        range: Phenotype\n      predicate:\n        range: ProcedureToPhenotypePredicate\n\n  DiagnosticProcedureToClinicalAttributeRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DiagnosticProcedure\n      object:\n        range: ClinicalAttribute\n      predicate:\n        range: DiagnosticProcedureToClinicalAttributePredicate\n\n  DiagnosticProcedure:\n    is_a: NamedEntity\n    annotations:\n      annotators: bioportal:loinc, sqlite:obo:ncit\n    id_prefixes:\n      - LOINC\n\n  Phenotype:\n    is_a: NamedEntity\n    annotations:\n      annotators: sqlite:obo:hp\n    id_prefixes:\n      - HP\n\n  ClinicalAttributeUnitRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalAttribute\n      object:\n        range: Unit\n      predicate:\n        range: ClinicalAttributeUnitPredicate\n\n  ClinicalAttributeUnitPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalAttributeUnit relationships.\n\n  ClinicalAttribute:\n    is_a: NamedEntity\n    annotations:\n      annotators: sqlite:obo:oba, sqlite:obo:ncit\n    id_prefixes:\n      - OBA\n\n  Quality:\n    is_a: NamedEntity\n    annotations:\n      annotators: sqlite:obo:pato\n    id_prefixes:\n      - PATO\n\n  ProcedureToPhenotypePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ProcedureToPhenotype relationships.\n\n  DiagnosticProcedureToClinicalAttributePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DiagnosticProcedureToClinicalAttribute relationships.\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n    annotations:\n      annotators: sqlite:obo:uo\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(448,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(448,'source','dietitian_notes.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(448,'content',replace('id: http://w3id.org/ontogpt/dietician_notes\nname: dietitian_notes\ntitle: Dietitian Notes Extraction Template\ndescription: >-\n  A template for extracting clinical observations from dietitian notes.\n  Developed with guidance from Lauren Chan, PhD, RD\n  and Alyson Lawrence, RD, CNSC\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  EFO: http://www.ebi.ac.uk/efo/EFO_\n  FOODON: http://purl.obolibrary.org/obo/FOODON_\n  HP: http://purl.obolibrary.org/obo/HP_\n  MAXO: http://purl.obolibrary.org/obo/MAXO_\n  MONDO: http://purl.obolibrary.org/obo/MONDO_\n  UO: http://purl.obolibrary.org/obo/UO_\n  dietician_notes: http://w3id.org/ontogpt/dietitian_notes\n  linkml: https://w3id.org/linkml/\n\ndefault_prefix: dietitian_notes\ndefault_range: string\n\n# TODO: address extracted chunks that are too large\n# TODO: find additional grounding strategies\n# TODO: provide additional examples for each class\n\nimports:\n  - linkml:types\n  - core\n\nclasses:\n\n  ClinicalObservation:\n    description: >-\n      A clinical observation about a single patient at a single time.\n    is_a: NamedEntity\n    attributes:\n      is_pediatric:\n        description: >-\n            True if the patient is a child, False otherwise.\n        range: boolean\n      is_preterm:\n        description: >-\n            True if the patient''s birth was preterm, False otherwise.\n            A birth before 37 weeks gestation is preterm.\n        range: boolean\n      patient_age:\n        description: >-\n            The patient''s age at the time of the current assessment.\n        range: integer\n      patient_height:\n        description: >-\n            The patient''s height at the time of the current assessment in centimeters.\n        range: integer\n      current_patient_weight:\n        description: >-\n            The value and units of the patient''s actual body weight at the time\n            of the current assessment in kilograms. \n        range: float\n      usual_patient_weight:\n        description: >-\n            The value and units of the patient''s body weight under usual\n            conditions and/or in the recent past in kilograms.\n        range: float\n      head_circumference:\n        description: >-\n            The value and units of the patient''s head circumference in centimeters.\n            Usually abbreviated as "HC".\n        range: integer\n      malnutrition_status:\n        description: >-\n          Observations of the patient''s malnutrition status.\n        range: boolean\n      nil_per_os:\n        description: >-\n          True if the patient is not receiving any oral nutrition,\n          False otherwise.\n        range: boolean\n\n  ClinicalObservationDietSupplementationRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalObservation\n      object:\n        range: DietSupplementation\n      predicate:\n        range: ClinicalObservationDietSupplementationPredicate\n  \n  ClinicalObservationDietSupplementationPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalObservationDietSupplementation relationships.\n\n  ClinicalObservationNutritionSupportRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalObservation\n      object:\n        range: NutritionSupport\n      predicate:\n        range: ClinicalObservationNutritionSupportPredicate\n\n  ClinicalObservationNutritionSupportPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalObservationNutritionSupport relationships.\n\n  ClinicalObservationDrugTherapyRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: ClinicalObservation\n      object:\n        range: DrugTherapy\n      predicate:\n        range: ClinicalObservationDrugTherapyPredicate\n\n  ClinicalObservationDrugTherapyPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the ClinicalObservationDrugTherapy relationships.\n\n  DietSupplementationTherapeuticMaterialRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DietSupplementation\n      object:\n        range: TherapeuticMaterial\n      predicate:\n        range: DietSupplementationTherapeuticMaterialPredicate\n\n  DietSupplementationTherapeuticMaterialPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DietSupplementationTherapeuticMaterial relationships.\n\n  DietSupplementation:\n    is_a: NamedEntity\n    attributes:\n      amount:\n        description: >-\n          The quantity or dosage of the therapy in milligrams.\n        range: integer\n      dosage_by_unit:\n        description: >-\n          The unit of a patient''s properties used to determine supplement\n          dosage in milligrams.\n        range: integer\n      duration:\n        description: >-\n          The duration of the supplementation in days.\n        range: integer\n      route_of_administration:\n        description: >-\n          The route of administration for the supplementation.\n        range: string\n\n  TherapeuticMaterial:\n    is_a: NamedEntity\n    description: >-\n      A specific material added to a patient''s diet or\n      included as part of a nutritional plan.\n    id_prefixes:\n      - FOODON\n      - MAXO\n      - EFO\n    annotations:\n      annotators: sqlite:obo:foodon, sqlite:obo:chebi, sqlite:obo:maxo, sqlite:obo:efo, sqlite:obo:mesh\n      prompt.examples: >-\n        sugar, amino acids, single vitamin supplement,\n        ginkgo biloba supplement, multi-mineral supplement,\n        biotin supplementation, glucosamine supplementation\n\n  NutritionSupport:\n    is_a: NamedEntity\n    attributes:\n      method:\n        description: >-\n          The name of a method used to provide nutritional support.\n        range: string\n      components:\n        description: >-\n          The names of specific components included in a patient''s diet.\n        range: string\n        multivalued: true\n\n  DrugTherapyDrugRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: DrugTherapy\n      object:\n        range: Drug\n      predicate:\n        range: DrugTherapyDrugPredicate\n\n  DrugTherapyDrugPredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DrugTherapyDrug relationships.\n\n  DrugTherapy:\n    is_a: NamedEntity\n    attributes:\n      amount:\n        description: >-\n          The quantity or dosage of the drug in milligrams.\n        range: integer\n      dosage_by_unit:\n        description: >-\n          The unit of a patient''s properties used to determine drug\n          dosage in kilograms.\n        range: integer\n      duration:\n        description: >-\n          The duration of the drug therapy in days.\n        range: integer\n      route_of_administration:\n        description: >-\n          The route of administration for the drug therapy.\n        range: string\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n      - EFO\n    annotations:\n      annotators: sqlite:obo:mondo, sqlite:obo:mesh, sqlite:obo:efo\n      prompt.examples: cardiac asystole, COVID-19, Headache, cancer\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - DRUGBANK\n      - CHEBI\n      - MESH\n    annotations:\n      annotators: sqlite:obo:drugbank, sqlite:obo:chebi, sqlite:obo:mesh\n      prompt.examples: >-\n        acetaminophen, ibuprofen, furosemide, insulin, heparin, warfarin\n\n  Unit:\n    is_a: NamedEntity\n    id_prefixes:\n      - UO\n      - NCIT\n      - FOODON\n    annotations:\n      annotators: sqlite:obo:uo, sqlite:obo:ncit, sqlite:obo:foodon','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(449,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(449,'source','drug.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(449,'content',replace('id: http://w3id.org/ontogpt/drug\n\ndefault_range: string\n\nname: drug\n\ntitle: Drug Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for Drugs and drug mechanism\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  CL: http://purl.obolibrary.org/obo/cl.owl\n  GO: http://purl.obolibrary.org/obo/go/extensions/go-plus.owl\n  NCBITAXON: http://purl.obolibrary.org/obo/ncbitaxon.owl\n  PR: http://purl.obolibrary.org/obo/pr.owl\n  UBERON: http://purl.obolibrary.org/obo/uberon.owl\n  MESH: https://w3id.org/biopragmatics/resources/mesh/mesh.owl.gz\n  MONDO: https://purl.obolibrary.org/obo/mondo/mondo-international.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  MechanismElementMechanismElementRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: MechanismElement\n      object:\n        range: MechanismElement\n      predicate:\n        range: MechanismElementMechanismElementPredicate\n      references:\n        multivalued: true\n        range: string\n        annotations:\n          prompt.skip: "true"\n      source_text:\n        range: string\n        annotations:\n          prompt.skip: "true"\n  \n  MechanismElementMechanismElementPredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - BIOLINK\n      - RO\n    attributes:\n      label:\n        description: The predicate for the chemical to MechanismElementMechanismElement relationships.\n    annotations:\n      annotators: sqlite:obo:biolink, sqlite:obo:ro\n  \n  MechanismElement:\n    is_a: NamedEntity\n    id_prefixes:\n      - GO\n      - MESH\n      - UBERON\n      - PR\n      - NCBITaxon\n      - CL\n    annotations:\n      annotators: sqlite:obo:go, sqlite:obo:mesh, sqlite:obo:uberon, sqlite:obo:pr, sqlite:obo:ncbitaxon, sqlite:obo:cl\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MESH\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mesh, sqlite:obo:mondo\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - DRUGBANK\n      - CHEBI\n      - MESH\n    annotations:\n      annotators: sqlite:obo:drugbank, sqlite:obo:chebi, sqlite:obo:mesh\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(450,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(450,'source','drug_to_disease.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(450,'content',replace('id: http://w3id.org/ontogpt/drug\n\ndefault_range: string\n\nname: drug_to_disease\n\ntitle: Drug to Disease Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  A template for extracting relationships between drugs and diseases\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  MONDO: https://purl.obolibrary.org/obo/mondo/mondo-international.owl\n  CHEBI: http://purl.obolibrary.org/obo/chebi.owl\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n\n  DrugPreventsDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Drug\n      object:\n        range: Disease\n      predicate:\n        range: DrugPreventsDiseasePredicate\n\n  DrugPreventsDiseasePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the DrugPreventsDisease relationships.\n      id:\n        pattern: ''prevents''\n\n  DrugIsSubstanceThatTreatsDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Drug\n      object:\n        range: Disease\n      predicate:\n        range: DrugIsSubstanceThatTreatsDiseasePredicate\n\n  DrugIsSubstanceThatTreatsDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DrugIsSubstanceThatTreatsDisease relationships.\n      id:\n        pattern: ''is substance that treats''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  DrugCausesOrContributesToConditionDiseaseRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Drug\n      object:\n        range: Disease\n      predicate:\n        range: DrugCausesOrContributesToConditionDiseasePredicate\n\n  DrugCausesOrContributesToConditionDiseasePredicate:\n    is_a: RelationshipType\n    id_prefixes:\n      - RO\n    attributes:\n      label:\n        description: The predicate for the DrugCausesOrContributesToConditionDisease relationships.\n      id:\n        pattern: ''causes or contributes to condition''\n    annotations:\n      annotators: sqlite:obo:ro\n\n  Disease:\n    is_a: NamedEntity\n    id_prefixes:\n      - MONDO\n    annotations:\n      annotators: sqlite:obo:mondo\n\n  Drug:\n    is_a: NamedEntity\n    id_prefixes:\n      - DRUGBANK\n      - CHEBI\n    annotations:\n      annotators: sqlite:obo:drugbank, sqlite:obo:chebi\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(451,'type','txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(451,'source','ecosim_methods.txt',NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(451,'content',replace('id: http://w3id.org/ontogpt/ecosim_methods\n\ndefault_range: string\n\nname: ecosim_methods\n\ntitle: EcoSIM Methods Extraction Template\n\nlicense: https://creativecommons.org/publicdomain/zero/1.0/\n\ndescription: >-\n  EcoSIM Methods Extraction Template\n\nprefixes:\n  rdf: http://www.w3.org/1999/02/22-rdf-syntax-ns#\n  linkml: https://w3id.org/linkml/\n  ecosim_simple: http://w3id.org/ontogpt/ecosim_simple\n  ecosim: http://purl.obolibrary.org/obo/ecosim\n\nimports:\n  - linkml:types\n  - ontogpt:core\n\nclasses:\n  EquipmentMeasuresVariableRelationship:\n    is_a: Triple\n    slot_usage:\n      subject:\n        range: Equipment\n      object:\n        range: Variable\n      predicate:\n        range: EquipmentVariablePredicate\n    annotations:\n      prompt.examples: >-\n        NMR spectrometer was used to measure\n        chemical content\n  \n  EquipmentMeasuresVariablePredicate:\n    is_a: RelationshipType\n    attributes:\n      label:\n        description: The predicate for the chemical to EquipmentMeasuresVariable relationships.\n      id:\n        pattern: ''measures''\n  \n  Location:\n    is_a: NamedEntity\n    description: The name of a location used in research.\n    annotations:\n      prompt.examples: Vermont, New York City, Ethiopia\n\n  Method:\n    is_a: NamedEntity\n    description: >-\n      The name of a method used in environment and\n      earth science research.\n    annotations:\n      annotators: bioportal:ECOSIM\n      prompt.examples: sampling, spectroscopy\n\n  Variable:\n    is_a: NamedEntity\n    description: >-\n      The name of a variable measured in environment and\n      earth science research.\n    annotations:\n      annotators: bioportal:ECOSIM\n      prompt.examples: root shape, biomass, water turbidity\n\n  Equipment:\n    is_a: NamedEntity\n    description: >-\n      The name of a piece of equipment used in\n      environment and earth science research.\n','\n',char(10)),NULL,NULL,NULL);
INSERT INTO embedding_metadata VALUES(452,'type','txt',NULL,NULL,NULL);
